// Obtener fecha local como YYYY-MM-DD considerando turno de planta.
// El "día laboral" inicia a las 6:30 AM — una actividad entre 00:00 y 06:29
// pertenece al día anterior (tercer turno del día previo).
function fechaLocal(ts){
  var d = new Date(ts||Date.now());
  var h = d.getHours();
  var m = d.getMinutes();
  // Si es antes de las 6:30 AM, pertence al día laboral anterior
  if(h < 6 || (h === 6 && m < 30)){
    d.setDate(d.getDate() - 1);
  }
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

// Semana laboral: inicia lunes 6:30 AM, termina lunes siguiente 6:30 AM
function semanaLaboral(ts){
  var fecha = fechaLocal(ts);
  var d = new Date(fecha + 'T12:00:00');
  return getWeekNumber(d);
}

