// Pre-llenar gasto objetivo $100,000/semana hasta fin de año si no existe
(function(){
  var año = currentYear();
  var metaSemanal = 100000; // $100,000 por semana
  var cambiado = false;
  for(var sem=1; sem<=52; sem++){
    var existe = GASTO_DATA.find(function(g){return g.semana===sem && g.año===año;});
    if(!existe){
      GASTO_DATA.push({semana:sem, año:año, planeado:metaSemanal, real:0, ts:Date.now()});
      cambiado = true;
    } else if(!existe.planeado || existe.planeado===0){
      existe.planeado = metaSemanal;
      cambiado = true;
    }
  }
  if(cambiado){
    saveDB('gasto_data', GASTO_DATA);
    // Sync a Supabase los registros nuevos
    GASTO_DATA.forEach(function(g){
      if(!g._synced){
        supaUpsert('gasto_data',{semana:g.semana,año:g.año,planeado:g.planeado,real:g.real||0}).catch(function(){});
        g._synced=true;
      }
    });
  }
})();
