function showScreen(id){
  // Guardar scroll de pantalla activa antes de cambiar
  var prev=document.querySelector('.screen.active');
  if(prev&&prev.id&&prev.id!==id){
    var sc=prev.querySelector('.scroll-content')||prev;
    saveDB('scroll_pos_'+prev.id, sc.scrollTop);
  }
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  var el=document.getElementById(id);if(el)el.classList.add('active');
  window.scrollTo(0,0);
  // Restaurar scroll — retry hasta que el elemento acepte el valor
  var pos=loadDB('scroll_pos_'+id,0);
  if(pos>0){
    var tries=0;
    (function tryRestore(){
      var dest=document.getElementById(id);
      if(!dest){if(tries++<5)setTimeout(tryRestore,60);return;}
      var sc=dest.querySelector('.scroll-content')||dest;
      sc.scrollTop=pos;
      setTimeout(function(){
        if(Math.abs(sc.scrollTop-pos)>5&&tries++<6) setTimeout(tryRestore,80);
      },40);
    })();
  }
}
function getWeekNumber(d){d=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=new Date(Date.UTC(d.getUTCFullYear(),0,1));return Math.ceil((((d-y)/86400000)+1)/7);}
function currentWeek(){return getWeekNumber(new Date());}
function currentYear(){return new Date().getFullYear();}
function getWeeksInMonth(y,m){
  // Contar cuántos días de cada semana caen en este mes
  var conteo={};
  var d=new Date(y,m-1,1);
  while(d.getMonth()===m-1){
    var w=getWeekNumber(new Date(d));
    conteo[w]=(conteo[w]||0)+1;
    d.setDate(d.getDate()+1);
  }
  // Solo incluir semanas donde la MAYORÍA (>=4) de días están en este mes
  return Object.keys(conteo)
    .map(Number)
    .filter(function(w){return conteo[w]>=4;})
    .sort(function(a,b){return a-b;});
}
function diffMin(a,b){if(!a||!b)return null;const pa=a.split(':').map(Number),pb=b.split(':').map(Number);let d=(pb[0]*60+pb[1])-(pa[0]*60+pa[1]);if(d<0)d+=1440;return d;}
function comprimirImagen(file,cb){
  const r=new FileReader();r.onload=e=>{const img=new Image();img.onload=()=>{const M=800;let w=img.width,h=img.height;if(w>M){h=Math.round(h*M/w);w=M;}if(h>M){w=Math.round(w*M/h);h=M;}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);cb(c.toDataURL('image/jpeg',.6));};img.src=e.target.result;};r.readAsDataURL(file);
}
function nowTimeStr(){var n=new Date();return String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');}
function todayStr(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}

