// MIS ÓRDENES
// ================================================================
function showMisOrdenes(){detalleBackScreen='screen-ordenes';renderMisOrdenes();showScreen('screen-ordenes');}

function buildFiltrosPendientes(){
  const isAdmin=currentUser.rol==='admin';
  const tecs=USERS.filter(u=>u.rol==='tecnico');
  return`<div class="filter-row"><div class="filter-chip active" onclick="setFP('estado','todos',this)">Todos</div><div class="filter-chip" onclick="setFP('estado','abierta',this)">Abiertas</div><div class="filter-chip" onclick="setFP('estado','cerrada',this)">Cerradas</div></div>
  <div class="filter-row"><div class="filter-chip active" onclick="setFP('tipo','todas',this)">Todos tipos</div><div class="filter-chip" onclick="setFP('tipo','PM01',this)">PM01</div><div class="filter-chip" onclick="setFP('tipo','PM02',this)">PM02</div><div class="filter-chip" onclick="setFP('tipo','PM03',this)">PM03</div><div class="filter-chip" onclick="setFP('tipo','PM04',this)">PM04</div><div class="filter-chip" onclick="setFP('tipo','temporal',this)" style="border-color:#F59E0B;color:#B45309">⚡ Temporal</div></div>
  <div class="filter-row"><div class="filter-chip active" onclick="setFP('color','todos',this)">Todos colores</div><div class="filter-chip" onclick="setFP('color','azul',this)">🔵 Azul</div><div class="filter-chip" onclick="setFP('color','rojo',this)">🔴 Rojo</div></div>
  <div class="filter-row"><div class="filter-chip active" onclick="setFP('prio','todas',this)">Toda prioridad</div><div class="filter-chip" onclick="setFP('prio','A',this)">Prio A</div><div class="filter-chip" onclick="setFP('prio','B',this)">Prio B</div><div class="filter-chip" onclick="setFP('prio','C',this)">Prio C</div></div>
  ${isAdmin?`<div class="form-group mb8"><label class="form-label">Por técnico</label><select class="form-control" id="fpen-tecnico" onchange="aplicarFiltrosPendientes()"><option value="">Todos los técnicos</option>${tecs.map(t=>`<option value="${t.id}">${t.nombre}</option>`).join('')}</select></div>`:''}`;
}
function renderOTCard(o){
  const pB={A:'badge-pA',B:'badge-pB',C:'badge-pC'};
  const cc=o.colorOT?`color-${o.colorOT}`:'';
  return`<div class="ot-card ${o.tipo.toLowerCase()} ${cc}" onclick="showDetalle('${o.id}')">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">
      <span style="font-size:11px;color:var(--txt3);font-weight:700">${o.id}</span>
      <div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end">
        <span class="badge badge-${o.tipo.toLowerCase()}">${o.tipo}</span>
        ${o.colorOT?`<span class="badge badge-${o.colorOT}">${o.colorOT==='azul'?'🔵':'🔴'} ${o.colorOT}</span>`:''}
        ${o.esResueltaTemporal?'<span class="badge" style="background:#F59E0B;color:#1a1a1a;font-size:10px;font-weight:800">⚡ TEMPORAL</span>':''}
        ${o.prioridad?`<span class="badge ${pB[o.prioridad]||'badge-pB'}">P${o.prioridad}</span>`:''}
        <span class="badge" style="background:${o.estado==='pre_cierre'?'#7c3aed':''};color:${o.estado==='pre_cierre'?'#fff':''}">${o.estado==='pre_cierre'?'⏳ Pendiente aprobación':o.estado}</span>
      </div>
    </div>
    <div style="font-family:'Nunito',sans-serif;font-size:15px;font-weight:800;margin:2px 0 4px">${o.linea} — ${o.componente}</div>
    <div style="font-size:12px;color:var(--txt2)">${o.area||''} · ${o.tipoAnormalidad||''}</div>
    <div style="font-size:12px;color:var(--txt2);margin-top:2px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.4">${(o.detalle||'')}</div>
    ${o.motivoRechazo?`<div style="background:#fee2e2;border-left:3px solid #dc2626;border-radius:6px;padding:5px 8px;margin-top:6px;font-size:11px;color:#dc2626;font-weight:700">❌ Rechazado: ${o.motivoRechazo.substring(0,60)}${o.motivoRechazo.length>60?'...':''}</div>`:''}
    <div style="display:flex;justify-content:space-between;margin-top:8px;font-size:11px;color:var(--txt3)">
      <span>👤 ${o.levantadoPor}</span><span>📅 ${fmtDate(o.ts)}</span>
    </div>
  </div>`;
}

// ================================================================
// DETALLE OT
// ================================================================
function showDetalle(id){
  const o=ORDENES.find(x=>x.id===id);
  if(!o){const p=PM03_PLAN.find(x=>x.id===id);if(p){showDetallePM03(id);return;}return;}
  var _activaD=document.querySelector('.screen.active');
  otCerrandoId=id;
  document.getElementById('detalle-topbar').textContent=id;
  const r=currentUser.rol;
  // Determinar si la PM02 roja fue levantada por operador/lider (requiere aprobación)
  const esAnomOperador = o.tipo==='PM02' && o.colorOT==='rojo' &&
    (o.rolLevantador!==null && o.rolLevantador!=='admin' && o.rolLevantador!=='super' && o.rolLevantador!=='tecnico' ||
     o.pendienteAsignacion===true ||
     USERS.find(function(u){return u.id===o.levantadoId&&u.rol!=='admin'&&u.rol!=='super'&&u.rol!=='tecnico';})!=null);
  // Si la orden fue rechazada, el técnico puede volver a dar pre-cierre
  const fueRechazada = !!(o.motivoRechazo);
  const estaEnPreCierre = o.estado==='pre_cierre';
  // Técnico puede: cerrar normales, o dar pre-cierre a anoms de operador
  const canClose=(r==='tecnico'||r==='admin')&&o.estado==='abierta'&&!esAnomOperador;
  // Puede dar pre-cierre si: es anom operador Y (está abierta O fue rechazada y volvió a abierta)
  const canPreCierre=(r==='tecnico'||r==='admin'||r==='super')&&o.estado==='abierta'&&esAnomOperador;
  const canCierreAdmin=(r==='admin'||r==='super')&&(o.estado==='abierta'||o.estado==='pre_cierre');
  const canCloseAzul=r==='operador'&&o.colorOT==='azul'&&o.levantadoId===currentUser.id&&o.estado!=='cerrada'&&o.estado!=='pre_cierre';
  const canAprobar=(r!=='admin'&&r!=='tecnico'||r==='super')&&estaEnPreCierre&&(o.levantadoId===currentUser.id||r==='super');
  const canReasign=(r==='tecnico'||r==='admin'||r==='lider'||r==='super')&&o.estado==='abierta';
  const canEditOwn=['operador','lider','lider_calidad','inspector_calidad','administrativo','supply'].indexOf(r)>=0&&o.levantadoId===currentUser.id&&o.estado==='abierta';
  var canDelete=(r==='super')||(o.levantadoId===currentUser.id&&o.estado==='abierta'&&['operador','lider','lider_calidad','inspector_calidad','administrativo','supply'].indexOf(r)>=0);
  // Edición completa: super sin límite, admin y técnico dentro de 7 días
  var _7dias=7*24*60*60*1000;
  var _edadOT=Date.now()-(o.ts||0);
  var canEditFull=(r==='super')||(r==='admin'&&o.estado==='abierta')||
    (r==='tecnico'&&o.tecnicoAsignado===currentUser.id&&_edadOT<_7dias);
  const pC={A:'var(--rj)',B:'var(--am2)',C:'var(--vd2)'};
  let hist='';
  if(o.historialReasignacion?.length)hist+=`<div class="card"><div class="card-title">🔄 Reasignaciones</div>${o.historialReasignacion.map(h=>`<div class="traza-box">📅 ${fmtDateTime(h.ts)}<br>Por: <b>${h.cambiadoPor}</b> | De: ${h.de} → ${h.a}<br>Motivo: ${h.motivo}</div>`).join('')}</div>`;
  hist+=`<div class="card"><div class="card-title">✏️ Modificaciones</div><div id="hist-mod-${o.id}"><div style="font-size:12px;color:var(--txt3);padding:8px">Cargando...</div></div></div>`;
  loadHistorialSupa(o.id).then(function(entries){var el=document.getElementById('hist-mod-'+o.id);if(!el)return;var local=o.historialModificacion||[];var all=entries.concat(local.filter(function(l){return!entries.find(function(e){return Math.abs((e.ts||0)-(l.ts||0))<2000&&e.por===l.por;});})).sort(function(a,b){return(a.ts||0)-(b.ts||0);});if(!all.length){el.innerHTML='<div style="font-size:12px;color:var(--txt3);padding:8px">Sin modificaciones</div>';return;}el.innerHTML=all.map(function(h){return'<div class="traza-box">📅 '+fmtDateTime(h.ts)+'<br>Por: <b>'+(h.por||'')+'</b> | '+(h.campo||'')+': '+(h.de||'')+' → '+(h.a||'')+'</div>';}).join('');});
  document.getElementById('detalle-content').innerHTML=`
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
      <span class="badge badge-${o.tipo.toLowerCase()}">${o.tipo}</span>
      ${o.colorOT?`<span class="badge badge-${o.colorOT}">${o.colorOT==='azul'?'🔵 Azul':'🔴 Rojo'}</span>`:''}
      ${o.prioridad?`<span class="badge" style="background:${pC[o.prioridad]||'var(--gr3)'};color:#fff">Prioridad ${o.prioridad}</span>`:''}
      ${o.fuenteBitacora?'<span class="badge" style="background:#6d28d9;color:#fff;font-size:10px;font-weight:700">📒 REG-MTT-001.03</span>':''}
      <span class="badge" style="background:${o.estado==='pre_cierre'?'#7c3aed':''};color:${o.estado==='pre_cierre'?'#fff':''}">${o.estado==='pre_cierre'?'⏳ Pendiente aprobación':o.estado}</span>
    </div>
    <div class="card">
      ${row('🏭 Área',o.area)}
      ${row('📍 Línea',o.linea)}
      ${row('🔩 Componente',o.componente)}
      ${row('📌 Tipo',o.tipoAnormalidad)}
      ${o.contencion?'<div style="background:#fff7ed;border:1.5px solid #f59e0b;border-radius:8px;padding:10px 12px;margin:6px 0"><div style="font-size:11px;font-weight:700;color:#92400e;margin-bottom:3px">⚠️ Medida de Contención</div><div style="font-size:13px;color:#374151">'+o.contencion+'</div></div>':''}
      ${row('👤 Levantado por',o.levantadoPor)}
      ${row('👨‍🔧 Técnico asignado',o.tecnicoNombre||'Sin asignar')}
      ${o.tecnicosAdicionales&&o.tecnicosAdicionales.length?row('👥 Técnicos adicionales',o.tecnicosAdicionales.map(function(t){return t.nombre+(t.horas?' ('+t.horas+'h)':'');}).join(', ')):''}
      ${o.estado==='cerrada'&&o.cerradaPor&&o.cerradaPor!==o.tecnicoNombre&&o.cerradaPor!=='Super Usuario'&&o.cerradaPor!==currentUser?.nombre?row('✅ Cerrado por',o.cerradaPor):''}
      ${o.aprobadoPor?row('👤 Validado por',o.aprobadoPor+(o.aprobadoTs?' · '+new Date(o.aprobadoTs).toLocaleString('es-MX',{day:'2-digit',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'')):''}
      ${o.rechazadoPor?row('❌ Rechazado por',o.rechazadoPor+(o.rechazadoTs?' · '+new Date(o.rechazadoTs).toLocaleString('es-MX',{day:'2-digit',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'')):''}
      ${o.motivoRechazo?row('📝 Motivo rechazo',o.motivoRechazo):''}
      ${o.liderPM04?row('👷 Líder/Oficial A',o.liderPM04):''}
      ${o.limpiezaRequerida?row('🧹 Limpieza requerida','Sí — avisado: '+(o.limpiezaAvisadoA||'—')):(o.limpiezaRequerida===false?row('🧹 Limpieza','No requerida'):'')}
      ${o.horaLlamado?row('📞 Hora llamado',fmtTime(o.horaLlamado)):''}
      ${o.tiempoRespuesta!=null?row('⏱️ T. Respuesta',o.tiempoRespuesta+' min'):''}
      ${o.mttr!=null?row('🔧 MTTR',o.mttr+' min'):''}
      ${(function(){
        var fi='', hi='', ff='', hf='', hrs='';
        if(o.trabajoDias&&o.trabajoDias.length){
          // Trabajo de varios días: fecha inicio = primer día, fecha fin = último día
          var sorted=o.trabajoDias.slice().sort(function(a,b){return a.fecha>b.fecha?1:-1;});
          fi=new Date(sorted[0].fecha+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
          ff=new Date(sorted[sorted.length-1].fecha+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
        } else if(o.fechaTrabajo){
          fi=new Date(o.fechaTrabajo+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
          ff=fi; // mismo día
          hi=o.horaInicioTrabajo||'';
          hf=o.horaFinTrabajo||'';
        } else if(o.horaInicio){
          var dTs=new Date(o.ts);
          fi=dTs.toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
          hi=o.horaInicio||'';
          ff=o.cerradaTs?new Date(o.cerradaTs).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'}):fi;
          hf=o.horaEntrega||o.horaFinTrabajo||'';
        } else {
          fi=new Date(o.ts).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
          hi=new Date(o.ts).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'});
          if(o.cerradaTs){
            ff=new Date(o.cerradaTs).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});
            hf=new Date(o.cerradaTs).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'});
          }
        }
        hrs=o.horasCierre>0?o.horasCierre+' h':'';
        var r2='';
        if(fi) r2+=row('📅 Fecha inicio',fi);
        if(hi) r2+=row('🕐 Hora inicio',hi);
        if(ff) r2+=row('📅 Fecha fin',ff); // siempre mostrar si existe
        if(hf) r2+=row('🕑 Hora fin',hf);
        if(hrs) r2+=row('⏱️ Horas invertidas',hrs);
        if(o.trabajoDias&&o.trabajoDias.length){
          r2+='<div style="margin-top:8px;background:#f9fafb;border-radius:8px;padding:8px">'
            +'<div style="font-size:11px;font-weight:700;color:#6b7280;margin-bottom:4px;text-transform:uppercase">Detalle por día</div>';
          o.trabajoDias.slice().sort(function(a,b){return a.fecha>b.fecha?1:-1;}).forEach(function(d,i){
            var rango=d.horaInicio&&d.horaFin?' · '+d.horaInicio+' → '+d.horaFin:'';
            r2+='<div style="display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid #e5e7eb">'
              +'<span style="color:#374151">Día '+(i+1)+' · '+new Date(d.fecha+'T12:00:00').toLocaleDateString('es-MX',{day:'2-digit',month:'short'})+rango+'</span>'
              +'<span style="font-weight:700;color:#1a3c5e">'+d.horas+' h</span></div>';
          });
          r2+='</div>';
        }
        return r2;
      })()}
      ${o.turno?row('🔄 Turno','Turno '+o.turno):''}
      ${r==='super'?'<div style="margin-top:8px;padding:8px;background:#fef3c7;border-radius:8px;font-size:11px;color:#92400e"><b>🔒 Solo super</b> · Registro: '+fmtDateTime(o.ts)+(o.cerradaTs?' · Captura cierre: '+fmtDateTime(o.cerradaTs):'')+'</div>':''}
    </div>
    <div class="card"><div class="card-title">📝 Detalle</div><p style="font-size:14px;color:var(--txt2);line-height:1.6">${o.detalle}</p>${o.causaRaiz?`<div style="margin-top:10px;font-weight:700;font-size:13px">💡 Causa raíz:</div><p style="font-size:13px;color:var(--txt2);margin-top:4px">${o.causaRaiz}</p>`:''}${o.foto?`<div style="margin-top:10px;font-weight:700;font-size:13px">📷 Foto:</div><img src="${o.foto}" class="foto-preview mt4">`:''}
    </div>
    ${o.estado==='cerrada'&&o.observacionesCierre?`<div class="card"><div class="card-title">✅ Observaciones de cierre</div><p style="font-size:13px;color:var(--txt2)">${o.observacionesCierre}</p>${o.refaccionesUsadas?row('🔩 Refacciones',o.refaccionesUsadas):''}</div>`:''}
    ${hist}
    ${hist}
    <div style="display:flex;flex-direction:column;gap:8px;margin-top:4px">
      ${canClose?`<button class="btn btn-success" onclick="abrirCierre('${o.id}')">✅ Cerrar Orden</button>`:''}
      ${canPreCierre?`<button class="btn btn-success" style="background:#7c3aed" onclick="abrirPreCierre('${o.id}')">🔧 Pre-cierre (pendiente aprobación)</button>`:''}
      ${canAprobar?`<div style="display:flex;gap:8px"><button class="btn btn-success" style="flex:1" onclick="aprobarCierre('${o.id}')">✅ Aprobar cierre</button><button class="btn" style="flex:1;background:#dc2626;color:#fff;border:none" onclick="rechazarCierre('${o.id}')">❌ Rechazar</button></div>`:''}
      ${estaEnPreCierre&&(r==='tecnico'||r==='admin')?`<div style="background:#f0e6ff;border-radius:10px;padding:10px;font-size:13px;color:#7c3aed;font-weight:600">⏳ Esperando aprobación del operador que levantó esta orden</div>`:''}
      ${o.motivoRechazo?`<div style="background:#fee2e2;border-radius:10px;padding:10px;font-size:13px;color:#dc2626;font-weight:600">❌ Rechazado por ${o.rechazadoPor}: ${o.motivoRechazo}</div>`:''}
      ${canCierreAdmin&&!canClose?`<button class="btn btn-success" onclick="abrirCierre('${o.id}')">✅ Forzar Cierre (Admin)</button>`:''}
      ${canCloseAzul?`<button class="btn btn-azul-ot" onclick="abrirCierreAzul('${o.id}')">🔵 Marcar resuelta</button>`:''}
      ${canReasign?`<button class="btn btn-warning" onclick="abrirReasignacion('${o.id}')">🔄 Reasignar</button>`:''}
      ${canEditOwn?`<button class="btn btn-outline" onclick="editarDetalleOp('${o.id}')">✏️ Editar mi aviso</button>`:''}
      ${canDelete?`<button class="btn" style="background:#fee2e2;color:#dc2626;border:none;margin-top:6px" onclick="eliminarOrdenPropia('${o.id}')">🗑️ Eliminar aviso</button>`:''}
      ${canEditFull?`<button class="btn btn-outline" style="border-color:#7c3aed;color:#7c3aed" onclick="abrirEditorCompleto('${o.id}')">✏️ Editar Orden</button>`:''}
    </div>`;
  showScreen('screen-detalle');
}
function row(k,v){return v&&v!=='—'?`<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--gr4);font-size:13px"><span style="color:var(--txt3)">${k}</span><span style="font-weight:600;max-width:60%;text-align:right">${v}</span></div>`:'';}
function abrirCierre(id){
  otCerrandoId=id;
  const o=ORDENES.find(x=>x.id===id)||PM03_PLAN.find(x=>x.id===id);
  document.getElementById('cierre-obs').value='';
  document.getElementById('cierre-horas').value='';
  document.getElementById('cierre-refacciones').value='';
  document.getElementById('cierre-ref-wrap').classList.remove('hidden');
  const el_i=document.getElementById('cierre-hora-inicio');
  const el_f=document.getElementById('cierre-hora-fin');
  const el_c=document.getElementById('cierre-tiempo-calc');
  if(el_i)el_i.value=''; if(el_f)el_f.value=''; if(el_c)el_c.textContent='';
  const tipo=o?.tipo||'PM03';
  const showTime=['PM01','PM03','PM04'].includes(tipo);
  const wrap=document.getElementById('cierre-tiempo-wrap');
  if(wrap)wrap.classList.toggle('hidden',!showTime);
  showModal('modal-cierre');
}
function abrirCierreAzul(id){otCerrandoId=id;document.getElementById('cierre-obs').value='';document.getElementById('cierre-horas').value='0';document.getElementById('cierre-refacciones').value='';document.getElementById('cierre-ref-wrap').classList.add('hidden');showModal('modal-cierre');}
function confirmarCierre(){
  const o=ORDENES.find(x=>x.id===otCerrandoId);if(!o)return;
  // Validar limpieza obligatoria
  if(window._limpiezaRequerida===null||window._limpiezaRequerida===undefined){
    showAlert('Indica si se requiere limpieza por el usuario','error');return;
  }
  if(window._limpiezaRequerida===true){
    var avisoLimp=document.getElementById('limpieza-aviso')?document.getElementById('limpieza-aviso').value.trim():'';
    if(!avisoLimp){showAlert('Indica a quién se le avisó de la limpieza','error');return;}
    o.limpiezaRequerida=true;
    o.limpiezaAvisadoA=avisoLimp;
  } else {
    o.limpiezaRequerida=false;
    o.limpiezaAvisadoA='';
  }
  const obs=document.getElementById('cierre-obs').value.trim();
  if(!obs){showAlert('Escribe las observaciones','error');return;}
  // Calcular horas automáticamente de hora inicio/fin
  var horaIniVal=document.getElementById('cierre-hora-inicio')?.value;
  var horaFinVal=document.getElementById('cierre-hora-fin')?.value;
  var horas=0;
  if(horaIniVal&&horaFinVal){
    var diff=diffMin(horaIniVal,horaFinVal);
    horas=parseFloat((diff/60).toFixed(2));
  }
  if(!horas) horas=parseFloat(document.getElementById('cierre-horas').value)||0;
  const refs=document.getElementById('cierre-refacciones').value.trim();
  const horaIni=document.getElementById('cierre-hora-inicio')?.value||null;
  const horaFin=document.getElementById('cierre-hora-fin')?.value||null;
  o.estado='cerrada';o.observacionesCierre=obs;o.horasCierre=horas;o.refaccionesUsadas=refs;
  o.cerradaTs=Date.now();o.cerradaPor=currentUser.nombre;
  if(horaIni)o.horaInicioTrabajo=horaIni; if(horaFin)o.horaFinTrabajo=horaFin;
  if(refs){refs.split(',').map(s=>s.trim()).forEach(cod=>{const ref=REFACCIONES.find(r=>r.codigo===cod||r.descripcion.toLowerCase().includes(cod.toLowerCase()));if(ref&&ref.cantidad>0)ref.cantidad--;CONSUMO_REF.push({ts:Date.now(),otId:otCerrandoId,tecnico:currentUser.nombre,codigo:cod,descripcion:cod,semana:currentWeek(),año:currentYear()});});saveDB('refacciones',REFACCIONES);saveDB('consumo_ref',CONSUMO_REF);}
  saveDB('ordenes',ORDENES);saveOrdenSupa(o);cerrarModal('modal-cierre');showAlert('✅ Orden cerrada');showDetalle(otCerrandoId);
}
function abrirReasignacion(id){
  reasignandoId=id;
  function buildSelect(){
    var tecs=USERS.filter(function(u){return u.rol==='tecnico'&&u.id!=='u_super';});
    document.getElementById('reasig-sel').innerHTML='<option value="">Sin asignar</option>'+tecs.map(function(t){return '<option value="'+t.id+'">'+t.nombre+'</option>';}).join('');
    document.getElementById('reasig-motivo').value='';
    showModal('modal-reasignar');
  }
  // Recargar usuarios frescos de Supabase
  supaFetch('usuarios','GET',null,'rol=eq.tecnico&activo=eq.true&order=nombre.asc').then(function(rows){
    if(rows&&rows.length) rows.forEach(function(r){
      if(!USERS.find(function(u){return u.id===r.id;}))
        USERS.push({id:r.id,username:r.username,nombre:r.nombre,rol:r.rol});
    });
    buildSelect();
  }).catch(buildSelect);
}
function confirmarReasignacion(){
  const o=ORDENES.find(x=>x.id===reasignandoId);if(!o)return;
  const sel=document.getElementById('reasig-sel');const motivo=document.getElementById('reasig-motivo').value.trim();
  const nuevoId=sel.value,nuevoNom=sel.options[sel.selectedIndex]?.text||'Sin asignar';
  if(!o.historialReasignacion)o.historialReasignacion=[];
  o.historialReasignacion.push({ts:Date.now(),cambiadoPor:nombreEfectivo(),de:o.tecnicoNombre||'Sin asignar',a:nuevoNom,motivo:motivo||'Sin motivo'});
  o.tecnicoAsignado=nuevoId;o.tecnicoNombre=nuevoNom;
  saveDB('ordenes',ORDENES);
  supabaseStatePatch(o.id,{tecnico_asignado:nuevoId,tecnico_nombre:nuevoNom});
  cerrarModal('modal-reasignar');showAlert('✅ Reasignado a '+nuevoNom);showDetalle(reasignandoId);
}
function editarDetalleOp(id){
  const o=ORDENES.find(x=>x.id===id);if(!o)return;
  const TIPOS=['Seguridad','Calidad','5s','Condición Básica','LDA (Lugar de Difícil Acceso)','FDS (Fuente de Suciedad)','Paro Menor','Otra'];
  const tiposOpts=TIPOS.map(t=>`<option value="${t}"${o.tipoAnormalidad===t?' selected':''}>${t}</option>`).join('');
  const esContencion=(o.colorOT==='rojo'&&o.prioridad==='A'&&(o.tipoAnormalidad==='Seguridad'||o.tipoAnormalidad==='Calidad'));

  const m=document.createElement('div');
  m.id='modal-edit-op';
  m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:flex-end;justify-content:center';
  m.innerHTML=`<div style="background:#fff;border-radius:16px 16px 0 0;padding:20px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto">
    <div style="font-family:Nunito,sans-serif;font-size:16px;font-weight:800;color:#1a3c5e;margin-bottom:14px">✏️ Editar mi aviso</div>
    <div class="form-group"><label class="form-label">Prioridad</label>
      <select class="form-control" id="eop-prio">
        <option value="A"${o.prioridad==='A'?' selected':''}>🔴 Prioridad A</option>
        <option value="B"${o.prioridad==='B'?' selected':''}>🟠 Prioridad B</option>
        <option value="C"${o.prioridad==='C'?' selected':''}>🟢 Prioridad C</option>
      </select></div>
    <div class="form-group"><label class="form-label">Tipo de anormalidad</label>
      <select class="form-control" id="eop-tipo" onchange="eopCheckContencion()">
        <option value="">-- Selecciona --</option>${tiposOpts}
      </select></div>
    <div class="form-group"><label class="form-label">Componente</label>
      <input type="text" class="form-control" id="eop-comp" value="${o.componente||''}"></div>
    <div class="form-group"><label class="form-label">Detalle / Descripción</label>
      <textarea class="form-control" id="eop-detalle" rows="3">${o.detalle||''}</textarea></div>
    <div id="eop-contencion-wrap" style="display:${esContencion?'block':'none'}">
      <div class="form-group" style="background:#fff7ed;border:2px solid #f59e0b;border-radius:10px;padding:12px">
        <label class="form-label" style="color:#92400e;font-weight:800">⚠️ Medida de Contención <span style="color:#dc2626">*Obligatoria</span></label>
        <textarea class="form-control" id="eop-contencion" rows="2" placeholder="Describe la acción de contención...">${o.contencion||''}</textarea>
      </div></div>
    <div style="display:flex;gap:8px;margin-top:12px">
      <button type="button" class="btn btn-outline" style="flex:1" onclick="document.getElementById('modal-edit-op').remove()">Cancelar</button>
      <button type="button" class="btn btn-primary" style="flex:2" onclick="guardarEditOp('${id}')">💾 Guardar</button>
    </div>
  </div>`;
  document.body.appendChild(m);
}

function eopCheckContencion(){
  var tipo=document.getElementById('eop-tipo')?.value||'';
  var prio=document.getElementById('eop-prio')?.value||'';
  var wrap=document.getElementById('eop-contencion-wrap');
  if(wrap) wrap.style.display=(prio==='A'&&(tipo==='Seguridad'||tipo==='Calidad'))?'block':'none';
}

function guardarEditOp(id){
  var o=ORDENES.find(x=>x.id===id);if(!o)return;
  var prio=document.getElementById('eop-prio')?.value||o.prioridad;
  var tipo=document.getElementById('eop-tipo')?.value||o.tipoAnormalidad;
  var comp=document.getElementById('eop-comp')?.value.trim()||o.componente;
  var det=document.getElementById('eop-detalle')?.value.trim()||o.detalle;
  var cont=document.getElementById('eop-contencion')?.value.trim()||'';
  // Validar contención obligatoria
  if(o.colorOT==='rojo'&&prio==='A'&&(tipo==='Seguridad'||tipo==='Calidad')&&!cont){
    showAlert('La medida de contención es obligatoria para Seguridad/Calidad Prio A','error');return;
  }
  if(!o.historialModificacion)o.historialModificacion=[];
  if(prio!==o.prioridad)o.historialModificacion.push({ts:Date.now(),por:nombreEfectivo(),campo:'Prioridad',de:o.prioridad,a:prio});
  if(tipo!==o.tipoAnormalidad)o.historialModificacion.push({ts:Date.now(),por:nombreEfectivo(),campo:'Tipo anormalidad',de:o.tipoAnormalidad,a:tipo});
  if(det!==o.detalle)o.historialModificacion.push({ts:Date.now(),por:nombreEfectivo(),campo:'Detalle',de:o.detalle,a:det});
  o.prioridad=prio;o.tipoAnormalidad=tipo;o.componente=comp;o.detalle=det;
  if(cont)o.contencion=cont;
  saveDB('ordenes',ORDENES);
  saveOrdenSupa(o);
  document.getElementById('modal-edit-op')?.remove();
  showAlert('✅ Aviso actualizado');
  showDetalle(id);
}

