function showConsultaOT(){
  detalleBackScreen='screen-consulta';
  // Reset filtros al entrar
  filtrosConsulta={tipo:'todas',estado:'todos',color:'todos',prio:'todas',anom:'todas'};
  // Reset fecha resumen a ayer si no hay filtro
  if(!window._rtFecha && !window._rtSem){
    var ayer=new Date(Date.now()-86400000);
    window._rtFecha=ayer.toISOString().split('T')[0];
  }
  renderResumenTecnicosOT();
  const sel=document.getElementById('filtro-tecnico');
  const tecs=USERS.filter(u=>u.rol==='tecnico');
  sel.innerHTML=`<option value="">Todos los técnicos</option>${tecs.map(t=>`<option value="${t.id}">${t.nombre}</option>`).join('')}`;
  filtrosConsulta={tipo:'todas',estado:'todos',color:'todos',prio:'todas'};
  renderResumenConsulta();
  // Add semana/año filter if not present
  setTimeout(function(){
    if(!document.getElementById('filtro-semana-consulta')){
      var filterArea = document.querySelector('#screen-consulta .scroll-content');
      var semDiv = document.createElement('div');
      semDiv.style.cssText = 'display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap';
      semDiv.innerHTML = '<div style="flex:1;min-width:70px"><label class="form-label">Mes</label><select class="form-control" id="filtro-mes-consulta" onchange="filtrarOrdenes()" style="padding:8px"><option value="">Todos</option>'
        + ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'].map(function(m,i){return '<option value="'+(i+1)+'"'+(i+1===new Date().getMonth()+1?' selected':'')+'>'+m+'</option>';}).join('')
        + '</select></div>'
        + '<div style="flex:1;min-width:70px"><label class="form-label">Semana</label><select class="form-control" id="filtro-semana-consulta" onchange="filtrarOrdenes()" style="padding:8px"><option value="">Todas</option>'
        + Array.from({length:52},function(_,i){return '<option value="'+(i+1)+'"'+(i+1===currentWeek()?' selected':'')+'>Sem '+(i+1)+'</option>';}).join('')
        + '</select></div>'
        + '<div style="flex:1;min-width:70px"><label class="form-label">Año</label><select class="form-control" id="filtro-año-consulta" onchange="filtrarOrdenes()" style="padding:8px">'
        + [currentYear()-1,currentYear(),currentYear()+1].map(function(a){return '<option value="'+a+'"'+(a===currentYear()?' selected':'')+'>'+a+'</option>';}).join('')
        + '</select></div>'
        + '<div style="flex:1;min-width:55px"><label class="form-label">Día</label><select class="form-control" id="filtro-dia-consulta" onchange="filtrarOrdenes()" style="padding:8px"><option value="">Todos</option>'
        + Array.from({length:31},function(_,i){return '<option value="'+(i+1)+'"'+(i+1===new Date().getDate()?' selected':'')+'>'+( i+1)+'</option>';}).join('')
        + '</select></div>';
      if(filterArea){var s=filterArea.querySelector('.search-box');if(s)filterArea.insertBefore(semDiv,s);}
    }
  },50);
  filtrarOrdenes();showScreen('screen-consulta');
}
function setFiltro(tipo,val,btn){filtrosConsulta[tipo]=val;const row=btn.closest('.filter-row');if(row)row.querySelectorAll('.filter-chip').forEach(c=>c.classList.remove('active'));btn.classList.add('active');filtrarOrdenes();}
