    <div class="form-group"><label class="form-label">Mes</label><select class="form-control" id="gas-mes-b">${meses.map((m,i)=>`<option value="${i+1}" ${i+1===new Date().getMonth()+1?'selected':''}>${m}</option>`).join('')}</select></div>
