// SCROLL LISTENERS
// ================================================================
function _initScrollListeners(){
  function attachScroll(sc){
    if(sc._scrollBound) return;
    sc._scrollBound=true;
    sc.addEventListener('scroll',function(){
      var screenEl=sc.closest('.screen');
      if(screenEl&&screenEl.id) saveDB('scroll_pos_'+screenEl.id, sc.scrollTop);
    },{passive:true});
  }
  // Registrar en todos los existentes
  document.querySelectorAll('.scroll-content').forEach(attachScroll);
  // Observar el DOM para registrar los que se creen dinámicamente
  var obs=new MutationObserver(function(muts){
    muts.forEach(function(m){
      m.addedNodes.forEach(function(n){
        if(n.nodeType!==1) return;
        if(n.classList&&n.classList.contains('scroll-content')) attachScroll(n);
        n.querySelectorAll&&n.querySelectorAll('.scroll-content').forEach(attachScroll);
      });
    });
  });
  obs.observe(document.body,{childList:true,subtree:true});
}

