function mostrarFormTiempoResolucion(modo){
  const cont=document.getElementById('pm-wizard-container');
  var fechaD=pmState.fechaTrabajo||todayStr();
  var hiD=pmState.horaInicioTrabajo||'';
  var hfD=pmState.horaFinTrabajo||'';
  var esTmp=modo==='temp';
  window._resLimp=null;
  cont.innerHTML=`<div class="wizard-title">${esTmp?'⚡ Resuelta Temporalmente':'⏱️ Tiempo Invertido'}</div>
  <div class="wizard-sub">Confirma la fecha y hora del trabajo</div>
  <div class="form-group" style="margin-bottom:10px">
    <label class="form-label" style="font-size:12px">📅 Fecha del trabajo</label>
    <input type="date" class="form-control" id="pm-fecha-orden" value="${fechaD}"
      ${(function(){var r=currentUser.rol;if(r==='super')return '';var m=new Date(Date.now()-7*86400000).toISOString().split('T')[0];return 'min="'+m+'" max="'+todayStr()+'"';})()}
      style="padding:8px;margin-bottom:8px" onchange="var d=this.value;pmState.fechaTrabajo=d;pmState._tsOrden=new Date(d+'T'+(document.getElementById('res-ini').value||'00:00')+':00').getTime();pmState._semOrden=getWeekNumber(new Date(d+'T12:00:00'));pmState._añoOrden=new Date(d+'T12:00:00').getFullYear();">
  </div>
  <div style="background:var(--az3);border-radius:10px;padding:14px;margin-bottom:12px">
    <div style="display:flex;gap:10px;margin-bottom:10px">
      <div style="flex:1"><label class="form-label" style="font-size:11px">Hora inicio (24h)</label>
        <input type="time" class="form-control" id="res-ini" value="${hiD}" onchange="calcResTime()"></div>
      <div style="flex:1"><label class="form-label" style="font-size:11px">Hora fin (24h)</label>
        <input type="time" class="form-control" id="res-fin" value="${hfD}" onchange="calcResTime()"></div>
    </div>
    <div id="res-tiempo-calc" style="text-align:center;font-size:14px;font-weight:700;color:var(--mo)"></div>
  </div>
  <div style="background:#fff3cd;border:2px solid #ffc107;border-radius:10px;padding:14px;margin-bottom:14px">
    <div style="font-size:13px;font-weight:700;color:#856404;margin-bottom:10px">🧹 ¿Se requiere limpieza después de la intervención?</div>
    <div style="display:flex;gap:8px;margin-bottom:8px">
      <button id="res-limp-si" type="button" onclick="resLimpToggle(true)" style="flex:1;padding:10px;border-radius:8px;border:2px solid #e5e7eb;background:#fff;font-weight:700;cursor:pointer">✅ Sí</button>
      <button id="res-limp-no" type="button" onclick="resLimpToggle(false)" style="flex:1;padding:10px;border-radius:8px;border:2px solid #e5e7eb;background:#fff;font-weight:700;cursor:pointer">❌ No</button>
    </div>
    <div id="res-limp-aviso-wrap" style="display:none">
      <label style="font-size:12px;font-weight:700;color:#374151;display:block;margin-bottom:4px">¿A quién se le avisó?</label>
      <input type="text" id="res-limp-aviso" class="form-control" placeholder="Nombre del usuario avisado..." style="padding:10px">
    </div>
  </div>
  <button class="btn btn-success" onclick="${esTmp?'confirmarResolucion_temp()':'confirmarResolucion()'}">✅ Guardar como Resuelta</button>`;
  document.getElementById('pm-btn-next').style.display='none';
  if(hiD&&hfD) calcResTime();
}

function calcResTime(){
  const ini=document.getElementById('res-ini')?.value;
  const fin=document.getElementById('res-fin')?.value;
  const div=document.getElementById('res-tiempo-calc');
  if(!ini||!fin||!div)return;
  const [ih,im]=ini.split(':').map(Number);
  const [fh,fm]=fin.split(':').map(Number);
  let mins=(fh*60+fm)-(ih*60+im);
  if(mins<0)mins+=1440;
  const h=Math.floor(mins/60),m=mins%60;
  div.textContent='⏱️ '+h+'h '+m+'m = '+parseFloat((h+m/60).toFixed(2))+' hrs';
  pmState.tiempoHoras=parseFloat((h+m/60).toFixed(2));
  pmState.horaInicioTrabajo=ini; pmState.horaFinTrabajo=fin;
}

function confirmarResolucion(){
  calcResTime();
  // Capturar fecha del campo visible
  var fEl=document.getElementById('pm-fecha-orden');
  var fecha=fEl&&fEl.value?fEl.value:pmState.fechaTrabajo||todayStr();
  pmState.fechaTrabajo=fecha;
  var horaIni=pmState.horaInicioTrabajo||'00:00';
  pmState._tsOrden=new Date(fecha+'T'+horaIni+':00').getTime();
  pmState._semOrden=getWeekNumber(new Date(fecha+'T12:00:00'));
  pmState._añoOrden=new Date(fecha+'T12:00:00').getFullYear();
  if(pmState.tiempoHoras && pmState.tiempoHoras > 0){
    pmState.horasCierre = pmState.tiempoHoras;
  } else {
    var ini = document.getElementById('res-ini');
    var fin = document.getElementById('res-fin');
    if(ini && fin && ini.value && fin.value){
      var parts1 = ini.value.split(':').map(Number);
      var parts2 = fin.value.split(':').map(Number);
      var mins = (parts2[0]*60+parts2[1]) - (parts1[0]*60+parts1[1]);
      if(mins < 0) mins += 1440;
      pmState.horasCierre = parseFloat((mins/60).toFixed(2));
    }
  }
  pmState.resuelta = true;
  // Leer limpieza del campo inline
  if(window._resLimp===null||window._resLimp===undefined){
    showAlert('Indica si se requiere limpieza','error');return;
  }
  if(window._resLimp===true){
    var av=document.getElementById('res-limp-aviso')?document.getElementById('res-limp-aviso').value.trim():'';
    if(!av){showAlert('Indica a quién se le avisó de la limpieza','error');return;}
    pmState.limpiezaRequerida=true;
    pmState.limpiezaAvisadoA=av;
  } else {
    pmState.limpiezaRequerida=false;
    pmState.limpiezaAvisadoA='';
  }
  window._resLimp=null;
  guardarOT();
}

// ─── guardarOT with resuelta flag ───
const _origGuardarOT=guardarOT;
// Override guardarOT to handle resuelta
const guardarOT_orig=guardarOT;

// ─── calcularTiempoCierre ───
function calcularTiempoCierre(){
  const ini=document.getElementById('cierre-hora-inicio')?.value;
  const fin=document.getElementById('cierre-hora-fin')?.value;
  const calc=document.getElementById('cierre-tiempo-calc');
  if(!ini||!fin||!calc)return;
  const [ih,im]=ini.split(':').map(Number);
  const [fh,fm]=fin.split(':').map(Number);
  let mins=(fh*60+fm)-(ih*60+im);
  if(mins<0)mins+=1440;
  const h=Math.floor(mins/60),m=mins%60;
  const hDec=parseFloat((h+m/60).toFixed(2));
  calc.textContent='⏱️ '+h+'h '+m+'m ('+hDec+' hrs)';
  document.getElementById('cierre-horas').value=hDec;
}

// ─── Filtrar ordenes (new version with all filters) ───
function filtrarOrdenes(){
  const q=(document.getElementById('consulta-search')?.value||'').toLowerCase();
  // Si hay texto de búsqueda, ignorar todos los filtros
  if(q.length>=2){
    const allOTs=[...ORDENES,...PM03_PLAN.map(function(p){return{id:p.id,tipo:'PM03',linea:p.linea||'',area:p.area||'',componente:p.componente||p.actividad||'',detalle:p.actividad||'',tecnicoAsignado:p.tecnicoAsignado||'',tecnicoNombre:p.tecnicoNombre||'',estado:p.estado||'',ts:p.ts||0};})].filter(function(o){
      var hay=(o.id+' '+(o.linea||'')+(o.area||'')+(o.componente||'')+(o.detalle||'')+(o.tecnicoNombre||'')).toLowerCase();
      return hay.includes(q);
    });
    const contQ=document.getElementById('consulta-list');
    if(contQ) contQ.innerHTML='<p style="font-size:13px;color:var(--txt3);margin-bottom:8px">'+allOTs.length+' orden(es) encontradas</p>'+
      allOTs.map(function(o){
        var fnClick=o.tipo==='PM03'?'showDetallePM03':'showDetalle';
        return '<div class="ot-card" style="margin-bottom:8px" onclick="'+fnClick+'(\''+o.id+'\')">'+
          '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">'+
          '<span style="font-size:11px;font-weight:700;color:#7c3aed">'+o.id+'</span>'+
          '<span style="font-size:11px;background:#e5e7eb;border-radius:6px;padding:1px 7px;color:#374151">'+o.tipo+'</span>'+
          '</div>'+
          '<div style="font-size:13px;font-weight:700;color:#1a3c5e;margin-bottom:2px">'+(o.linea||o.area||'—')+(o.componente?' · '+o.componente:'')+'</div>'+
          '<div style="font-size:12px;color:#6b7280">'+(o.detalle||'').substring(0,60)+'</div>'+
          '</div>';
      }).join('');
    return;
  }
  const tecF=document.getElementById('filtro-tecnico')?.value||'';
  const levF=document.getElementById('filtro-levantado')?.value||'';
  const semConsulta=parseInt(document.getElementById('filtro-semana-consulta')?.value)||0;
  const mesConsulta=parseInt(document.getElementById('filtro-mes-consulta')?.value)||0;
  const añoConsulta=parseInt(document.getElementById('filtro-año-consulta')?.value)||currentYear();
  const semsConsultaMes=(mesConsulta>0&&!semConsulta)?getWeeksInMonth(añoConsulta,mesConsulta):null;
  // Convertir PM03 a formato compatible con ORDENES para mostrar en Consultar
  var pm3Lista = PM03_PLAN.map(function(p){
    return {
      id:p.id, tipo:'PM03', area:p.area||'', linea:p.linea||'',
      componente:p.componente||p.actividad||'', tipoAnormalidad:'Mtto Planeado',
      detalle:p.actividad||'', levantadoPor:p.generadoPor||'Sistema',
      tecnicoAsignado:p.tecnicoId||'', tecnicoNombre:p.tecnicoNombre||'Sin asignar',
      estado:p.estado||'abierta',prioridad:p.prioridad||null, colorOT:null, prioridad:null,
      semana:p.semana, año:p.año||2026, ts:p.ts||0,
      _esPM03:true, _pm3id:p.id,
      estadoCalidad:p.estadoCalidad, liberadoPor:p.liberadoPor
    };
  });
  let lista=[...ORDENES,...pm3Lista].sort((a,b)=>b.ts-a.ts);
  // Aplicar filtro de semana/mes
  if(semsConsultaMes) lista=lista.filter(o=>semsConsultaMes.includes(o.semana)&&(o.año||currentYear())===añoConsulta);
  else if(semConsulta) lista=lista.filter(o=>o.semana===semConsulta&&(o.año||currentYear())===añoConsulta);
  // Filtro por día con corte 6:30am a 6:30am
  var diaConsulta=parseInt(document.getElementById('filtro-dia-consulta')?.value)||0;
  if(diaConsulta>0){
    var mesParaDia=mesConsulta||new Date().getMonth()+1;
    var añoParaDia=añoConsulta;
    var inicioCorte=new Date(añoParaDia,mesParaDia-1,diaConsulta,6,30,0).getTime();
    var finCorte=new Date(añoParaDia,mesParaDia-1,diaConsulta+1,6,30,0).getTime();
    lista=lista.filter(function(o){
      var tsO=o.ts||o.cerradaTs||0;
      return tsO>=inicioCorte&&tsO<finCorte;
    });
  }
  if(filtrosConsulta.tipo==='temporal') lista=lista.filter(function(o){return o.esResueltaTemporal;});
  else if(filtrosConsulta.tipo==='bitacora') lista=lista.filter(function(o){return o.fuenteBitacora===true;});
  else if(filtrosConsulta.tipo&&filtrosConsulta.tipo!=='todas') lista=lista.filter(o=>o.tipo===filtrosConsulta.tipo);
  if(filtrosConsulta.estado&&filtrosConsulta.estado!=='todos') lista=lista.filter(o=>o.estado===filtrosConsulta.estado);
  // Filtro especial todos incluye pre_cierre
  if(filtrosConsulta.estado==='todos') lista=lista; // ya incluye pre_cierre
  if(filtrosConsulta.color&&filtrosConsulta.color!=='todos') lista=lista.filter(o=>o.colorOT===filtrosConsulta.color);
  if(filtrosConsulta.prio&&filtrosConsulta.prio!=='todas') lista=lista.filter(o=>o.prioridad===filtrosConsulta.prio);
  if(filtrosConsulta.anom&&filtrosConsulta.anom!=='todas') lista=lista.filter(o=>o.tipoAnormalidad===filtrosConsulta.anom);
  if(tecF) lista=lista.filter(o=>o.tecnicoAsignado===tecF);
  if(levF) lista=lista.filter(o=>o.levantadoPor===levF);
  if(q) lista=lista.filter(o=>(o.id||'').toLowerCase().includes(q)||(o.linea||'').toLowerCase().includes(q)||(o.detalle||'').toLowerCase().includes(q)||(o.levantadoPor||'').toLowerCase().includes(q)||(o.tecnicoNombre||'').toLowerCase().includes(q)||(o.tipoAnormalidad||'').toLowerCase().includes(q));
  const cont=document.getElementById('consulta-list');
  const canAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  const pB={A:'badge-pA',B:'badge-pB',C:'badge-pC'};
  cont.innerHTML=lista.length?
    `<p style="font-size:13px;color:var(--txt3);margin-bottom:8px">${lista.length} orden(es)</p>`+
    lista.map(o=>`<div class="ot-card ${o.tipo.toLowerCase()} ${o.colorOT?'color-'+o.colorOT:''}" onclick="${o._esPM03?`showDetallePM03('${o._pm3id||o.id}')`:`showDetalle('${o.id}')`}" style="${o.fuenteBitacora?'border-left:4px solid #6d28d9;background:linear-gradient(to right,#f5f3ff 0%,#fff 60%)':''}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">
        <span style="font-size:11px;color:var(--txt3);font-weight:700">${o.id}</span>
        <div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end">
          ${o.fuenteBitacora?'<span class="badge" style="background:#6d28d9;color:#fff;font-size:10px;font-weight:700">📒 REG-MTT-001.03</span>':''}
          <span class="badge badge-${o.tipo.toLowerCase()}">${o.tipo}</span>
          ${o.colorOT?`<span class="badge badge-${o.colorOT}">${o.colorOT==='azul'?'🔵':'🔴'}</span>`:''}
          ${o.esResueltaTemporal?'<span class="badge" style="background:#F59E0B;color:#1a1a1a;font-size:10px;font-weight:800">⚡ TEMPORAL</span>':''}
          ${o.pendienteAsignacion?'<span class="badge" style="background:#7c3aed;color:#fff;font-size:10px;font-weight:700">📋 Por asignar</span>':''}
          ${o._esPM03&&o.estado==='cerrada'&&!o.liberadoPor&&o.estadoCalidad!=='liberada'?'<span class="badge" style="background:#dc2626;color:#fff;font-size:10px;font-weight:700">🔴 x Liberar</span>':''}
          ${o._esPM03&&o.estadoCalidad==='liberada'?'<span class="badge" style="background:#16a34a;color:#fff;font-size:10px">✅ Liberada</span>':''}
        ${o.prioridad?`<span class="badge ${pB[o.prioridad]||'badge-pB'}">P${o.prioridad}</span>`:''}
          <span class="badge" style="background:${o.estado==='pre_cierre'?'#7c3aed':''};color:${o.estado==='pre_cierre'?'#fff':''}">${o.estado==='pre_cierre'?'⏳ Pendiente aprobación':o.estado}</span>
        </div>
      </div>
      <div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;margin:2px 0 4px">${o.linea} — ${o.componente}</div>
      <div style="font-size:12px;color:var(--txt2)">${o.area||''} · ${o.tipoAnormalidad||''}</div>
      <div style="font-size:12px;color:var(--txt2);margin-top:2px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.4">${(o.detalle||'')}</div>
      <div style="display:flex;justify-content:space-between;margin-top:8px;font-size:11px;color:var(--txt3)">
        <span>👤 ${o.levantadoPor}</span><span>👨‍🔧 ${o.tecnicoNombre||'Sin asignar'}</span><span>📅 ${fmtDate(o.ts)}</span>
      </div>
      ${canAdmin&&o.estado!=='cerrada'?`<div style="display:flex;gap:6px;margin-top:8px">
        <button class="btn btn-warning btn-sm" style="font-size:12px;padding:5px 10px;flex:1" onclick="event.stopPropagation();abrirReasignacion('${o.id}')">🔄 Reasignar</button>
        <button class="btn btn-danger btn-sm" style="font-size:12px;padding:5px 10px;width:auto" onclick="event.stopPropagation();eliminarOT('${o.id}')">🗑️</button>
      </div>`:canAdmin&&o.estado==='cerrada'&&currentUser.rol==='super'?`<div style="display:flex;gap:6px;margin-top:8px;justify-content:flex-end">
        <button class="btn btn-danger btn-sm" style="font-size:12px;padding:5px 10px;width:auto" onclick="event.stopPropagation();eliminarOT('${o.id}')">🗑️ Eliminar</button>
      </div>`:''}
    </div>`).join('')
    :`<div class="card text-center" style="padding:32px"><div style="font-size:40px">📭</div><div style="font-weight:700;margin-top:8px">Sin resultados</div></div>`;
}

function eliminarOT(id){
  if(currentUser.rol!=='admin'&&currentUser.rol!=='super'){showAlert('Sin permisos','error');return;}
  if(!confirm('¿Eliminar esta orden permanentemente?\nEsta acción no se puede deshacer.')) return;
  const idx=ORDENES.findIndex(x=>x.id===id);
  if(idx>=0){ORDENES.splice(idx,1);saveDB('ordenes',ORDENES);deleteOrdenSupa(id);showAlert('Orden eliminada','warning');filtrarOrdenes();renderResumenConsulta();}
}

// ─── renderResumenConsulta (visual with %) ───
function renderResumenConsulta(){
  const ots=ORDENES,total=ots.length;
  const sol=ots.filter(o=>o.estado==='cerrada').length,ab=total-sol;
  const pctSol=total?Math.round((sol/total)*100):0,pctAb=total?Math.round((ab/total)*100):0;
  const pA=ots.filter(o=>o.prioridad==='A'),pB=ots.filter(o=>o.prioridad==='B'),pC=ots.filter(o=>o.prioridad==='C');
  function ps(arr){const t=arr.length,s=arr.filter(o=>o.estado==='cerrada').length,a=t-s,pct=t?Math.round((s/t)*100):0;return{t,s,a,pct};}
  const sA=ps(pA),sB=ps(pB),sC=ps(pC);
  function bc(p){return p>=80?'var(--vd)':p>=50?'var(--am2)':'var(--rj)';}
  document.getElementById('consulta-resumen').innerHTML=`
  <div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800;color:var(--mo);margin-bottom:10px">📊 Resumen de Órdenes de Trabajo</div>
  <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px">
    <div style="background:rgba(255,255,255,.7);border-radius:10px;padding:10px;text-align:center">
      <div style="font-size:26px;font-weight:800;color:var(--mo)">${total}</div>
      <div style="font-size:10px;font-weight:700;color:var(--txt2)">TOTAL OT</div>
      <div style="font-size:10px;color:var(--txt3);margin-top:3px">PM03 ${PM03_PLAN.filter(function(p){return p.estado==='cerrada'&&(p.año||new Date(p.ts||0).getFullYear())===new Date().getFullYear();}).length} cerradas ${new Date().getFullYear()}</div>
    </div>
    <div style="background:rgba(255,255,255,.7);border-radius:10px;padding:10px;text-align:center">
      <div style="font-size:24px;font-weight:800;color:var(--vd)">${sol}</div>
      <div style="font-size:10px;font-weight:700;color:var(--vd)">SOLUCIONADAS</div>
      <div style="font-size:13px;font-weight:800;color:var(--vd)">${pctSol}%</div>
      <div style="background:rgba(0,0,0,.1);border-radius:4px;height:5px;margin-top:3px;overflow:hidden"><div style="width:${pctSol}%;height:100%;background:var(--vd);border-radius:4px"></div></div>
    </div>
    <div style="background:rgba(255,255,255,.7);border-radius:10px;padding:10px;text-align:center">
      <div style="font-size:24px;font-weight:800;color:var(--am2)">${ab}</div>
      <div style="font-size:10px;font-weight:700;color:var(--am2)">ABIERTAS</div>
      <div style="font-size:13px;font-weight:800;color:var(--am2)">${pctAb}%</div>
      <div style="background:rgba(0,0,0,.1);border-radius:4px;height:5px;margin-top:3px;overflow:hidden"><div style="width:${pctAb}%;height:100%;background:var(--am2);border-radius:4px"></div></div>
    </div>
  </div>
  <div style="border-top:1px solid rgba(255,255,255,.4);padding-top:8px">
    <div style="font-size:11px;font-weight:700;color:var(--txt2);margin-bottom:6px">POR PRIORIDAD</div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">
      ${[{l:'Prioridad A',s:sA,col:'var(--rj)'},{l:'Prioridad B',s:sB,col:'var(--am2)'},{l:'Prioridad C',s:sC,col:'var(--vd)'}].map(p=>`
      <div style="background:rgba(255,255,255,.6);border-radius:8px;padding:8px;border-left:3px solid ${p.col}">
        <div style="font-size:9px;font-weight:800;color:${p.col};margin-bottom:3px">${p.l}</div>
        <div style="font-size:11px">Total: <b>${p.s.t}</b></div>
        <div style="font-size:11px;color:var(--vd)">Sol: <b>${p.s.s}</b></div>
        <div style="font-size:11px;color:var(--am2)">Ab: <b>${p.s.a}</b></div>
        <div style="font-size:12px;font-weight:800;color:${bc(p.s.pct)}">${p.s.pct}%</div>
        <div style="background:rgba(0,0,0,.1);border-radius:3px;height:4px;margin-top:2px;overflow:hidden"><div style="width:${p.s.pct}%;height:100%;background:${bc(p.s.pct)};border-radius:3px"></div></div>
      </div>`).join('')}
    </div>
  </div>`;
}

// ─── descargarOTExcel ───
function descargarOTExcel(){
  var ots=[...ORDENES].sort(function(a,b){return b.ts-a.ts;});
  if(!ots.length){showAlert('Sin ordenes','error');return;}
  var hdrs=['ID','Tipo','Estado','Color OT','Área','Línea','Componente','Prioridad','Tipo Anormalidad','Detalle','Levantado Por','Técnico','Fecha','Semana','Año','Hora Inicio','Hora Fin','Horas Invertidas','Cerrada Por','Fecha Cierre','Refacciones','Observaciones Cierre','Causa Raíz'];
  var rows=ots.map(function(o){return[o.id,o.tipo,o.estado,o.colorOT||'',o.area||'',o.linea||'',o.componente||'',o.prioridad||'',o.tipoAnormalidad||'',o.detalle||'',o.levantadoPor||'',o.tecnicoNombre||'',fmtDate(o.ts),o.semana||'',o.año||'',o.horaInicioTrabajo||'',o.horaFinTrabajo||'',o.horasCierre||0,o.cerradaPor||'',o.cerradaTs?fmtDate(o.cerradaTs):'',o.refaccionesUsadas||'',o.observacionesCierre||'',o.causaRaiz||''];});
  generarExcelXML(hdrs, rows, 'Saporis_OT_'+new Date().toISOString().slice(0,10)+'.xls', 'Órdenes de Trabajo');
  showAlert('Descargadas '+ots.length+' ordenes en Excel');
}

