var SUPA_URL='https://bwjvmtwkgvyewyjfazou.supabase.co';
var SUPA_KEY='sb_publishable_bMC14dd2RT3n0Ka3Mwb8Yg_JRXlz-OE';
var SUPER_PWD='Apocalipsis$2016';

function supaFetch(t,m,b,p){var url=SUPA_URL+'/rest/v1/'+t+(p?'?'+p:'');var headers={'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Accept':'application/json'};if(m==='POST')headers['Prefer']='resolution=merge-duplicates,return=representation';var o={method:m||'GET',headers:headers};if(b)o.body=JSON.stringify(b);return fetch(url,o).then(function(r){if(!r.ok){return r.text().then(function(txt){console.error('supaFetch error ['+t+']:',txt);return null;});}return r.json();}).catch(function(e){console.error('supaFetch catch:',e);return null;});}
function supaUpsert(t,b){
  window._supaUpsert=supaUpsert;
  return fetch(SUPA_URL+'/rest/v1/'+t,{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=representation'},
    body:JSON.stringify(b)
  }).then(function(r){
    if(!r.ok){
      return r.text().then(function(txt){
        console.error('supaUpsert ERROR ['+t+']:', txt.substring(0,200));
        return null;
      });
    }
    return r.json();
  }).catch(function(e){
    console.error('supaUpsert CATCH ['+t+']:', e.message);
    return null;
  });
}




// ================================================================
// LIMPIEZA AUTOMÁTICA DE FOTOS — 7 días después del cierre
// ================================================================
function _limpiarFotosAntiguas(){
  var ahora=Date.now();
  var SIETE_DIAS=7*24*60*60*1000;
  var ultimaLimpieza=loadDB('ultima_limpieza_fotos',0);
  if(ahora-ultimaLimpieza<24*60*60*1000) return;
  saveDB('ultima_limpieza_fotos',ahora);
  var ordenesConFoto=ORDENES.filter(function(o){
    return o.foto&&o.estado==='cerrada'&&o.cerradaTs&&(ahora-o.cerradaTs)>SIETE_DIAS;
  });
  ordenesConFoto.forEach(function(o){
    o.foto=null;
    fetch(SUPA_URL+'/rest/v1/ordenes?id=eq.'+o.id,{method:'PATCH',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},body:JSON.stringify({foto:null})}).catch(function(){});
  });
  if(ordenesConFoto.length>0){saveDB('ordenes',ORDENES);console.log('[FOTOS] Limpiadas '+ordenesConFoto.length+' fotos');}
  var pm3ConFoto=PM03_PLAN.filter(function(p){
    return p.fotos&&p.fotos.length&&p.estado==='cerrada'&&p.cerradaTs&&(ahora-p.cerradaTs)>SIETE_DIAS;
  });
  pm3ConFoto.forEach(function(p){
    p.fotos=[];
    fetch(SUPA_URL+'/rest/v1/pm03_plan?id=eq.'+p.id,{method:'PATCH',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},body:JSON.stringify({fotos:null})}).catch(function(){});
  });
  if(pm3ConFoto.length>0){saveDB('pm03_plan',PM03_PLAN);}
}

// ================================================================
// ESCALACIÓN AUTOMÁTICA — Correctivos temporales > 4 semanas → Prioridad A
// ================================================================
function _escalarCorreccionesTemporales(){
  var ahora=Date.now();
  var CUATRO_SEMANAS=4*7*24*60*60*1000;

  // Buscar PM03 generadas desde corrección temporal sin cerrar
  var pm3Temporales=PM03_PLAN.filter(function(p){
    return p.origenOT &&
           p.estado!=='cerrada' &&
           p.estado!=='reprogramada' &&
           (ahora-(p.ts||0))>CUATRO_SEMANAS;
  });

  if(!pm3Temporales.length) return;

  var semSiguiente=currentWeek()+1;
  var añoSig=currentYear();
  if(semSiguiente>52){semSiguiente=1;añoSig++;}

  var modificadas=[];

  pm3Temporales.forEach(function(p){
    var cambio=false;

    // Escalar prioridad a A si no lo es ya
    if(p.prioridad!=='A'){
      p.prioridad='A';
      cambio=true;
    }

    // Si la semana asignada ya pasó o no tiene semana, reprogramar a próxima semana
    var semActual=currentWeek();
    if(!p.semana||p.semana<semActual||(p.semana===semActual&&p.año<currentYear())){
      p.semana=semSiguiente;
      p.año=añoSig;
      p._editadoTs=Date.now();
      cambio=true;
    }

    if(cambio){
      modificadas.push(p);
      // PATCH directo a Supabase
      fetch(SUPA_URL+'/rest/v1/pm03_plan?id=eq.'+p.id,{
        method:'PATCH',
        headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
        body:JSON.stringify({
          prioridad:'A',
          semana:p.semana,
          anio:p.año,
          nota_reprogramacion:(p.notaReprogramacion||'')+'| Escalado automáticamente por corrección temporal > 4 semanas'
        })
      }).catch(function(){});
    }
  });

  if(modificadas.length>0){
    saveDB('pm03_plan',PM03_PLAN);
    console.log('[ESCALACIÓN] '+modificadas.length+' PM03 temporales escaladas a prioridad A para sem '+semSiguiente);
    // Mostrar alerta al admin
    if(currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super')){
      showAlert('⚠️ '+modificadas.length+' corrección(es) temporal(es) escaladas a Prioridad A — más de 4 semanas sin solución definitiva');
    }
  }
}
// ── FIN ESCALACIÓN ───────────────────────────────────────────────
function syncSupabase(){
  cargarProtocolosSupa();
  cargarChecklistConfig();
  // Cargar refacciones faltantes para badge
  supaFetch('refacciones_faltantes','GET',null,'estado=eq.levantada&limit=100').then(function(rows){
    if(rows){
      var stored=loadDB('ref_faltantes',[]);
      rows.forEach(function(r){if(!stored.find(function(s){return s.id===r.id;}))stored.unshift(r);});
      REF_FALTANTES=stored;
      saveDB('ref_faltantes',REF_FALTANTES);
    }
    actualizarBadgeRefFaltantes();
  }).catch(function(){});
  // Limpiar fotos de PMs cerradas hace más de 7 días
  _limpiarFotosAntiguas();
  // Escalar correctivos temporales > 4 semanas
  setTimeout(_escalarCorreccionesTemporales, 2000);
  // Sync notificaciones
  setTimeout(syncNotificaciones, 1500);
  // Actualizar badges admin
  setTimeout(actualizarBadgesAdmin, 2000);
  // Sync areas config
  supaFetch('areas_config','GET',null,'activa=eq.true&order=orden.asc').then(function(rows){
    if(rows&&rows.length){
      PM_AREAS=rows.map(function(r){return{id:r.id,label:r.label,icon:r.icon||'📍'};});
      saveDB('pm_areas_config',PM_AREAS);
    }
  }).catch(function(){});
  // Sync equipos por linea
  supaFetch('equipos_linea','GET',null,'activo=eq.true&limit=2000').then(function(rows){
    if(rows&&rows.length){
      EQUIPOS_LINEA=rows;
      saveDB('equipos_linea',EQUIPOS_LINEA);
    }
  }).catch(function(){});
  // Sync DOR planes
  supaFetch('dor_planes','GET',null,'order=creado_ts.desc&limit=500').then(function(rows){
    if(rows&&rows.length){
      DOR_PLANES=rows.map(function(r){return{
        id:r.id,descripcion:r.descripcion,responsable:r.responsable,
        prioridad:r.prioridad||'B',tipo:r.tipo||'plan',
        fechaVencimiento:r.fecha_vencimiento||'',estado:r.estado||'abierto',
        creadoPor:r.creado_por||'',creadoTs:r.creado_ts||0,
        cierreTs:r.cierre_ts||0,cierreNota:r.cierre_nota||'',
        cerradoPor:r.cerrado_por||'',bloqueo:r.bloqueo||null
      };});
      saveDB('dor_planes',DOR_PLANES);
      // Re-render DOR if open
      if(document.getElementById('dor-content')) renderDOR();
    }
  }).catch(function(){});
  supaFetch('usuarios','GET',null,'activo=eq.true').then(function(rows){
    if(!rows||!rows.length){supaUpsert('usuarios',DEFAULT_USERS.filter(function(u){return u.rol!=='super';}).map(function(u){return{id:u.id,username:u.username,nombre:u.nombre,password_hash:u.password,rol:u.rol,activo:true};})  ).catch(function(){});return;}
    // Filtrar super de los registros de Supabase para no sobreescribir
    var superLocal=USERS.filter(function(u){return u.rol==='super';});
    USERS=rows.filter(function(r){return r.rol!=='super';}).map(function(r){return{id:r.id,username:r.username,nombre:r.nombre,password:r.password_hash,rol:r.rol}});
    USERS=USERS.concat(superLocal);
    saveDB('users',USERS);
  }).catch(function(){});
  supaFetch('ordenes','GET',null,'order=ts.desc&limit=999999').then(function(rows){
    if(!rows)return;
    var localOrdenes = loadDB('ordenes',[]);
    var syncedIds = new Set(rows.map(function(r){return r.id;}));
    // Preservar órdenes locales que NO llegaron a Supabase (save pendiente)
    var localSoloIds = localOrdenes.filter(function(l){
      return !syncedIds.has(l.id) && (Date.now()-l.ts) < 86400000*7; // menos de 7 días
    });
    // Reintentar guardar en Supabase las que no llegaron
    if(localSoloIds.length){
      console.log('Reintentando sync de '+localSoloIds.length+' órdenes locales no sincronizadas');
      setTimeout(function(){
        localSoloIds.forEach(function(o){ saveOrdenSupa(o); });
      }, 2000);
    }
    ORDENES=rows.map(function(r){
      // Preservar estado local más reciente
      var local = localOrdenes.find(function(l){return l.id===r.id;});
      var estadoFinal = r.estado||'abierta';
      // Preservar estado local solo si NO hay motivo_rechazo
      // (si hay rechazo, el operador la mandó de vuelta a abierta intencionalmente)
      var tieneRechazo = r.motivo_rechazo || (local && local.motivoRechazo);
      if(local && (local.estado==='pre_cierre'||local.estado==='cerrada') 
         && estadoFinal==='abierta' && !tieneRechazo){
        estadoFinal = local.estado;
        setTimeout(function(){ saveOrdenSupa(local); }, 1000);
      }
      return {id:r.id,tipo:r.tipo,area:r.area,linea:r.linea,componente:r.componente,prioridad:r.prioridad,tipoAnormalidad:r.tipo_anormalidad,detalle:r.detalle,foto:local?local.foto:null,tecnicoAsignado:r.tecnico_asignado,tecnicoNombre:r.tecnico_nombre,levantadoPor:r.levantado_por,levantadoId:r.levantado_id,estado:estadoFinal,colorOT:r.color_ot,semana:r.semana,año:r.anio,ts:r.ts,observacionesCierre:r.observaciones_cierre,horasCierre:r.horas_cierre||0,horaInicioTrabajo:r.hora_inicio_trabajo,horaFinTrabajo:r.hora_fin_trabajo,fechaTrabajo:r.fecha_trabajo||null,cerradaTs:r.cerrada_ts,cerradaPor:r.cerrada_por,refaccionesUsadas:r.refacciones_usadas,causaRaiz:r.causa_raiz,horaLlamado:r.hora_llamado,horaInicio:r.hora_inicio,horaEntrega:r.hora_entrega,tiempoRespuesta:r.tiempo_respuesta,mttr:r.mttr,turno:r.turno,liderPM04:r.lider_pm04,historialReasignacion:r.historial_reasignacion||[],historialModificacion:r.historial_modificacion||[],motivoRechazo:r.motivo_rechazo||null,rechazadoPor:r.rechazado_por||null,preCierreTs:r.pre_cierre_ts||null,preCierrePor:r.pre_cierre_por||null,aprobadoPor:r.aprobado_por||null,rolLevantador:r.rol_levantador||null,esResueltaTemporal:r.es_resuelta_temporal||false,pm03Definitiva:r.pm03_definitiva||null,fuenteBitacora:r.fuente_bitacora||false,fuenteLabel:r.fuente_label||null,limpiezaRequerida:r.limpieza_requerida!=null?r.limpieza_requerida:null,limpiezaAvisadoA:r.limpieza_avisado_a||null,tecnicosAdicionales:(function(){try{return r.tecnicos_adicionales?JSON.parse(r.tecnicos_adicionales):[];}catch(e){return [];}})(),trabajoDias:(function(){try{return r.trabajo_dias?JSON.parse(r.trabajo_dias):[];}catch(e){return [];}})(),pendienteAsignacion:r.pendiente_asignacion||false,conciliadoCon:r.conciliado_con||null,conciliadoConNombre:r.conciliado_con_nombre||null,semanaResolucion:r.semana_resolucion||null};
    // Agregar órdenes locales no sincronizadas al array (pendientes de llegar a Supabase)
    }).concat(localSoloIds.map(function(l){
      // Intentar resync de estas órdenes
      setTimeout(function(){ saveOrdenSupa(l); }, 500);
      return l;
    }));
    saveDB('ordenes',ORDENES);
  }).catch(function(){});
  supaFetch('pm03_plan','GET',null,'order=semana.asc&limit=999999').then(function(rows){
    if(!rows)return;
    var localPM03=loadDB('pm03_plan',[]);
    PM03_PLAN=rows.map(function(r){
      // Preserve local cerrada state if Supabase has it as abierta (sync lag)
      var local=localPM03.find(function(l){return l.id===r.id;});
      var estadoFinal=r.estado;
      // Respetar ediciones locales recientes del super (10 minutos)
      if(local && local._editadoTs && (Date.now()-local._editadoTs)<1800000){
        estadoFinal=local.estado;
        setTimeout(function(){ savePM03Supa(local); },2000);
      } else if(local&&local.estado==='cerrada'&&r.estado==='abierta'){
        estadoFinal='cerrada';
        supaUpsert('pm03_plan',{id:r.id,estado:'cerrada',horas_cierre:local.horasCierre||0,observaciones_cierre:local.observacionesCierre||null,cerrada_ts:local.cerradaTs||null,cerrada_por:local.cerradaPor||null,tecnico_id:local.tecnicoId||null,tecnico_nombre:local.tecnicoNombre||null}).catch(function(){});
      }
      // Also: if Supabase has cerrada_ts but estado=abierta, fix it
      if(r.cerrada_ts&&r.estado==='abierta'){
        estadoFinal='cerrada';
        supaUpsert('pm03_plan',{id:r.id,estado:'cerrada'}).catch(function(){});
      }
      // Parse actividades_estado JSON
      var actEst = null;
      try{ if(r.actividades_estado) actEst=typeof r.actividades_estado==='string'?JSON.parse(r.actividades_estado):r.actividades_estado; }catch(e){}
      // Preservar actividadesEstado local si Supabase no lo tiene
      if(!actEst && local && local.actividadesEstado) actEst = local.actividadesEstado;
      return {id:r.id,linea:r.linea,componente:r.componente,actividad:r.actividad,area:r.area,
        semana:r.semana,año:r.anio,tecnicoId:r.tecnico_id,tecnicoNombre:r.tecnico_nombre,
        estado:estadoFinal,fuenteExcel:r.fuente_excel,esInspeccion:r.es_inspeccion,
        horasCierre:estadoFinal==='cerrada'&&local?local.horasCierre||r.horas_cierre||0:r.horas_cierre||0,
        horaInicio:r.hora_inicio||(local?local.horaInicio:null),
        horaFin:r.hora_fin||(local?local.horaFin:null),
        observacionesCierre:estadoFinal==='cerrada'&&local?local.observacionesCierre||r.observaciones_cierre:r.observaciones_cierre,
        cerradaTs:estadoFinal==='cerrada'&&local?local.cerradaTs||r.cerrada_ts:r.cerrada_ts,
        cerradaPor:estadoFinal==='cerrada'&&local?local.cerradaPor||r.cerrada_por:r.cerrada_por,
        generadoPor:r.generado_por,ts:r.ts,
        // Campos protocolo
        refaccionesUsadas:r.refacciones_usadas||(local?local.refaccionesUsadas:null),
        herramientaIngresada:r.herramienta_ingresada||(local?local.herramientaIngresada:null),
        herramientaSalida:r.herramienta_salida||(local?local.herramientaSalida:null),
        grasaAceite:r.grasa_aceite||(local?local.grasaAceite:null),
        limpiezaMtto:r.limpieza_mtto!=null?r.limpieza_mtto:(local?local.limpiezaMtto:null),
        desinfProduccion:r.desinf_produccion!=null?r.desinf_produccion:(local?local.desinfProduccion:null),
        actividadesEstado:actEst,
        // Campos liberación Calidad — PRIORITARIOS desde Supabase
        liberadoPor:r.liberado_por||(local?local.liberadoPor:null),
        liberadoTs:r.liberado_ts||(local?local.liberadoTs:null),
        estadoCalidad:r.estado_calidad||(local?local.estadoCalidad:null),
        rechazoCalidad:r.rechazo_calidad||(local?local.rechazoCalidad:null),
        firmaTecnico:r.firma_tecnico||(local?local.firmaTecnico:null),
        firmaTecnicoTs:r.firma_tecnico_ts||(local?local.firmaTecnicoTs:null),
        liberadoProdPor:r.liberado_prod_por||(local?local.liberadoProdPor:null),
        liberadoProdTs:r.liberado_prod_ts||(local?local.liberadoProdTs:null),
        liberadoAdminPor:r.liberado_admin_por||(local?local.liberadoAdminPor:null),
        liberadoAdminTs:r.liberado_admin_ts||(local?local.liberadoAdminTs:null),
        estadoFlujo:r.estado_flujo||(local?local.estadoFlujo:'ejecucion'),
        fotos:(function(){try{if(r.fotos)return JSON.parse(r.fotos);return local&&local.fotos?local.fotos:[];}catch(e){return local&&local.fotos?local.fotos:[];}}()),
        // Campos de borrador — priorizar Supabase sobre local
        comentariosActividades:(function(){
          var sup=r.comentarios_actividades;
          var loc=local?local.comentariosActividades:null;
          var supD=r.draft_ts||0, locD=local&&local._draftTs?local._draftTs:0;
          try{ sup=sup?JSON.parse(sup):null; }catch(e){ sup=null; }
          // Usar el más reciente
          if(supD>=locD) return sup||loc;
          return loc||sup;
        })(),
        horasActividades:(function(){try{return r.horas_actividades?JSON.parse(r.horas_actividades):(local?local.horasActividades:null);}catch(e){return local?local.horasActividades:null;}})(),
        personasActividades:(function(){try{return r.personas_actividades?JSON.parse(r.personas_actividades):(local?local.personasActividades:null);}catch(e){return local?local.personasActividades:null;}})(),
        diasTrabajo:(function(){
          var sup=r.dias_trabajo; var loc=local?local.diasTrabajo:null;
          var supD=r.draft_ts||0, locD=local&&local._draftTs?local._draftTs:0;
          try{ sup=sup?JSON.parse(sup):null; }catch(e){ sup=null; }
          if(supD>=locD) return sup||loc;
          return loc||sup;
        })(),
        actividadesEstadoInicial:(function(){try{return r.actividades_estado_inicial?JSON.parse(r.actividades_estado_inicial):(local?local.actividadesEstadoInicial:null);}catch(e){return local?local.actividadesEstadoInicial:null;}})(),
        actividadesEstadoFinal:(function(){try{return r.actividades_estado_final?JSON.parse(r.actividades_estado_final):(local?local.actividadesEstadoFinal:null);}catch(e){return local?local.actividadesEstadoFinal:null;}})(),
        reporteActividades:r.reporte_actividades||(local?local.reporteActividades:null),
        refaccionesNuevas:r.refacciones_nuevas||(local?local.refaccionesNuevas:null),
        _draftTs:r.draft_ts||(local?local._draftTs:0)
      };
    });
    saveDB('pm03_plan',PM03_PLAN);
  }).catch(function(){});
  supaFetch('refacciones','GET',null,'order=codigo.asc').then(function(rows){if(rows&&rows.length){REFACCIONES=rows;saveDB('refacciones',REFACCIONES);}}).catch(function(){});
  supaFetch('mtbf_data','GET',null,'order=anio.desc,semana.desc').then(function(rows){if(rows&&rows.length){MTBF_DATA=rows;saveDB('mtbf_data',MTBF_DATA);}}).catch(function(){});
  supaFetch('gasto_data','GET',null,'order=anio.asc,semana.asc').then(function(rows){if(rows&&rows.length){GASTO_DATA=rows;saveDB('gasto_data',GASTO_DATA);}}).catch(function(){});
  supaFetch('inspecciones','GET',null,'order=created_at.desc&limit=2000').then(function(rows){if(rows&&rows.length){INSPECCIONES=rows;saveDB('inspecciones',INSPECCIONES);}}).catch(function(){});
  // Process offline queue
  setTimeout(processSyncQueue, 2000);
}

function saveOrdenSupa(o){
  // Construir payload sin foto ni historiales (evitar payload grande)
  var payload = {
    id:o.id, tipo:o.tipo||'PM02', area:o.area||'', linea:o.linea||'',
    componente:o.componente||'', prioridad:o.prioridad||'C',
    tipo_anormalidad:o.tipoAnormalidad||null, detalle:(o.detalle||'').substring(0,500),
    tecnico_asignado:o.tecnicoAsignado||null,
    tecnico_nombre:o.tecnicoNombre||null,
    levantado_por:o.levantadoPor||'', levantado_id:o.levantadoId||'',
    estado:o.estado||'abierta', color_ot:o.colorOT||null,
    semana:o.semana||currentWeek(), anio:o.año||o.anio||currentYear(), ts:o.ts||Date.now(),
    observaciones_cierre:o.observacionesCierre||null,
    horas_cierre:o.horasCierre||0,
    hora_inicio_trabajo:o.horaInicioTrabajo||null,
    hora_fin_trabajo:o.horaFinTrabajo||null,
    fecha_trabajo:o.fechaTrabajo||null,
    pre_cierre_ts:o.preCierreTs||null,
    pre_cierre_por:o.preCierrePor||null,
    aprobado_por:o.aprobadoPor||null,
    rol_levantador:o.rolLevantador||null,
    motivo_rechazo:o.motivoRechazo||null,
    rechazado_por:o.rechazadoPor||null,
    cerrada_ts:o.cerradaTs||null,
    cerrada_por:o.cerradaPor||null,
    refacciones_usadas:o.refaccionesUsadas||null,
    causa_raiz:o.causaRaiz||null,
    hora_llamado:o.horaLlamado||null,
    hora_inicio:o.horaInicio||null,
    hora_entrega:o.horaEntrega||null,
    tiempo_respuesta:o.tiempoRespuesta||null,
    mttr:o.mttr||null,
    turno:o.turno||null,
    lider_pm04:o.liderPM04||null,
    es_trabajo_varios_dias:o.esTrabajoVariosDias||false,
    es_resuelta_temporal:o.esResueltaTemporal||false,
    pm03_definitiva:o.pm03Definitiva||null,
    fuente_bitacora:o.fuenteBitacora||false,
    fuente_label:o.fuenteLabel||null,
    tecnicos_adicionales:o.tecnicosAdicionales&&o.tecnicosAdicionales.length?JSON.stringify(o.tecnicosAdicionales):null,
    trabajo_dias:o.trabajoDias&&o.trabajoDias.length?JSON.stringify(o.trabajoDias):null,
    pendiente_asignacion:o.pendienteAsignacion||false,
    conciliado_con:o.conciliadoCon||null,
    conciliado_con_nombre:o.conciliadoConNombre||null,
    limpieza_requerida:o.limpiezaRequerida!=null?o.limpiezaRequerida:null,
    limpieza_avisado_a:o.limpiezaAvisadoA||null
  };
  return fetch(SUPA_URL+'/rest/v1/ordenes', {
    method: 'POST',
    headers: {
      'apikey': SUPA_KEY,
      'Authorization': 'Bearer '+SUPA_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'resolution=merge-duplicates,return=representation'
    },
    body: JSON.stringify(payload)
  }).then(function(r){
    if(!r.ok){
      return r.text().then(function(txt){
        console.error('saveOrdenSupa FAIL ['+o.id+']: '+txt);
        showAlert('⚠️ Error al sincronizar orden '+o.id.substring(0,15)+': '+txt.substring(0,80),'error');
        // Guardar en cola local para retry
        var q=loadDB('supa_retry_queue',[]);
        q.push({table:'ordenes',id:o.id,ts:Date.now()});
        saveDB('supa_retry_queue',q);
      });
    }
    return r.json().then(function(data){
      console.log('saveOrdenSupa OK: '+o.id+' estado:'+o.estado);
      return data;
    });
  }).catch(function(e){
    console.error('saveOrdenSupa CATCH:',e.message);
  });
}

// Reintentar órdenes fallidas
function reintentarOrdenesSync(){
  var local = loadDB('ordenes',[]);
  var pendientes = loadDB('ordenes_retry_queue',[]);
  if(!pendientes.length) return;
  var nuevasCola = [];
  pendientes.forEach(function(item){
    var o = local.find(function(x){return x.id===item.id;});
    if(o && (Date.now()-item.ts) < 3600000){ // máximo 1 hora
      saveOrdenSupa(o);
    }
  });
  saveDB('ordenes_retry_queue',[]);
}
setTimeout(reintentarOrdenesSync, 5000);
