function mostrarFormVariosDias(){
  var cont=document.getElementById('pm-wizard-container');
  var html='<div class="wizard-title">📅 Trabajo de Varios Días</div>'
    +'<div class="wizard-sub">Registra la fecha, hora inicio y hora fin por día</div>'
    +'<div style="margin-top:12px">';
  for(var i=1;i<=10;i++){
    html+='<div style="background:#f9fafb;border-radius:10px;padding:10px;margin-bottom:8px">'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
      +'<div style="width:24px;height:24px;background:var(--mo);color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0">'+i+'</div>'
      +'<input type="date" class="form-control" id="vd-fecha-'+i+'" style="flex:1;padding:7px;font-size:.85rem">'
      +'</div>'
      +'<div style="display:flex;gap:8px">'
      +'<div style="flex:1"><label style="font-size:.72rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Hora inicio</label>'
      +'<input type="time" class="form-control" id="vd-ini-'+i+'" style="padding:7px;font-size:.85rem" onchange="calcVdHoras('+i+')"></div>'
      +'<div style="flex:1"><label style="font-size:.72rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Hora fin</label>'
      +'<input type="time" class="form-control" id="vd-fin-'+i+'" style="padding:7px;font-size:.85rem" onchange="calcVdHoras('+i+')"></div>'
      +'<div style="flex:1"><label style="font-size:.72rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Horas</label>'
      +'<input type="number" class="form-control" id="vd-horas-'+i+'" placeholder="0" min="0" max="24" step="0.25" style="padding:7px;font-size:.85rem"></div>'
      +'</div></div>';
  }
  html+='</div>';
  cont.innerHTML=html;
  var saveBtn=document.createElement('button');
  saveBtn.className='btn btn-success mt8';
  saveBtn.textContent='💾 Guardar con registro diario';
  saveBtn.onclick=guardarOTVariosDias;
  cont.appendChild(saveBtn);
  var skipBtn=document.createElement('button');
  skipBtn.className='btn btn-gray mt8';
  skipBtn.textContent='📋 Guardar como Abierta sin días';
  skipBtn.onclick=function(){pmState.resuelta=false;pmState._tsOrden=Date.now();guardarOT();};
  cont.appendChild(skipBtn);
  document.getElementById('pm-btn-next').style.display='none';
}

function calcVdHoras(i){
  var ini=document.getElementById('vd-ini-'+i);
  var fin=document.getElementById('vd-fin-'+i);
  var hrs=document.getElementById('vd-horas-'+i);
  if(!ini||!fin||!hrs||!ini.value||!fin.value) return;
  var p1=ini.value.split(':').map(Number);
  var p2=fin.value.split(':').map(Number);
  var mins=(p2[0]*60+p2[1])-(p1[0]*60+p1[1]);
  if(mins<0) mins+=1440;
  hrs.value=parseFloat((mins/60).toFixed(2));
}

function guardarOTVariosDias(){
  var dias=[];
  for(var i=1;i<=10;i++){
    var f=document.getElementById('vd-fecha-'+i);
    var h=document.getElementById('vd-horas-'+i);
    var ini=document.getElementById('vd-ini-'+i);
    var fin=document.getElementById('vd-fin-'+i);
    if(f&&f.value&&h&&parseFloat(h.value)>0){
      dias.push({
        fecha:f.value,
        horas:parseFloat(h.value),
        horaInicio:ini?ini.value:'',
        horaFin:fin?fin.value:''
      });
    }
  }
  if(!dias.length){showAlert('Registra al menos un día con horas','error');return;}
  pmState.trabajoDias=dias;
  pmState.horasCierre=dias.reduce(function(s,d){return s+d.horas;},0);
  pmState.esTrabajoVariosDias=true;
  // Fecha de la orden = primer día
  var primerDia=dias[0].fecha;
  pmState.fechaTrabajo=primerDia;
  pmState._tsOrden=new Date(primerDia+'T'+(dias[0].horaInicio||'08:00')+':00').getTime();
  pmState._semOrden=getWeekNumber(new Date(primerDia+'T12:00:00'));
  pmState._añoOrden=new Date(primerDia+'T12:00:00').getFullYear();
  pmState.resuelta=true;
  guardarOT();
}

// ================================================================
// FOTO DESDE GALERÍA
// ================================================================
function tomarFotoOGaleria(callback){
  var inp=document.createElement('input');
  inp.type='file';
  inp.accept='image/*';
  inp.style.display='none';
  inp.onchange=function(e){
    if(!e.target.files.length)return;
    var reader=new FileReader();
    reader.onload=function(ev){if(callback)callback(ev.target.result);};
    reader.readAsDataURL(e.target.files[0]);
  };
  document.body.appendChild(inp);
  inp.click();
  setTimeout(function(){document.body.removeChild(inp);},1000);
}

