// Helper: rango de fechas de un mes completo
function getMesRange(mes, año){
  var inicio = new Date(año, mes-1, 1);
  var fin    = new Date(año, mes, 0);
  return {
    inicio: inicio.toISOString().split('T')[0],
    fin:    fin.toISOString().split('T')[0]
  };
}

// ── TÉCNICOS ADICIONALES en wizard PM ───────────────────────────
function pmAddExtraTec(){
  if(!pmState.tecnicosAdicionales) pmState.tecnicosAdicionales=[];
  pmState.tecnicosAdicionales.push({id:'',nombre:'',horas:0});
  renderPMStep();
}
function pmRemoveExtraTec(idx){
  if(!pmState.tecnicosAdicionales) return;
  pmState.tecnicosAdicionales.splice(idx,1);
  renderPMStep();
}
function pmUpdateExtraTec(idx,sel){
  if(!pmState.tecnicosAdicionales) return;
  var u=USERS.find(function(x){return x.id===sel.value;});
  pmState.tecnicosAdicionales[idx].id=sel.value;
  pmState.tecnicosAdicionales[idx].nombre=u?u.nombre:'';
}
function pmUpdateExtraHrs(idx,inp){
  if(!pmState.tecnicosAdicionales) return;
  pmState.tecnicosAdicionales[idx].horas=parseFloat(inp.value)||0;
}

