// Se llama desde renderKPIs, busca el elemento kpi-pendientes-aprobacion
function renderPendientesAprobacion(){
  var el = document.getElementById('kpi-pendientes-aprobacion');
  if(!el) return;
  var pendientes = ORDENES.filter(function(o){return o.estado==='pre_cierre';});
  if(!pendientes.length){ el.innerHTML=''; return; }
  el.innerHTML='<div style="display:flex;align-items:center;gap:8px;margin-top:6px;background:#f0e6ff;border-radius:8px;padding:8px 10px">'
    +'<div style="font-size:1.1rem;font-weight:800;color:#7c3aed">'+pendientes.length+'</div>'
    +'<div style="font-size:.75rem;font-weight:700;color:#7c3aed;flex:1">Pendientes<br>de aprobar</div>'
    +'<button onclick="descargarPendientesAprobacion()" style="background:#7c3aed;color:#fff;border:none;border-radius:7px;padding:5px 10px;font-size:.72rem;font-weight:700;cursor:pointer">⬇️ Descargar</button>'
    +'</div>';
}

function descargarPendientesAprobacion(){
  var rows = ORDENES.filter(function(o){return o.estado==='pre_cierre';});
  if(!rows.length){showAlert('Sin pendientes de aprobación','error');return;}
  var hdrs=['ID','Tipo','Área','Línea','Componente','Tipo Anormalidad','Levantado Por','Técnico','Pre-cierre Por','Observaciones','Horas','Refacciones','Fecha Creación','Fecha Pre-cierre'];
  var data=rows.map(function(o){return[o.id,o.tipo,o.area||'',o.linea||'',o.componente||'',o.tipoAnormalidad||'',o.levantadoPor||'',o.tecnicoNombre||'',o.preCierrePor||'',o.observacionesCierre||'',o.horasCierre||0,o.refaccionesUsadas||'',fmtDate(o.ts),o.preCierreTs?fmtDate(o.preCierreTs):''];});
  generarExcelXML(hdrs,data,'Pendientes_Aprobacion_'+new Date().toISOString().slice(0,10)+'.xlsx','Pendientes');
  showAlert('✅ Excel descargado — '+rows.length+' pendientes');
}
