// ================================================================
// RECHAZO DE CIERRE — Operador/Lider regresa la OT al técnico
// ================================================================
function rechazarCierre(id){
  var modal = document.createElement('div');
  modal.id = 'modal-rechazo';
  modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML =
    '<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#dc2626;margin-bottom:4px">❌ Rechazar cierre</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">La orden volverá a estar <strong>Abierta</strong> para que el técnico la atienda de nuevo.</div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:6px">Motivo del rechazo <span style="color:#dc2626">*</span></label>'
    +'<textarea id="rechazo-motivo" rows="3" placeholder="Describe por qué rechazas el cierre..." style="width:100%;box-sizing:border-box;padding:10px;border:1.5px solid #d1d5db;border-radius:10px;font-size:.9rem;font-family:inherit;resize:none"></textarea></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-rechazo\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;font-size:.9rem;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarRechazo(\''+id+'\')" style="flex:1;padding:13px;background:#dc2626;color:#fff;border:none;border-radius:11px;font-size:.9rem;font-weight:700;cursor:pointer">❌ Rechazar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function confirmarRechazo(id){
  var motivo = (document.getElementById('rechazo-motivo')||{}).value||'';
  if(!motivo.trim()){ showAlert('Escribe el motivo del rechazo','error'); return; }
  var o = ORDENES.find(function(x){return x.id===id;});
  if(!o) return;

  // Regresar a abierta con comentario del rechazo
  o.estado = 'abierta';
  o.preCierreTs = null;
  o.preCierrePor = null;
  o.rechazadoPor = currentUser.nombre;
  o.rechazadoTs  = Date.now();
  o.motivoRechazo = motivo.trim();

  if(!o.historialModificacion) o.historialModificacion=[];
  o.historialModificacion.push({
    ts: Date.now(),
    por: currentUser.nombre,
    campo: 'Rechazo de cierre',
    de: 'pre_cierre',
    a: 'abierta — ' + motivo.trim()
  });

  saveDB('ordenes', ORDENES);
  // PATCH directo — solo actualizar los campos de estado (más ligero y confiable)
  supabaseStatePatch(o.id, {
    estado: 'abierta',
    pre_cierre_ts: null,
    pre_cierre_por: null,
    rechazado_por: o.rechazadoPor,
    motivo_rechazo: o.motivoRechazo
  });

  var modal = document.getElementById('modal-rechazo');
  if(modal) modal.remove();
  showAlert('↩️ Cierre rechazado — la orden está abierta nuevamente para el técnico');

  // Si estamos en el detalle, recargar
  if(document.getElementById('screen-detalle').classList.contains('active')){
    showDetalle(id);
  } else {
    showAnormalidadesPorAprobar();
  }
}
// ── FIN RECHAZO ───────────────────────────────────────────────────

