// ================================================================
// RESUELTA TEMPORALMENTE — Cierra PM02 y genera PM03 definitiva
// ================================================================
function guardarRessueltaTemporalmente(){
  var t = document.getElementById('inp-detalle');
  if(t) pmState.detalle = t.value.trim();
  if(!pmState.detalle){ showAlert('Escribe el detalle primero','error'); return; }

  // Las horas ya están en pmState.horasCierre desde confirmarResolucion
  var hrs = pmState.horasCierre||0;
  if(hrs<=0){ showAlert('Las horas se calculan automáticamente — verifica hora inicio y fin','error'); return; }

  // 1. Guardar PM02 como cerrada (resuelta temporalmente)
  pmState.resuelta = true;
  pmState.esResueltaTemporal = true;

  var idPM02 = genID(pmTipo);
  var fechaOT = (function(){
    var f = document.getElementById('pm-fecha-orden');
    if(f && f.value && f.value !== todayStr()) return new Date(f.value+'T12:00:00').getTime();
    return Date.now();
  })();

  var tecId = pmState.tecnicoAsignado||'';
  var tecNom = pmState.tecnicoNombre||'Sin asignar';
  if(currentUser.rol==='tecnico' && !tecId){ tecId=currentUser.id; tecNom=currentUser.nombre; }

  // Generar folio PM03
  var idPM03 = genID('PM03');

  var pm02 = {
    id: idPM02, tipo: pmTipo,
    area: pmState.area, linea: pmState.lineaDisplay||pmState.linea,
    componente: pmState.componente||'—', prioridad: pmState.prioridad,
    tipoAnormalidad: pmState.tipoAnormalidadDisplay||pmState.tipoAnormalidad||'—',
    detalle: pmState.detalle, foto: pmState.foto||null,
    tecnicoAsignado: tecId, tecnicoNombre: tecNom,
    levantadoPor: currentUser.nombre, levantadoId: currentUser.id,
    rolLevantador: currentUser.rol,
    ts: fechaOT, horaCreacion: new Date().toISOString(),
    estado: 'cerrada', semana: currentWeek(), año: currentYear(),
    colorOT: pmState.colorOT||null,
    observacionesCierre: 'Resuelta temporalmente. PM03 generada: '+idPM03,
    horasCierre: hrs,
    cerradaTs: Date.now(), cerradaPor: currentUser.nombre,
    esResueltaTemporal: true,
    pm03Definitiva: idPM03,
    historialReasignacion: [], historialModificacion: []
  };

  // 2. Generar PM03 para solución definitiva — sin semana para que vaya a "Por Reprogramar"
  var pm03 = {
    id: idPM03,
    linea: pmState.lineaDisplay||pmState.linea,
    componente: pmState.componente||'—',
    actividad: 'Solución definitiva — '+pmTipo+' '+idPM02+' — '+pmState.detalle,
    area: pmState.area,
    semana: null,
    año: currentYear(),
    tecnicoId: tecId,
    tecnicoNombre: tecNom,
    estado: 'abierta',
    estadoFlujo: 'por_reprogramar',
    generadoPor: nombreEfectivo()||'Sistema',
    origenPM02: idPM02,
    esResueltaTemporal: true,
    ts: Date.now(),
    horaCreacion: new Date().toISOString(),
    observacionesCierre: null,
    horasCierre: 0
  };

  ORDENES.push(pm02);
  saveDB('ordenes', ORDENES);
  saveDB('pm_draft_'+currentUser.id, null);
  saveOrdenSupa(pm02);

  PM03_PLAN.push(pm03);
  saveDB('pm03_plan', PM03_PLAN);
  savePM03Supa(pm03);

  showAlert('✅ '+idPM02+' cerrada como temporal | PM03 '+idPM03+' generada para solución definitiva');
  goMenu();
}
// ── FIN RESUELTA TEMPORALMENTE ───────────────────────────────────

// ================================================================
// PATCH LIGERO — solo actualiza campos específicos en Supabase
// Más confiable que upsert completo para cambios de estado
// ================================================================
function supabaseStatePatch(id, fields){
  return fetch(SUPA_URL+'/rest/v1/ordenes?id=eq.'+id, {
    method: 'PATCH',
    headers: {
      'apikey': SUPA_KEY,
      'Authorization': 'Bearer '+SUPA_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify(fields)
  }).then(function(r){
    if(!r.ok){
      return r.text().then(function(txt){
        console.error('supabaseStatePatch FAIL ['+id+']: '+txt);
        showAlert('⚠️ Error actualizando estado: '+txt.substring(0,60),'error');
      });
    } else {
      console.log('supabaseStatePatch OK: '+id+' → '+JSON.stringify(fields).substring(0,60));
    }
  }).catch(function(e){
    console.error('supabaseStatePatch CATCH:', e.message);
  });
}

function saveHistorialSupa(ordenId, campo, de, a){
  var entry={orden_id:ordenId,ts:Date.now(),por:currentUser?currentUser.nombre:'Sistema',campo:campo,de:String(de||''),a:String(a||'').substring(0,200)};
  var o=ORDENES.find(function(x){return x.id===ordenId;});
  if(o){if(!o.historialModificacion)o.historialModificacion=[];o.historialModificacion.push(entry);saveDB('ordenes',ORDENES);}
  fetch(SUPA_URL+'/rest/v1/historial_ordenes',{method:'POST',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},body:JSON.stringify(entry)}).then(function(r){if(!r.ok)r.text().then(function(t){console.error('historial error:',t);});}).catch(function(e){console.error('historial catch:',e.message);});
}
async function loadHistorialSupa(ordenId){
  var r=await fetch(SUPA_URL+'/rest/v1/historial_ordenes?orden_id=eq.'+ordenId+'&order=ts.asc',{headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Accept':'application/json'}});
  if(!r.ok)return [];
  return await r.json();
}

