    +'<button onclick="document.getElementById(\'modal-atc-opciones\').remove()" style="padding:14px;background:#f3f4f6;border:none;border-radius:12px;font-size:.9rem;cursor:pointer">Cancelar</button>'
    +'</div></div>';
