function guardarAtencionTemporal(){
  var hrs=pmState.horasCierre||0;
  if(hrs<=0){showAlert('Las horas se calculan automáticamente — verifica hora inicio y fin','error');return;}
  var tipo=atencionState.tipoPM||'PM01';
  var idPM=genID(tipo),idPM3=genID('PM03');
  var tr=null,mttr=null;
  if(atencionState.horaLlamado&&atencionState.horaInicio)tr=Math.round((atencionState.horaInicio-atencionState.horaLlamado)/60000);
  if(atencionState.horaInicio&&atencionState.horaEntrega)mttr=Math.round((atencionState.horaEntrega-atencionState.horaInicio)/60000);
  var ot={id:idPM,tipo,area:'productiva',linea:atencionState.lineaDisplay||'—',componente:atencionState.componente||'—',prioridad:'A',tipoAnormalidad:'Paro Menor',colorOT:tipo==='PM02'?'rojo':null,detalle:atencionState.falla||'Atención a línea',causaRaiz:atencionState.causaRaiz,foto:atencionState.foto||null,tecnicoAsignado:currentUser.id,tecnicoNombre:currentUser.nombre,levantadoPor:nombreEfectivo(),levantadoId:currentUser.id,rolLevantador:currentUser.rol,ts:Date.now(),fecha:atencionState.fecha||todayStr(),esAtencion:true,turno:getTurno(),estado:'cerrada',semana:currentWeek(),año:currentYear(),horaLlamado:atencionState.horaLlamado,horaInicio:atencionState.horaInicio,horaEntrega:atencionState.horaEntrega,tiempoRespuesta:tr,mttr,liderPM04:atencionState.liderPM04||null,refaccionesUsadas:atencionState.refacciones||'',horasCierre:hrs,observacionesCierre:'Resuelta temporalmente. PM03 generada: '+idPM3,cerradaTs:Date.now(),cerradaPor:nombreEfectivo(),esResueltaTemporal:true,pm03Definitiva:idPM3,historialReasignacion:[],historialModificacion:[]};
  var pm03={id:idPM3,linea:atencionState.lineaDisplay||'—',componente:atencionState.componente||'—',actividad:'Solución definitiva — '+tipo+' '+idPM+' — '+(atencionState.falla||'Atención a línea'),area:'productiva',semana:currentWeek(),año:currentYear(),tecnicoId:currentUser.id,tecnicoNombre:currentUser.nombre,estado:'abierta',generadoPor:nombreEfectivo()||'Sistema',origenPM02:idPM,esResueltaTemporal:true,ts:Date.now(),horaCreacion:new Date().toISOString(),observacionesCierre:null,horasCierre:0};
  ORDENES.push(ot);saveDB('ordenes',ORDENES);saveOrdenSupa(ot);
  PM03_PLAN.push(pm03);saveDB('pm03_plan',PM03_PLAN);savePM03Supa(pm03);
  if(currentSlot){ATENCION_SLOTS[currentSlot]=null;saveDB('atencion_slots',ATENCION_SLOTS);updateSlotPreview();}
  showAlert('✅ '+idPM+' cerrada como temporal | PM03 '+idPM3+' generada');
  goMenu();
}

function superEliminarOT(id){
  var o=ORDENES.find(function(x){return x.id===id;});
  if(!o)return;
  if(!confirm('⚠️ ¿ELIMINAR permanentemente la orden '+id+'?\n\nEsta acción no se puede deshacer.'))return;
  ORDENES=ORDENES.filter(function(x){return x.id!==id;});saveDB('ordenes',ORDENES);
  var deleted=loadDB('ordenes_eliminadas',[]);if(deleted.indexOf(id)<0){deleted.push(id);saveDB('ordenes_eliminadas',deleted);}
  var q=loadDB('supa_retry_queue',[]);saveDB('supa_retry_queue',q.filter(function(x){return x.id!==id;}));
  fetch(SUPA_URL+'/rest/v1/ordenes?id=eq.'+id,{method:'DELETE',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Prefer':'return=minimal'}}).then(function(r){if(r.ok){showAlert('🗑️ Orden '+id+' eliminada');}else{r.text().then(function(t){showAlert('⚠️ Error: '+t.substring(0,60),'error');});}});
  fetch(SUPA_URL+'/rest/v1/historial_ordenes?orden_id=eq.'+id,{method:'DELETE',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY}});
  var prev=detalleBackScreen||'screen-ordenes';showScreen(prev);
}
function buildSuperEditFields(o){
  var fechaVal=new Date(o.ts).toISOString().split('T')[0];
  var tecOpts=USERS.filter(function(u){return u.rol==='tecnico';}).map(function(u){return '<option value="'+u.id+'"'+(o.tecnicoAsignado===u.id?' selected':'')+'>'+u.nombre+'</option>';}).join('');
  return '<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">📅 Fecha (retroactiva)</label>'
    +'<input type="date" id="eot-fecha" class="form-control" value="'+fechaVal+'" style="padding:10px"></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">👨‍🔧 Técnico Asignado</label>'
    +'<select id="eot-tecnico" class="form-control" style="padding:10px">'+tecOpts+'</select></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">📝 Detalle</label>'
    +'<textarea id="eot-detalle" class="form-control" rows="3" style="padding:10px">'+(o.detalle||'')+'</textarea></div>';
}

function capturarFechaHoraPM(){
  var f=document.getElementById('pm-fecha-orden');
  var h=document.getElementById('pm-hora-orden');
  var fecha=f&&f.value?f.value:todayStr();
  var hora=h&&h.value?h.value:nowTimeStr();
  var ts=new Date(fecha+'T'+hora+':00').getTime();
  pmState._tsOrden=ts;
  pmState._semOrden=getWeekNumber(new Date(fecha+'T12:00:00'));
  pmState._añoOrden=new Date(fecha+'T12:00:00').getFullYear();
  console.log('Fecha PM:',fecha,hora,'→ ts:',ts);
}

function nombreEfectivo(){
  try{
    if(!currentUser||currentUser.rol!=='super') return currentUser?currentUser.nombre:'';
    // Super: usar nombre del usuario seleccionado o vacío
    if(window._superCierraPor) return window._superCierraPor.nombre;
    if(window._superLevantadorActual) return window._superLevantadorActual.nombre;
    if(typeof pmState!=='undefined'&&pmState&&pmState.tecnicoNombre) return pmState.tecnicoNombre;
    return ''; // Super no deja rastro si no hay usuario seleccionado
  }catch(e){return currentUser?currentUser.nombre:'';}
}
function idEfectivo(){
  try{if(currentUser&&currentUser.rol==='super'&&typeof pmState!=='undefined'&&pmState&&pmState.tecnicoAsignado)return pmState.tecnicoAsignado;return currentUser?currentUser.id:'';}catch(e){return currentUser?currentUser.id:'';}
}

// ================================================================
// PROTOCOLOS DE MANTENIMIENTO PREVENTIVO PM03
// ================================================================
var PROTOCOLOS_PM03_SUPA = []; // Cargados de Supabase
var PROTOCOLOS_PM03 = {}; // Los protocolos se gestionan desde Admin → Protocolos PM03

function getProtocoloPM03(linea){
  if(!linea) return null;
  // Buscar primero en protocolos de Supabase (dinámicos)
  for(var i=0;i<PROTOCOLOS_PM03_SUPA.length;i++){
    var s=PROTOCOLOS_PM03_SUPA[i];
    if(s.linea===linea||linea.indexOf(s.linea)>=0||s.linea.indexOf(linea)>=0)
      return {equipo:s.equipo,equipoSecundario:s.equipo_secundario,codigo:s.codigo||'REG-MTT-002.02',actividades:s.actividades||[]};
  }
  // Fallback a hardcoded
  var keys=Object.keys(PROTOCOLOS_PM03);
  for(var j=0;j<keys.length;j++){
    if(linea===keys[j]||linea.indexOf(keys[j])>=0||keys[j].indexOf(linea)>=0)
      return PROTOCOLOS_PM03[keys[j]];
  }
  return null;
}

// Cargar protocolos de Supabase al iniciar
function cargarProtocolosSupa(){
  supaFetch('protocolos_pm03','GET',null,'activo=eq.true&order=linea.asc').then(function(rows){
    if(rows&&rows.length){
      PROTOCOLOS_PM03_SUPA=rows;
      console.log('Protocolos cargados:',rows.length);
    }
  }).catch(function(){});
}

// ================================================================
// LIBERACIÓN DE MTTO — Calidad valida PM03 ejecutadas
// ================================================================
function showLiberacionMtto(){
  detalleBackScreen = 'screen-ordenes';
  // Buscar PM03 cerradas pendientes de liberación (sin liberadoPor)
  var pm3Cerradas = PM03_PLAN.filter(function(p){
    return p.estado === 'cerrada' && !p.liberadoPor && p.estadoCalidad!=='liberada';
  }).sort(function(a,b){ return (b.cerradaTs||b.ts||0)-(a.cerradaTs||a.ts||0); });

  var lDiv = document.getElementById('mis-ordenes-list');
  var fDiv = document.getElementById('ordenes-filtros');

  if(fDiv) fDiv.innerHTML = '<div style="background:#0891b2;color:#fff;border-radius:10px;padding:10px 14px;font-size:.88rem;font-weight:700;margin-bottom:8px">🔬 PM03 pendientes de liberación de Calidad</div>';

  if(!pm3Cerradas.length){
    lDiv.innerHTML = '<div class="card text-center" style="padding:40px"><div style="font-size:48px">✅</div><div style="font-weight:700;margin-top:12px">Sin PM03 pendientes de liberación</div></div>';
  } else {
    lDiv.innerHTML = pm3Cerradas.map(function(p){
      return '<div class="ot-card pm03" onclick="showLiberacionDetalle(\''+p.id+'\')" style="border-left:4px solid #0891b2">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">'
        +'<span style="font-size:11px;color:#0891b2;font-weight:700">'+p.id+'</span>'
        +'<span class="badge" style="background:#0891b2;color:#fff">⏳ Pendiente liberación</span>'
        +'</div>'
        +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;margin:2px 0 4px">'+p.linea+' — '+(p.componente||p.actividad?.substring(0,40)||'PM03')+'</div>'
        +'<div style="font-size:12px;color:var(--txt2)">Semana '+p.semana+' / '+p.año+'</div>'
        +'<div style="font-size:12px;color:var(--txt2);margin-top:2px">👨‍🔧 '+(p.tecnicoNombre||'—')+'</div>'
        +'<div style="margin-top:8px">'
        +'<button class="btn btn-success" style="font-size:13px;padding:10px" onclick="event.stopPropagation();liberarPM03(\''+p.id+'\')">✅ Liberar</button>'

        +'</div></div>';
    }).join('');
  }
  showScreen('screen-ordenes');
}

function liberarPM03(id){
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;

  // Modal de confirmación con opción de limpieza
  var modal = document.createElement('div');
  modal.id = 'modal-liberar-pm03';
  modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  var reqLimp = p.limpiezaMtto || p.desinfProduccion;
  modal.innerHTML = '<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">🔬 Liberar PM03</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">'+p.linea+' — Sem '+p.semana+'/'+p.año+'</div>'
    +'<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:12px;margin-bottom:14px;font-size:.88rem;color:#166534">'
    +'✅ Confirmo la liberación de línea por limpieza y sanitización para arranque.</div>'
    +(reqLimp
      ?'<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:10px;padding:12px;margin-bottom:14px">'
        +'<div style="font-size:.85rem;font-weight:700;color:#92400e;margin-bottom:8px">⚠️ Esta línea requiere limpieza y/o sanitización antes del arranque</div>'
        +'<div style="font-size:.8rem;color:#78350f;margin-bottom:8px">¿Te diste por enterado y confirmas que se realizará antes del arranque?</div>'
        +'<div style="display:flex;gap:8px">'
        +'<button id="limp-si-btn" onclick="calToggleLimp(true)" style="flex:1;padding:10px;border:2px solid #d97706;border-radius:8px;background:#fff;font-weight:700;font-size:.85rem;cursor:pointer">✅ Me doy por enterado</button>'
        +'</div></div>'
      :'')
    +'<div style="display:flex;gap:10px;margin-top:8px">'
    +'<button onclick="var m=document.getElementById(\'modal-liberar-pm03\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;font-size:.9rem;cursor:pointer">Cancelar</button>'
    +'<button id="btn-confirmar-liberar" onclick="confirmarLiberarPM03(\''+id+'\')" style="flex:1;padding:13px;background:#16a34a;color:#fff;border:none;border-radius:11px;font-size:.95rem;font-weight:700;cursor:pointer">✅ Liberar Equipo</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  window._calLimpConfirmado = !reqLimp; // Si no requiere limpieza, ya está confirmado
}

function calToggleLimp(val){
  window._calLimpConfirmado = val;
  var btn = document.getElementById('limp-si-btn');
  if(btn){btn.style.background='#d97706';btn.style.color='#fff';}
}

function confirmarLiberarPM03(id){
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var reqLimp = p.limpiezaMtto || p.desinfProduccion;
  if(reqLimp && !window._calLimpConfirmado){
    showAlert('Debes confirmar que te diste por enterado de la limpieza requerida','error');
    return;
  }
  p.liberadoPor   = currentUser.nombre;
  p.liberadoTs    = Date.now();
  p.estadoCalidad = 'liberada';
  p.estadoFlujo   = 'pendiente_produccion';
  p.calLimpConfirmada = window._calLimpConfirmado;
  saveDB('pm03_plan', PM03_PLAN);
  savePM03Supa(p);
  var m = document.getElementById('modal-liberar-pm03');if(m)m.remove();
  showAlert('✅ PM03 liberada por Calidad — enviada a Producción');
  showMisOrdenes();
}

function rechazarLiberacionPM03(id){
  var motivo = prompt('Motivo del rechazo de Calidad:');
  if(!motivo) return;
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  p.rechazoCalidad  = motivo;
  p.rechazadoCalPor = currentUser.nombre;
  p.rechazadoCalTs  = Date.now();
  p.estadoCalidad   = 'rechazada';
  p.estado          = 'abierta'; // Regresa a abierta para que técnico corrija
  saveDB('pm03_plan', PM03_PLAN);
  savePM03Supa(p);
  showAlert('↩️ PM03 rechazada — regresa al técnico');
  showLiberacionMtto();
}

function showLiberacionDetalle(id){
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p){ showAlert('PM03 no encontrada','error'); return; }
  var proto = getProtocoloPM03(p.linea);
  var actHTML = '';
  if(proto && proto.actividades){
    actHTML = '<div class="card"><div class="card-title">📋 Actividades del Protocolo</div>'
      +'<div class="table-wrap"><table><thead><tr><th>#</th><th>Descripción</th><th>Esp.</th><th>Estado</th></tr></thead><tbody>'
      +proto.actividades.map(function(a){
        var est = (p.actividadesEstado||{})[a.id] || '—';
        var col = est==='A'?'#16a34a':est==='B'?'#d97706':est==='C'?'#dc2626':'#6b7280';
        return '<tr><td>'+a.id+'</td><td style="font-size:11px">'+a.desc+'</td><td>'+a.esp+'</td>'
          +'<td style="font-weight:800;color:'+col+'">'+est+'</td></tr>';
      }).join('')
      +'</tbody></table></div></div>';
  }
  var html = '<div class="card"><div class="card-title">🔬 '+p.id+'</div>'
    +'<div class="info-row"><span>Línea</span><span>'+p.linea+'</span></div>'
    +'<div class="info-row"><span>Técnico</span><span>'+(p.tecnicoNombre||'—')+'</span></div>'
    +'<div class="info-row"><span>Semana</span><span>'+p.semana+' / '+p.año+'</span></div>'
    +'<div class="info-row"><span>Estado</span><span>'+(p.estadoCalidad||'Pendiente')+'</span></div>'
    +(p.observacionesCierre?'<div class="info-row"><span>Observaciones</span><span>'+p.observacionesCierre+'</span></div>':'')
    +'</div>'+actHTML
    +'<div style="display:flex;gap:10px;padding:0 16px 24px">'
    +'<button class="btn btn-success" onclick="liberarPM03(\''+id+'\')" style="flex:1">✅ Liberar</button>'

    +'</div>';
  document.getElementById('detalle-content').innerHTML = html;
  detalleBackScreen = 'screen-ordenes';
  showScreen('screen-detalle');
}
// ── FIN LIBERACIÓN MTTO ──────────────────────────────────────────

