// ================================================================
// PROTOCOLO REG-MTT — Impresión / PDF con firma de Calidad
// ================================================================
function firmaCelda(titulo, nombre, ts, comentario){
  var firmado = !!nombre;
  var fecha = ts ? new Date(ts).toLocaleDateString('es-MX',{day:'2-digit',month:'2-digit',year:'numeric'}) : '';
  return '<td style="text-align:center;padding:8px;width:25%;background:'+(firmado?'#dcfce7':'#fff')+'">'
    +'<div style="height:50px;border-bottom:1px solid #000;margin-bottom:4px;display:flex;align-items:flex-end;justify-content:center">'
    +(firmado?'<div style="font-size:14px;font-weight:800;color:#16a34a">✅ LIBERADO</div>':'')
    +'</div>'
    +'<div style="font-weight:700;font-size:10px">'+titulo+'</div>'
    +'<div style="font-size:10px;font-weight:'+(firmado?'800':'400')+';color:'+(firmado?'#16a34a':'#000')+'">'+(nombre||'___________________')+'</div>'
    +'<div style="font-size:9px;color:#555">'+(fecha||'Firma y Nombre')+'</div>'
    +(comentario?'<div style="font-size:9px;color:#374151;font-style:italic;margin-top:2px">'+comentario+'</div>':'')
    +'</td>';
}

function imprimirProtocoloPM03(id){
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p){showAlert('PM03 no encontrada','error');return;}
  var proto = getProtocoloPM03(p.linea);
  var win = window.open('','_blank');
  if(!win){showAlert('Activa ventanas emergentes para imprimir','error');return;}

  // Fecha formateada
  var fechaInicio = p.cerradaTs ? new Date(p.cerradaTs).toLocaleDateString('es-MX',{day:'2-digit',month:'2-digit',year:'numeric'}) : '___/___/______';
  var horaInicio  = p.horaInicio || '___:___';
  var horaFin     = p.horaFin    || '___:___';

  // Actividades del protocolo
  var actRows = '';
  if(proto && proto.actividades){
    proto.actividades.forEach(function(a){
      var estI = (p.actividadesEstadoInicial||{})[a.id] || '';
      var estF = (p.actividadesEstadoFinal||p.actividadesEstado||{})[a.id] || '';
      var com  = (p.comentariosActividades||{})[a.id] || '';
      var pers = (p.personasActividades||{})[a.id] || 1;
      var hrs  = (p.horasActividades||{})[a.id] || '';
      // Colores estado
      function estCell(e){
        var col=e==='B'?'#16a34a':e==='R'?'#d97706':e==='C'?'#dc2626':'#000';
        return e?('<span style="font-weight:800;color:'+col+'">'+e+'</span>'):'';
      }
      actRows += '<tr>'
        +'<td style="text-align:center;width:25px;font-size:10px">'+a.id+'</td>'
        +'<td style="font-size:9px;padding:3px 4px;line-height:1.3">'+a.desc+'</td>'
        +'<td style="text-align:center;width:35px;font-size:10px">'+a.esp+'</td>'
        +'<td style="text-align:center;width:28px">'+estCell(estI)+'</td>'
        +'<td style="text-align:center;width:28px">'+estCell(estF)+'</td>'
        +'<td style="text-align:center;width:25px;font-size:10px">'+(hrs||'')+'</td>'
        +'<td style="text-align:center;width:25px;font-size:10px">'+pers+'</td>'
        +'<td style="font-size:9px;padding:3px 4px">'+com+'</td>'
        +'</tr>';
    });
    for(var i=(proto.actividades.length+1);i<=10;i++){
      actRows+='<tr><td style="text-align:center;font-size:10px">'+i+'</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>';
    }
  }

  // Totales
  // Calcular totales reales
  var totalHrs = 0;
  var totalPers = 1;
  if(proto && proto.actividades){
    proto.actividades.forEach(function(a){
      var h=(p.horasActividades||{})[a.id]||'';
      var hNum=parseFloat(h)||0;
      if(h.indexOf('min')>=0) hNum=hNum/60;
      totalHrs+=hNum;
      var pe=(p.personasActividades||{})[a.id]||1;
      if(pe>totalPers) totalPers=pe;
    });
    totalHrs=Math.round(totalHrs*10)/10||p.horasCierre||0;
  }

  // Estado liberación
  var liberadoNombre = p.liberadoPor || '';
  var liberadoFecha  = p.liberadoTs  ? new Date(p.liberadoTs).toLocaleDateString('es-MX') : '';
  var rechazoNota    = p.rechazoCalidad ? '<div style="color:#dc2626;font-size:10px;margin-top:4px">⚠️ '+p.rechazoCalidad+'</div>' : '';

  var html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">'
    +'<title>'+( proto?proto.codigo:'REG-MTT')+' — '+p.linea+'</title>'
    +'<style>'
    +'*{margin:0;padding:0;box-sizing:border-box;}'
    +'body{font-family:Arial,sans-serif;font-size:11px;padding:12px;color:#000}'
    +'table{width:100%;border-collapse:collapse;}'
    +'td,th{border:1px solid #000;padding:3px 5px;}'
    +'th{background:#d0d0d0;font-weight:700;font-size:10px;text-align:center}'
    +'.titulo{font-size:14px;font-weight:700;text-align:center;padding:6px}'
    +'.codigo{font-size:11px;font-weight:700;text-align:right;}'
    +'.seccion{background:#d0d0d0;font-weight:700;font-size:10px;padding:4px 6px;text-transform:uppercase;border:1px solid #000}'
    +'.firma-box{border:1px solid #000;height:60px;min-width:120px;text-align:center;padding-top:40px;font-size:9px;color:#555}'
    +'@media print{body{padding:0}button{display:none}}'
    +'</style></head><body>'

    // Botón imprimir
    +'<div style="text-align:right;margin-bottom:8px"><button onclick="window.print()" style="padding:8px 16px;background:#1a3c5e;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:12px">🖨️ Imprimir / Guardar PDF</button></div>'

    // Encabezado
    +'<table style="margin-bottom:6px"><tr>'
    +'<td style="width:80px;text-align:center;border:1px solid #000;padding:4px"><div style="font-weight:800;font-size:9px">SAPORIS MTTO</div></td>'
    +'<td class="titulo">Protocolo de Mantenimiento Preventivo</td>'
    +'<td style="width:100px;border:1px solid #000;padding:4px"><div style="font-size:9px;font-weight:700">'+( proto?proto.codigo:'REG-MTT')+'</div></td>'
    +'</tr></table>'

    // Info del equipo
    +'<table style="margin-bottom:6px"><tr>'
    +'<td style="width:60px;border:1px solid #000;padding:3px;font-weight:700">Equipo:</td>'
    +'<td style="border:1px solid #000;padding:3px">'+(proto?proto.equipo:p.linea)+'</td>'
    +'<td style="width:120px;border:1px solid #000;padding:3px;font-weight:700">Equipo Secundario:</td>'
    +'<td style="border:1px solid #000;padding:3px">'+(proto?proto.equipoSecundario:p.componente||'—')+'</td>'
    +'</tr></table>'

    // Fechas y responsable
    +'<table style="margin-bottom:6px"><tr>'
    +'<td style="width:80px;font-weight:700;border:1px solid #000;padding:3px">Fecha inicio</td>'
    +'<td style="border:1px solid #000;padding:3px">'+fechaInicio+'</td>'
    +'<td style="width:80px;font-weight:700;border:1px solid #000;padding:3px">Fecha término</td>'
    +'<td style="border:1px solid #000;padding:3px">'+fechaInicio+'</td>'
    +'<td style="width:50px;font-weight:700;border:1px solid #000;padding:3px">Semana</td>'
    +'<td style="border:1px solid #000;padding:3px">'+p.semana+'</td>'
    +'</tr><tr>'
    +'<td style="font-weight:700;border:1px solid #000;padding:3px">Responsable</td>'
    +'<td colspan="5" style="border:1px solid #000;padding:3px">'+(p.tecnicoNombre||'—')+'</td>'
    +'</tr></table>'

    // Tabla de actividades
    +'<div class="seccion" style="margin-bottom:0">Actividades de Mantenimiento a Realizar</div>'
    +'<table style="margin-bottom:6px">'
    +'<tr style="background:#e8e8e8">'
    +'<th>#</th><th>Descripción</th><th>Esp.</th>'
    +'<th>Est. Inicial</th><th>Est. Final</th>'
    +'<th>Hrs</th><th>Pers.</th><th>Comentarios</th>'
    +'</tr>'
    +actRows
    +'<tr style="background:#e8e8e8"><td colspan="5" style="font-weight:700;text-align:right;font-size:10px">TOTAL HRS / PERSONAL</td>'
    +'<td style="text-align:center;font-weight:800">'+totalHrs+'</td><td style="text-align:center;font-weight:800">'+totalPers+'</td><td></td></tr>'
    +'</table>'

    // Reporte de actividades
    +'<div class="seccion" style="margin-bottom:0">Reporte de Actividades</div>'
    +'<table style="margin-bottom:6px"><tr>'
    +'<td style="font-weight:700;width:130px">Refacciones Usadas</td><td>'+(p.refaccionesUsadas||'Ninguna')+'</td>'
    +'<td style="font-weight:700;width:130px">Refacciones Nuevas</td><td></td>'
    +'</tr><tr>'
    +'<td style="font-weight:700">Herramienta Ingresada</td><td>'+(p.herramientaIngresada||'—')+'</td>'
    +'<td style="font-weight:700">Herramienta Salida</td><td>'+(p.herramientaSalida||'—')+'</td>'
    +'</tr></table>'

    // Limpieza
    +'<div class="seccion" style="margin-bottom:0">Limpieza y Sanitizado</div>'
    +'<table style="margin-bottom:6px"><tr>'
    +'<td>Limpieza por Mantenimiento</td>'
    +'<td style="width:30px;text-align:center;font-weight:800">'+(p.limpiezaMtto?'✓':'')+'</td><td style="width:30px">SI</td>'
    +'<td style="width:30px;text-align:center;font-weight:800">'+(p.limpiezaMtto===false?'✓':'')+'</td><td style="width:30px">NO</td>'
    +'<td style="font-weight:700">Grasa / Aceite grado alimenticio</td><td colspan="2">'+(p.grasaAceite||'N/A')+'</td>'
    +'</tr><tr>'
    +'<td>Desinfección por producción</td>'
    +'<td style="text-align:center;font-weight:800">'+(p.desinfProduccion?'✓':'')+'</td><td>SI</td>'
    +'<td style="text-align:center;font-weight:800">'+(p.desinfProduccion===false?'✓':'')+'</td><td>NO</td>'
    +'<td style="font-weight:700">Nombre grasa / aceite</td><td colspan="2">'+(p.grasaAceite||'N/A')+'</td>'
    +'</tr><tr>'
    +'<td style="font-weight:700">Comentarios limpieza</td>'
    +'<td colspan="7">'+(p.observacionesCierre||'')+'</td>'
    +'</tr></table>'

    // Firmas
    +'<div class="seccion" style="margin-bottom:0">Firmas de Autorización</div>'
     +'<table><tr>'
     +firmaCelda('TÉCNICO DE MANTENIMIENTO', p.firmaTecnico, p.firmaTecnicoTs, '')
     +firmaCelda('PRODUCCIÓN / LIDER', p.liberadoProdPor, p.liberadoProdTs, p.comentarioFirmaProd)
     +firmaCelda('INSPECTOR CALIDAD', liberadoNombre, p.liberadoTs, p.comentarioFirmaCalidad)
     +firmaCelda('JEFE DE MANTENIMIENTO', p.liberadoAdminPor, p.liberadoAdminTs, p.comentarioFirmaAdmin)
     +'</tr></table>'

    // Pie
    +'<div style="text-align:center;font-size:9px;color:#777;margin-top:8px">'
    +'Saporis MTTO — '+id+' — Semana '+p.semana+'/'+p.año
    +'</div>'
    +'</body></html>';

  win.document.write(html);
  win.document.close();
}
