function abrirEditarPM03Admin(id){
  var p = PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var modal=document.createElement('div');
  modal.id='modal-edit-pm03-admin';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">✏️ Editar PM03</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">'+id+' — '+p.linea+'</div>'
    +'<div style="margin-bottom:14px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">Estado</label>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="epm3-btn-abierta" onclick="epm3SetEstado(\'abierta\')" style="flex:1;padding:11px;border-radius:9px;border:2px solid '+(p.estado==='abierta'?'#f59e0b':'#d1d5db')+';background:'+(p.estado==='abierta'?'#fef3c7':'#fff')+';font-weight:700;cursor:pointer">📂 Abierta</button>'
    +'<button id="epm3-btn-cerrada" onclick="epm3SetEstado(\'cerrada\')" style="flex:1;padding:11px;border-radius:9px;border:2px solid '+(p.estado==='cerrada'?'#16a34a':'#d1d5db')+';background:'+(p.estado==='cerrada'?'#dcfce7':'#fff')+';font-weight:700;cursor:pointer">✅ Cerrada</button>'
    +'</div></div>'
    +'<div style="margin-bottom:14px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">Técnico</label>'
    +'<select id="epm3-tecnico" class="form-control" style="padding:10px">'
    +USERS.filter(function(u){return u.rol==='tecnico';}).map(function(u){return '<option value="'+u.id+'"'+(p.tecnicoId===u.id?' selected':'')+'>'+u.nombre+'</option>';}).join('')
    +'</select></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;text-transform:uppercase;display:block;margin-bottom:6px">Observaciones</label>'
    +'<textarea id="epm3-obs" class="form-control" rows="2" style="padding:10px">'+(p.observacionesCierre||'')+'</textarea></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-edit-pm03-admin\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="guardarEditarPM03Admin(\''+id+'\') " style="flex:1;padding:13px;background:#7c3aed;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  window._epm3Estado = p.estado;
}
function epm3SetEstado(est){
  window._epm3Estado=est;
  ['abierta','cerrada'].forEach(function(e){
    var btn=document.getElementById('epm3-btn-'+e);
    if(!btn) return;
    var activo = e===est;
    btn.style.borderColor=activo?(e==='cerrada'?'#16a34a':'#f59e0b'):'#d1d5db';
    btn.style.background=activo?(e==='cerrada'?'#dcfce7':'#fef3c7'):'#fff';
  });
}
function guardarEditarPM03Admin(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var nuevoEst=window._epm3Estado||p.estado;
  var tecSel=document.getElementById('epm3-tecnico');
  var obs=document.getElementById('epm3-obs').value.trim();
  var tObj=tecSel?USERS.find(function(u){return u.id===tecSel.value;}):null;
  p.estado=nuevoEst;
  if(tObj){p.tecnicoId=tObj.id;p.tecnicoNombre=tObj.nombre;}
  if(obs) p.observacionesCierre=obs;
  if(nuevoEst==='cerrada'&&!p.cerradaTs){p.cerradaTs=Date.now();p.cerradaPor=nombreEfectivo();}
  p._editadoTs=Date.now(); // Marca para que sync no sobreescriba
  saveDB('pm03_plan',PM03_PLAN);
  savePM03Supa(p);
  var m=document.getElementById('modal-edit-pm03-admin');if(m)m.remove();
  showAlert('✅ PM03 actualizada');
  // Actualizar el detalle Y refrescar la lista de fondo
  showDetallePM03(id);
  if(detalleBackScreen==='screen-pm03') setTimeout(function(){renderPM03();},100);
}

// Helper: el super "es" cualquier rol para efectos de permisos
function superEs(rol){
  if(!currentUser) return false;
  if(currentUser.rol==='super') return true;
  return currentUser.rol===rol;
}

function superEliminarPM03(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  if(!confirm('⚠️ ¿ELIMINAR permanentemente la PM03 '+id+'?\n\nEsta acción no se puede deshacer.')) return;
  PM03_PLAN=PM03_PLAN.filter(function(x){return x.id!==id;});
  saveDB('pm03_plan',PM03_PLAN);
  // Marcar como eliminada para evitar que sync la restaure
  var del=loadDB('pm03_eliminadas',[]);
  if(del.indexOf(id)<0){del.push(id);saveDB('pm03_eliminadas',del);}
  // Eliminar de Supabase
  fetch(SUPA_URL+'/rest/v1/pm03_plan?id=eq.'+id,{
    method:'DELETE',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Prefer':'return=minimal'}
  }).then(function(r){
    if(r.ok) console.log('PM03 '+id+' eliminada de Supabase');
    else r.text().then(function(t){console.error('Error:',t);});
  });
  showAlert('🗑️ PM03 '+id+' eliminada');
  // Refrescar pantalla origen
  if(detalleBackScreen==='screen-pm03') showPM03();
  else if(detalleBackScreen==='screen-ordenes'){
    // Re-render la lista que estaba activa
    if(typeof filtrarOrdenes==='function') filtrarOrdenes();
    showScreen('screen-ordenes');
  } else goBack();
}

function cancelarAtencion(){
  if(!confirm('¿Cancelar esta atención? Se borrará toda la información capturada en este slot.')) return;
  ATENCION_SLOTS[currentSlot] = null;
  saveDB('atencion_slots', ATENCION_SLOTS);
  atencionState = {};
  updateSlotPreview();
  showAlert('🚫 Atención cancelada');
  goMenu();
}

