function shoMostrarListaAnom(lista, titulo){
  var modal = document.createElement('div');
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;overflow-y:auto;padding:12px;box-sizing:border-box';
  var rows = lista.map(function(o){
    return '<div style="background:#fff;border-left:4px solid #dc2626;border-radius:8px;padding:12px;margin-bottom:8px">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">'
      +'<span style="font-size:11px;font-weight:700;color:#dc2626">'+o.id+'</span>'
      +'<span style="font-size:11px;color:#6b7280">'+fmtDate(o.ts)+'</span>'
      +'</div>'
      +'<div style="font-size:14px;font-weight:700;color:#1a3c5e;margin-bottom:2px">'+(o.linea||o.area||'—')+'</div>'
      +'<div style="font-size:12px;color:#374151;margin-bottom:2px">'+(o.componente||o.detalle||'—').substring(0,80)+'</div>'
      +'<div style="font-size:11px;color:#6b7280">👨‍🔧 '+(o.tecnicoNombre||'Sin asignar')+' · Prio '+o.prioridad+'</div>'
      +'</div>';
  }).join('');
  modal.id='modal-sho-anom';
  modal.onclick=function(e){if(e.target===modal)modal.remove();};
  modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:20px;max-width:500px;margin:auto;box-sizing:border-box">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">'
    +'<div style="font-family:Nunito,sans-serif;font-size:16px;font-weight:800;color:#dc2626">'+titulo+'</div>'
    +'<button onclick="document.getElementById(\'modal-sho-anom\').remove()" style="background:none;border:none;font-size:1.3rem;cursor:pointer;color:#9ca3af">✕</button>'
    +'</div>'
    +(lista.length?rows:'<div style="text-align:center;padding:30px;color:#9ca3af">Sin anormalidades activas</div>')
    +'</div>';
  document.body.appendChild(modal);
}

// ---- Comentarios con seguimiento ----
async function shoCargarComentarios(f){
  // Cargar: abiertos de cualquier fecha + todos los del filtro actual
  try{
    var rows=await supaFetch('sho_comentarios','GET',null,'order=ts.asc&limit=500');
    if(!rows) return [];
    var anio=f.anio||currentYear();
    var mes=f.mes||0;
    var dia=f.dia||0;
    var turno=f.turno||'';
    return rows.filter(function(c){
      // Siempre mostrar los no cerrados
      if(!c.cerrado) return true;
      // Mostrar cerrados solo si son del periodo seleccionado
      var mismoAnio=!anio||(c.anio||0)===anio;
      var mismoMes=!mes||(c.mes||0)===mes;
      var mismoDia=!dia||(c.dia||0)===dia;
      var mismoTurno=!turno||c.turno===turno;
      return mismoAnio&&mismoMes&&mismoDia&&mismoTurno;
    });
  }catch(e){return [];}
}

async function shoAgregarComentario(){
  var inp=document.getElementById('sho-nuevo-comment');
  if(!inp||!inp.value.trim()){showAlert('Escribe un comentario primero','error');return;}
  var texto=inp.value.trim();
  var f=shoGetFiltros();
  var payload={
    id:'shoc_'+Date.now(),
    texto:texto,
    autor:currentUser.nombre,
    autor_id:currentUser.id,
    ts:Date.now(),
    cerrado:false,
    anio:f.anio||currentYear(),
    mes:f.mes||0,
    dia:f.dia||0,
    turno:f.turno||shoTurnoActual()
  };
  var r=await supaUpsert('sho_comentarios',payload);
  if(r!==null){
    inp.value='';
    renderSHO();
  }else{
    showAlert('Error al guardar comentario','error');
  }
}

async function shoCerrarComentario(id){
  try{
    var res=await fetch(SUPA_URL+'/rest/v1/sho_comentarios?id=eq.'+id,{
      method:'PATCH',
      headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},
      body:JSON.stringify({cerrado:true,cerrado_por:nombreEfectivo(),cerrado_ts:Date.now()})
    });
    if(res.ok){renderSHO();showAlert('✅ Comentario cerrado');}
    else showAlert('Error al cerrar comentario','error');
  }catch(e){showAlert('Error al cerrar comentario','error');}
}

// ---- Render principal ----
async function showSHO(){
  var roles=['tecnico','admin','super'];
  if(!currentUser||roles.indexOf(currentUser.rol)===-1){showAlert('Sin acceso','error');return;}
  showScreen('screen-sho');
  var turno=shoTurnoActual();
  var sub=turno+' · '+currentUser.nombre;
  document.getElementById('sho-topbar-sub').textContent=sub;
  shoIniciarFiltros();
  renderSHO();
}

