async function importarEmpleadosArchivo(){
  if(!currentUser||currentUser.rol!=='super'){showAlert('Sin permisos','error');return;}
  var datos=[{"nombre":"Julio Cesar Arreola Garcia","numero_empleado":"2196","activo":true,"fecha_ingreso":"2025-12-17","antiguedad_años":0.5,"puesto":"OFICIAL DE MANTENIMIENTO B","usuario_id":"u_t1","turno_actual":1},{"nombre":"Anthon Humberto Chavez Carmona","numero_empleado":"1980","activo":true,"fecha_ingreso":"2025-06-18","antiguedad_años":1.0,"puesto":"OFICIAL DE MANTENIMIENTO B","usuario_id":null,"turno_actual":1},{"nombre":"Marco Antonio Diaz Castro","numero_empleado":"2055","activo":true,"fecha_ingreso":"2025-04-14","antiguedad_años":1.17,"puesto":"OFICIAL DE MANTENIMIENTO B","usuario_id":"u_t3","turno_actual":1},{"nombre":"Angel Abraham Muratalla Zarco","numero_empleado":"1923","activo":true,"fecha_ingreso":"2024-10-09","antiguedad_años":1.67,"puesto":"OFICIAL DE MANTENIMIENTO B","usuario_id":"u_t4","turno_actual":1},{"nombre":"Uriel Navarrete Garrido","numero_empleado":"1105","activo":true,"fecha_ingreso":"2017-09-27","antiguedad_años":8.75,"puesto":"OFICIAL DE MANTENIMIENTO A","usuario_id":"u_t5","turno_actual":1},{"nombre":"Jose Eduardo Orozco Rico","numero_empleado":"461","activo":true,"fecha_ingreso":"2025-04-02","antiguedad_años":1.17,"puesto":"ESPECIALISTA DE MANTENIMIENTO","usuario_id":"u_t6","turno_actual":1},{"nombre":"Mauricio Rangel Verduzco","numero_empleado":"1755","activo":true,"fecha_ingreso":"2023-09-18","antiguedad_años":2.75,"puesto":"COORDINADOR DE MANTENIMIENTO","usuario_id":"u_adm2","turno_actual":1},{"nombre":"Lisandro Torres Duran","numero_empleado":"804","activo":true,"fecha_ingreso":"2012-11-12","antiguedad_años":13.58,"puesto":"OFICIAL DE MANTENIMIENTO A","usuario_id":"u_t7","turno_actual":1},{"nombre":"Alan Roberto Zurita Zamudio","numero_empleado":"2064","activo":true,"fecha_ingreso":"2025-04-28","antiguedad_años":1.17,"puesto":"OFICIAL DE MANTENIMIENTO B","usuario_id":"u_t8","turno_actual":1}];
  var ok=0,skip=0,fail=0;
  // Verificar si ya existen
  var existentes=await supaFetch('empleados','GET',null,'select=numero_empleado');
  var existNums=new Set((existentes||[]).map(function(e){return e.numero_empleado;}));

  for(var i=0;i<datos.length;i++){
    var e=datos[i];
    if(existNums.has(e.numero_empleado)){
      // Actualizar en lugar de duplicar
      var r=await supaFetch('empleados','PATCH',{
        nombre:e.nombre,
        activo:e.activo,
        fecha_ingreso:e.fecha_ingreso,
        antiguedad_años:e.antiguedad_años,
        puesto:e.puesto,
        usuario_id:e.usuario_id,
        turno_actual:e.turno_actual||1
      },'numero_empleado=eq.'+e.numero_empleado);
      if(r!==null){ok++;}else{fail++;}
    }else{
      var payload={
        id: 'emp_'+String(e.numero_empleado),
        nombre:e.nombre,
        numero_empleado:String(e.numero_empleado),
        activo:e.activo===true,
        fecha_ingreso:e.fecha_ingreso||null,
        'antiguedad_años':e.antiguedad_años||0,
        puesto:e.puesto||null,
        turno_actual:e.turno_actual||1
      };
      if(e.usuario_id) payload.usuario_id=e.usuario_id;
      var r2=await fetch(SUPA_URL+'/rest/v1/empleados',{
        method:'POST',
        headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},
        body:JSON.stringify(payload)
      });
      if(r2.ok||r2.status===201||r2.status===204){ok++;}else{
        var errTxt=await r2.text();
        console.error('Error empleado '+e.nombre+':',errTxt);
        fail++;
      }
    }
    await new Promise(function(res){setTimeout(res,80);});
  }
  showAlert('✅ Empleados importados: '+ok+' actualizados/creados'+(fail?' — '+fail+' errores':''));
  showGestionPersonal();
}



