function _anomGuardarBorrador(){
  // Leer estado actual del formulario antes de salir
  var area=(document.getElementById('anom-area')||{}).value||pmState.area||'';
  var linea=(document.getElementById('anom-linea')||{}).value||pmState.linea||'';
  var comp=(document.getElementById('anom-comp')||{}).value||pmState.componente||'';
  var tipo=(document.getElementById('anom-tipo')||{}).value||pmState.tipoAnormalidad||'';
  var detalle=(document.getElementById('anom-detalle')||{}).value||pmState.detalle||'';
  var fecha=(document.getElementById('anom-fecha')||{}).value||pmState.fechaTrabajo||'';
  var ini=(document.getElementById('anom-ini')||{}).value||pmState.horaInicioTrabajo||'';
  var fin=(document.getElementById('anom-fin')||{}).value||pmState.horaFinTrabajo||'';
  if(area||comp||detalle){
    var draft=Object.assign({},pmState,{
      area:area,linea:linea,componente:comp,tipoAnormalidad:tipo,
      detalle:detalle,fechaTrabajo:fecha,horaInicioTrabajo:ini,horaFinTrabajo:fin,
      tipo:'PM02',levantadoId:currentUser.id,_draft:true,_ts:Date.now()
    });
    saveDB('pm_anom_draft_'+currentUser.id, draft);
  }
}

function backFromAnomUnico(){
  var area=(document.getElementById('anom-area')||{}).value||pmState.area||'';
  var comp=(document.getElementById('anom-comp')||{}).value||pmState.componente||'';
  var detalle=(document.getElementById('anom-detalle')||{}).value||pmState.detalle||'';
  if(!(area||comp||detalle)){goMenu();return;}

  var modal=document.createElement('div');
  modal.id='modal-salir-anom';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end;justify-content:center';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px 20px 32px;width:100%;max-width:480px">'
    +'<div style="width:40px;height:4px;background:#e5e7eb;border-radius:2px;margin:0 auto 20px"></div>'
    +'<div style="font-size:17px;font-weight:800;font-family:Nunito,sans-serif;margin-bottom:6px;text-align:center">¿Qué deseas hacer?</div>'
    +'<div style="font-size:13px;color:#6b7280;text-align:center;margin-bottom:20px">Tienes datos capturados</div>'
    +'<button onclick="document.getElementById(\'modal-salir-anom\').remove()" style="width:100%;padding:14px;background:var(--mo,#7c3aed);color:#fff;border:none;border-radius:13px;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:10px">↩ Seguir capturando</button>'
    +'<button onclick="document.getElementById(\'modal-salir-anom\').remove();_anomGuardarBorrador();goMenu()" style="width:100%;padding:14px;background:#f0fdf4;color:#16a34a;border:2px solid #16a34a;border-radius:13px;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:10px">💾 Salir y conservar borrador</button>'
    +'<button onclick="document.getElementById(\'modal-salir-anom\').remove();saveDB(\'pm_anom_draft_\'+currentUser.id,null);pmState={};goMenu()" style="width:100%;padding:14px;background:#fff1f2;color:#dc2626;border:2px solid #dc2626;border-radius:13px;font-size:15px;font-weight:700;cursor:pointer">🗑️ Salir y borrar todo</button>'
    +'</div>';
  document.body.appendChild(modal);
}

function showFormAnomUnico(){
  document.getElementById('pm-anom-sub').textContent=currentUser.nombre+' · '+currentUser.rol;
  // Verificar si hay borrador guardado
  var draft=loadDB('pm_anom_draft_'+currentUser.id,null);
  if(draft&&draft._draft&&draft.tipo==='PM02'&&(Date.now()-draft._ts)<86400000){
    if(confirm('Tienes una anormalidad sin terminar. ¿Continuar donde la dejaste?')){
      pmState=draft;
    } else {
      saveDB('pm_anom_draft_'+currentUser.id,null);
      pmState={tipo:'PM02',levantadoPor:nombreEfectivo(),levantadoId:currentUser.id,ts:Date.now()};
    }
  } else {
    pmState={tipo:'PM02',levantadoPor:nombreEfectivo(),levantadoId:currentUser.id,ts:Date.now()};
  }
  showScreen('screen-pm-anom');
  _renderFormAnom();
}

function _renderFormAnom(){
  var cont=document.getElementById('pm-anom-content');
  var esLider=currentUser.rol==='lider';
  var color=pmState.colorOT||'';

  var areas=['Producción — Fabricación','Envasado','Bodega','Servicios Industriales','Instalaciones'];
  var areaOpts='<option value="">-- Selecciona área --</option>'+areas.map(function(a){return'<option value="'+a+'"'+(pmState.area===a?' selected':'')+'>'+a+'</option>';}).join('');
  var lineasAll=((LISTAS.lineas_proceso||[]).concat(LISTAS.lineas_envasado||[]).concat(LISTAS.lineas_servicios||[]).concat(LISTAS.lineas_bodega||[])).filter(Boolean);
  var lineaOpts='<option value="">-- Selecciona línea --</option>'+lineasAll.map(function(l){return'<option value="'+l+'"'+(pmState.linea===l?' selected':'')+'>'+l+'</option>';}).join('');
  var tipoOpts='<option value="">-- Tipo de anormalidad --</option>'+[...(LISTAS.tipos_anormalidad||[]),'Otra'].map(function(t){return'<option value="'+t+'"'+(pmState.tipoAnormalidad===t?' selected':'')+'>'+t+'</option>';}).join('');
  var prioOpts=['A','B','C'].map(function(p){
    var sel=pmState.prioridad===p;
    var bg=sel?(p==='A'?'#fee2e2':p==='B'?'#fef3c7':'#dcfce7'):'#f3f4f6';
    var border=sel?'2px solid '+(p==='A'?'#dc2626':p==='B'?'#d97706':'#16a34a'):'2px solid #e5e7eb';
    return'<button type="button" onclick="anomSelPrio(this,\''+p+'\')" class="btn" style="flex:1;padding:10px;background:'+bg+';border:'+border+';border-radius:10px;font-weight:800;font-size:15px">'+p+'</button>';
  }).join('');

  // Selector de color — visible para AMBOS roles
  var colorOpts='<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">'
    +'<button type="button" id="anom-btn-azul" onclick="pmState.colorOT=\'azul\';_renderFormAnom()" style="padding:14px;background:#E3F2FD;border:3px solid '+(color==='azul'?'#1565C0':'#e5e7eb')+';border-radius:10px;font-weight:800">🔵 Azul<div style="font-size:11px;font-weight:400;opacity:.8">Resuelve operador</div></button>'
    +'<button type="button" id="anom-btn-rojo" onclick="pmState.colorOT=\'rojo\';_renderFormAnom()" style="padding:14px;background:#FFEBEE;border:3px solid '+(color==='rojo'?'#C62828':'#e5e7eb')+';border-radius:10px;font-weight:800">🔴 Rojo<div style="font-size:11px;font-weight:400;opacity:.8">Resuelve mantenimiento</div></button>'
    +'</div>';

  // Sección dinámica según color
  var seccionColor='';
  if(color==='azul'){
    // Azul: auto-asigna al mismo usuario + fecha/hora
    pmState.tecnicoAsignado=currentUser.id;
    pmState.tecnicoNombre=currentUser.nombre;
    seccionColor=
      '<label class="form-label">📅 Fecha y hora del trabajo</label>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px">'
      +'<input type="date" class="form-control" id="anom-fecha" value="'+(pmState.fechaTrabajo||todayStr())+'" max="'+todayStr()+'">'
      +'<input type="time" class="form-control" id="anom-ini" placeholder="Inicio" value="'+(pmState.horaInicioTrabajo||'')+'">'
      +'<input type="time" class="form-control" id="anom-fin" placeholder="Fin" value="'+(pmState.horaFinTrabajo||'')+'">'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px">'
      +'<button class="btn btn-primary" onclick="guardarAnomUnico(false)">📋 Guardar Abierta</button>'
      +'<button class="btn btn-success" onclick="guardarAnomUnico(true)">✅ Guardar Resuelta</button>'
      +'</div>';
  } else if(color==='roja'||color==='rojo'){
    // Roja: pide con quién concilia (técnicos de mantenimiento)
    var tecs=USERS.filter(function(u){return u.rol==='tecnico'&&u.id!=='u_super';});
    var concRojaOpts='<option value="">-- Selecciona técnico --</option>'
      +tecs.map(function(u){return'<option value="'+u.id+'" data-nombre="'+u.nombre+'">'+u.nombre+'</option>';}).join('');
    seccionColor=
      '<label class="form-label">🤝 Conciliado con (técnico mantenimiento)</label>'
      +'<select class="form-control" id="anom-asig-tec" style="margin-bottom:14px">'+concRojaOpts+'</select>'
      +'<button class="btn btn-success" style="width:100%;margin-top:8px" onclick="guardarAnomUnico(false)">🔴 Generar anormalidad roja</button>';
  }

  cont.innerHTML=
    '<label class="form-label">🎨 Color / Quién resuelve</label>'
    +colorOpts
    +'<label class="form-label">🏭 Área</label>'
    +'<select class="form-control" id="anom-area" style="margin-bottom:14px" onchange="anomCambiarArea(this)"><option value="">-- Selecciona área --</option>'+areaOpts.split('<option value="">-- Selecciona área --</option>')[1]+'</select>'
    +'<label class="form-label">📍 Línea</label>'
    +'<select class="form-control" id="anom-linea" style="margin-bottom:14px">'+lineaOpts+'</select>'
    +'<label class="form-label">🔩 Componente / Equipo</label>'
    +'<input type="text" class="form-control" id="anom-comp" placeholder="Ej: Motor, banda, sensor..." value="'+(pmState.componente||'')+'" style="margin-bottom:14px">'
    +'<label class="form-label">⚡ Prioridad</label>'
    +'<div style="display:flex;gap:8px;margin-bottom:14px" id="anom-prio-btns">'+prioOpts+'</div>'
    +'<label class="form-label">📌 Tipo de anormalidad</label>'
    +'<select class="form-control" id="anom-tipo" style="margin-bottom:14px">'+tipoOpts+'</select>'
    +'<label class="form-label">📝 Descripción</label>'
    +'<textarea class="form-control" id="anom-detalle" rows="3" placeholder="Describe la anormalidad..." style="margin-bottom:14px">'+(pmState.detalle||'')+'</textarea>'
    +seccionColor;
}

function anomSelPrio(btn,prio){
  pmState.prioridad=prio;
  btn.closest('#anom-prio-btns').querySelectorAll('button').forEach(function(b){b.style.background='#f3f4f6';b.style.border='2px solid #e5e7eb';});
  btn.style.background=prio==='A'?'#fee2e2':prio==='B'?'#fef3c7':'#dcfce7';
  btn.style.border='2px solid '+(prio==='A'?'#dc2626':prio==='B'?'#d97706':'#16a34a');
}
function anomCambiarArea(sel){
  pmState.area=sel.value;
  // Filtrar líneas según área
  var lineasArea=[];
  var v=sel.value||'';
  if(v.includes('Fabricación')||v.includes('Proceso')) lineasArea=LISTAS.lineas_proceso||[];
  else if(v.includes('Envasado')) lineasArea=LISTAS.lineas_envasado||[];
  else if(v.includes('Servicios')) lineasArea=LISTAS.lineas_servicios||[];
  else if(v.includes('Bodega')) lineasArea=LISTAS.lineas_bodega||[];
  else lineasArea=(LISTAS.lineas_proceso||[]).concat(LISTAS.lineas_envasado||[]).concat(LISTAS.lineas_servicios||[]).concat(LISTAS.lineas_bodega||[]);
  var lEl=document.getElementById('anom-linea');
  if(lEl) lEl.innerHTML='<option value="">-- Selecciona línea --</option>'+lineasArea.filter(Boolean).map(function(l){return'<option value="'+l+'">'+l+'</option>';}).join('');
}

function guardarAnomUnico(resuelta){
  var area=(document.getElementById('anom-area')||{}).value||'';
  var linea=(document.getElementById('anom-linea')||{}).value||'';
  var comp=(document.getElementById('anom-comp')||{}).value||'';
  var tipo=(document.getElementById('anom-tipo')||{}).value||'';
  var detalle=(document.getElementById('anom-detalle')||{}).value.trim()||'';
  var color=pmState.colorOT||'';

  if(!color){showAlert('Selecciona el color','error');return;}
  if(!area){showAlert('Selecciona el área','error');return;}
  if(!linea){showAlert('Selecciona la línea','error');return;}
  if(!comp.trim()){showAlert('Escribe el componente','error');return;}
  if(!detalle){showAlert('Escribe la descripción','error');return;}
  if(!pmState.prioridad){showAlert('Selecciona la prioridad','error');return;}

  var esLider=currentUser.rol==='lider';
  var fecha=todayStr(), ini='', fin='', horas=0, tsOrden=Date.now();

  if(color==='azul'){
    // Azul: auto-asignado, recoger fecha/hora
    pmState.tecnicoAsignado=currentUser.id;
    pmState.tecnicoNombre=currentUser.nombre;
    fecha=(document.getElementById('anom-fecha')||{}).value||todayStr();
    ini=(document.getElementById('anom-ini')||{}).value||'';
    fin=(document.getElementById('anom-fin')||{}).value||'';
    tsOrden=new Date(fecha+'T'+(ini||'08:00')+':00').getTime();
    if(ini&&fin){
      var p1=ini.split(':').map(Number),p2=fin.split(':').map(Number);
      var mins=(p2[0]*60+p2[1])-(p1[0]*60+p1[1]);
      if(mins<0)mins+=1440;
      horas=parseFloat((mins/60).toFixed(2));
    }
  } else {
    // Roja: fecha/hora automática, técnico del selector
    tsOrden=Date.now();
    var asigTecEl=document.getElementById('anom-asig-tec');
    if(asigTecEl&&asigTecEl.value){
      var optTec=asigTecEl.options[asigTecEl.selectedIndex];
      pmState.tecnicoAsignado=asigTecEl.value;
      pmState.tecnicoNombre=optTec.getAttribute('data-nombre')||optTec.text;
    } else {
      pmState.tecnicoAsignado='';
      pmState.tecnicoNombre='';
    }
    resuelta=false;
  }

  pmState.area=area;
  pmState.linea=linea;
  pmState.componente=comp.trim();
  pmState.tipoAnormalidad=tipo;
  pmState.detalle=detalle;
  pmState.fechaTrabajo=color==='azul'?fecha:null;
  pmState.horaInicioTrabajo=ini||null;
  pmState.horaFinTrabajo=fin||null;
  pmState.horasCierre=resuelta?horas:0;
  pmState.resuelta=resuelta;
  pmState._tsOrden=tsOrden;
  pmState._semOrden=getWeekNumber(new Date(fecha+'T12:00:00'));
  pmState._añoOrden=new Date(fecha+'T12:00:00').getFullYear();
  pmState.pendienteAsignacion=false;

  guardarOT();
  saveDB('pm_anom_draft_'+currentUser.id,null);
  showScreen('screen-menu');
  showAlert('✅ Anormalidad guardada');
}

// ================================================================
// EXPORT EXCEL — KPI ANORMALIDADES
// ================================================================
function exportarKPIAnomExcel(){
  var pm02Op=ORDENES.filter(function(o){
    if(o.tipo!=='PM02') return false;
    var r=o.rolLevantador||'';
    return r==='operador'||r==='lider'||r==='inspector_calidad'||r==='lider_calidad'||r==='administrativo'||r==='supply';
  });
  if(window._kpiAnomLinea) pm02Op=pm02Op.filter(function(o){return(o.linea||o.area||'')=== window._kpiAnomLinea;});
  if(window._kpiAnomSem>0) pm02Op=pm02Op.filter(function(o){return o.semana===window._kpiAnomSem&&(o.año||currentYear())===window._kpiAnomAño;});
  if(window._kpiAnomBusq&&window._kpiAnomBusq.trim()){
    var q=window._kpiAnomBusq.trim().toLowerCase();
    pm02Op=pm02Op.filter(function(o){return(o.id||'').toLowerCase().includes(q)||(o.linea||'').toLowerCase().includes(q)||(o.detalle||'').toLowerCase().includes(q)||(o.levantadoPor||'').toLowerCase().includes(q);});
  }
  var header=['ID','Fecha','Semana','Área','Línea','Componente','Tipo','Color','Prioridad','Estado','Levantado por','Técnico','Horas','Detalle'];
  var rows=pm02Op.map(function(o){
    return[o.id,fmtDateTime(o.ts),o.semana,o.area,o.linea,o.componente,o.tipoAnormalidad,o.colorOT,o.prioridad,o.estado,o.levantadoPor,o.tecnicoNombre||'',o.horasCierre||0,o.detalle||''];
  });
  var csv=[header].concat(rows).map(function(r){return r.map(function(c){return'"'+(String(c||'').replace(/"/g,'""'))+'"';}).join(',');}).join('\n');
  var blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='KPI_Anormalidades_Sem'+(window._kpiAnomSem||'Todas')+'_'+currentYear()+'.csv';
  a.click();
}

