function superElegirNombreFirma(callback){
  // Si no es super, usar nombre propio directamente
  if(!currentUser||currentUser.rol!=='super'){
    callback(currentUser.nombre, currentUser.nombre);
    return;
  }
  // Super: mostrar modal para elegir con qué usuario registrar la acción
  var usuarios=USERS.filter(function(u){return u.rol!=='super'&&u.activo!==false;});
  var optsHTML=usuarios.map(function(u){
    return'<button onclick="document.getElementById(\'modal-super-firma\').remove();(window._superFirmaCallback||function(){})(\''+u.nombre+'\',\'Real: Super ['+currentUser.nombre+'] → '+u.nombre+'\')" '
      +'style="width:100%;padding:12px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;text-align:left;cursor:pointer;font-size:14px;font-weight:600;margin-bottom:6px">'
      +'<span>👤 '+u.nombre+'</span><span style="float:right;font-size:11px;color:#9ca3af">'+u.rol+'</span></button>';
  }).join('');

  window._superFirmaCallback=callback;
  var modal=document.createElement('div');
  modal.id='modal-super-firma';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:flex-end;justify-content:center';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px 20px 32px;width:100%;max-width:480px;max-height:80vh;overflow-y:auto">'
    +'<div style="width:40px;height:4px;background:#e5e7eb;border-radius:2px;margin:0 auto 16px"></div>'
    +'<div style="font-size:17px;font-weight:800;font-family:Nunito,sans-serif;color:#1a3c5e;margin-bottom:4px">⚡ Registrar acción como</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px;background:#fef3c7;border-radius:8px;padding:8px">El super usuario no deja registros. Elige con qué usuario se guarda esta acción.</div>'
    +optsHTML
    +'<button onclick="document.getElementById(\'modal-super-firma\').remove()" style="width:100%;padding:12px;background:#f3f4f6;border:none;border-radius:10px;cursor:pointer;font-weight:600;color:#374151;margin-top:4px">Cancelar</button>'
    +'</div>';
  document.body.appendChild(modal);
}

