var _refTab = 'catalogo';
var _refBusq = '';

function showRefacciones(){
  showScreen('screen-refacciones');
  _renderRefTabs();
}

function _renderRefTabs(){
  var tabsDiv = document.getElementById('ref-tabs');
  var cont = document.getElementById('ref-content');
  if(!tabsDiv||!cont) return;
  var isAdmin = currentUser.rol==='admin'||currentUser.rol==='super';
  var tabs = [
    {id:'catalogo', icon:'📦', label:'Catálogo'},
    {id:'movimientos', icon:'📋', label:'Movimientos'},
  ];
  if(isAdmin) tabs.push({id:'nuevo', icon:'➕', label:'Nueva'});
  tabsDiv.innerHTML = tabs.map(function(t){
    var sel = _refTab===t.id;
    return '<button onclick="_refTab=\''+t.id+'\';_renderRefTabs()" style="padding:7px 12px;border-radius:8px;border:2px solid '+(sel?'#5D4037':'#e5e7eb')+';background:'+(sel?'#EFEBE9':'#fff')+';font-weight:700;font-size:.82rem;cursor:pointer;color:'+(sel?'#5D4037':'#374151')+'">'+t.icon+' '+t.label+'</button>';
  }).join('');
  if(_refTab==='catalogo') _renderCatalogoRef(cont);
  else if(_refTab==='movimientos') _renderMovimientosRef(cont);
  else if(_refTab==='nuevo') _renderFormNuevaRef(cont);
}

// ── CATÁLOGO ─────────────────────────────────────────────────────
function _renderCatalogoRef(cont){
  cont.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  supaFetch('refacciones','GET',null,'activo=eq.true&order=nombre.asc').then(function(rows){
    var stockBajo=(rows||[]).filter(function(r){return r.cantidad<=r.cantidad_minima;});
    var html='<div style="display:flex;gap:8px;margin-bottom:12px">'
      +'<input type="text" id="ref-busq" class="form-control" placeholder="🔍 Buscar por nombre o código..." value="'+_refBusq+'" oninput="_refBusq=this.value;_filtrarCatalogo()" style="flex:1;padding:9px;font-size:.85rem">'
      +'</div>';
    if(stockBajo.length){
      html+='<div style="background:#fee2e2;border:1px solid #fecaca;border-radius:10px;padding:10px 14px;margin-bottom:12px;font-size:.85rem;color:#dc2626;font-weight:700">⚠️ '+stockBajo.length+' refacción(es) en stock bajo</div>';
    }
    if(!rows||!rows.length){
      html+='<div class="card text-center" style="padding:40px"><div style="font-size:48px">📦</div><div style="font-weight:700;margin-top:12px">Sin refacciones registradas</div><div style="font-size:13px;color:var(--txt3);margin-top:6px">Agrega la primera desde la pestaña ➕ Nueva</div></div>';
    } else {
      html+='<div id="ref-lista">'+_buildRefCards(rows)+'</div>';
    }
    cont.innerHTML=html;
    window._refAllRows=rows||[];
  });
}

function _buildRefCards(rows){
  var q=(_refBusq||'').toLowerCase();
  var filtered=rows.filter(function(r){
    return !q||r.nombre.toLowerCase().includes(q)||(r.codigo||'').toLowerCase().includes(q)||(r.descripcion||'').toLowerCase().includes(q);
  });
  if(!filtered.length) return '<div class="card text-center" style="padding:30px">Sin resultados para "'+_refBusq+'"</div>';
  return filtered.map(function(r){
    var stockOk=r.cantidad>r.cantidad_minima;
    var stockMin=r.cantidad===r.cantidad_minima||r.cantidad===r.cantidad_minima+1;
    var stockBajo=r.cantidad<=r.cantidad_minima;
    var colStock=stockBajo?'#dc2626':stockMin?'#d97706':'#16a34a';
    var isAdmin=currentUser.rol==='admin'||currentUser.rol==='super';
    return '<div class="card" style="border-left:4px solid '+colStock+';margin-bottom:10px;padding:14px">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">'
      +'<div style="flex:1">'
      +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800">'+r.nombre+'</div>'
      +'<div style="font-size:11px;color:#6b7280;margin-top:2px">Código: '+r.codigo+(r.ubicacion?' · 📍 '+r.ubicacion:'')+'</div>'
      +(r.descripcion?'<div style="font-size:12px;color:var(--txt2);margin-top:3px">'+r.descripcion+'</div>':'')
      +'</div>'
      +'<div style="text-align:center;background:#f8fafc;border-radius:10px;padding:8px 12px;min-width:70px">'
      +'<div style="font-size:1.6rem;font-weight:900;color:'+colStock+'">'+r.cantidad+'</div>'
      +'<div style="font-size:.7rem;color:#6b7280">en stock</div>'
      +'<div style="font-size:.68rem;color:#9ca3af">mín: '+r.cantidad_minima+'</div>'
      +'</div>'
      +'</div>'
      +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
      +'<button onclick="abrirDescuentoRef(\''+r.id+'\',\''+r.nombre.replace(/'/g,'')+'\','+r.cantidad+')" style="flex:1;padding:9px;background:#5D4037;color:#fff;border:none;border-radius:8px;font-size:.82rem;font-weight:700;cursor:pointer">📤 Descontar</button>'
      +'<button onclick="abrirEntradaRef(\''+r.id+'\',\''+r.nombre.replace(/'/g,'')+'\','+r.cantidad+')" style="flex:1;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-size:.82rem;font-weight:700;cursor:pointer">📥 Entrada</button>'
      +'<button onclick="mostrarQR(\''+r.codigo+'\',\''+r.nombre.replace(/'/g,'')+'\',\''+r.id+'\')" style="padding:9px 12px;background:#f3f4f6;border:none;border-radius:8px;font-size:.82rem;cursor:pointer">📲 QR</button>'
      +(isAdmin?'<button onclick="editarRef(\''+r.id+'\')" style="padding:9px 12px;background:#f3f4f6;border:none;border-radius:8px;font-size:.82rem;cursor:pointer">✏️</button>':'')
      +'</div></div>';
  }).join('');
}

function _filtrarCatalogo(){
  var lista=document.getElementById('ref-lista');
  if(lista&&window._refAllRows) lista.innerHTML=_buildRefCards(window._refAllRows);
}

// ── DESCUENTO ────────────────────────────────────────────────────
function abrirDescuentoRef(id,nombre,stockActual){
  var modal=document.createElement('div');
  modal.id='modal-ref-desc';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  // Ligar a OT abierta
  var otsAbiertas=ORDENES.filter(function(o){return o.estado==='abierta'&&o.tecnicoAsignado===currentUser.id;});
  var otOpts='<option value="">Sin ligar a OT</option>'+otsAbiertas.map(function(o){return '<option value="'+o.id+'">'+o.id+' — '+(o.linea||o.area||'—')+'</option>';}).join('');
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#5D4037;margin-bottom:4px">📤 Descontar Refacción</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">'+nombre+' · Stock actual: <strong>'+stockActual+'</strong></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Cantidad a descontar *</label>'
    +'<input type="number" id="ref-cant" class="form-control" min="1" max="'+stockActual+'" value="1" style="padding:12px;font-size:1.1rem;font-weight:700"></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Ligar a Orden de Trabajo</label>'
    +'<select id="ref-ot" class="form-control" style="padding:10px">'+otOpts+'</select></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Nota / motivo</label>'
    +'<input type="text" id="ref-nota" class="form-control" placeholder="Opcional" style="padding:10px"></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-ref-desc\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarDescuento(\''+id+'\','+stockActual+')" style="flex:2;padding:13px;background:#5D4037;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">📤 Confirmar Descuento</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function confirmarDescuento(id,stockActual){
  var cant=parseInt(document.getElementById('ref-cant').value)||0;
  if(cant<=0){showAlert('Cantidad inválida','error');return;}
  if(cant>stockActual){showAlert('No hay suficiente stock ('+stockActual+' disponibles)','error');return;}
  var otId=document.getElementById('ref-ot').value;
  var nota=document.getElementById('ref-nota').value.trim();
  var nuevaCant=stockActual-cant;
  // Actualizar stock
  fetch(SUPA_URL+'/rest/v1/refacciones?id=eq.'+id,{
    method:'PATCH',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
    body:JSON.stringify({cantidad:nuevaCant,updated_at:new Date().toISOString()})
  }).then(function(r){
    if(!r.ok){r.text().then(function(t){showAlert('Error: '+t.substring(0,80),'error');});return;}
    // Registrar movimiento
    fetch(SUPA_URL+'/rest/v1/refacciones_movimientos',{
      method:'POST',
      headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
      body:JSON.stringify({
        refaccion_id:id,tipo:'salida',cantidad:cant,
        cantidad_anterior:stockActual,cantidad_nueva:nuevaCant,
        usuario_id:currentUser.id,usuario_nombre:currentUser.nombre,
        orden_id:otId||null,nota:nota||null
      })
    });
    var m=document.getElementById('modal-ref-desc');if(m)m.remove();
    showAlert('✅ Descuento registrado: -'+cant+' piezas · Stock: '+nuevaCant);
    _refTab='catalogo';_renderRefTabs();
  });
}

// ── ENTRADA ──────────────────────────────────────────────────────
function abrirEntradaRef(id,nombre,stockActual){
  var modal=document.createElement('div');
  modal.id='modal-ref-ent';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#16a34a;margin-bottom:4px">📥 Entrada de Refacción</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">'+nombre+' · Stock actual: <strong>'+stockActual+'</strong></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Cantidad a agregar *</label>'
    +'<input type="number" id="ref-ent-cant" class="form-control" min="1" value="1" style="padding:12px;font-size:1.1rem;font-weight:700"></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Nota / proveedor</label>'
    +'<input type="text" id="ref-ent-nota" class="form-control" placeholder="Ej: Compra a proveedor XYZ" style="padding:10px"></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-ref-ent\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarEntrada(\''+id+'\','+stockActual+')" style="flex:2;padding:13px;background:#16a34a;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">📥 Confirmar Entrada</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function confirmarEntrada(id,stockActual){
  var cant=parseInt(document.getElementById('ref-ent-cant').value)||0;
  if(cant<=0){showAlert('Cantidad inválida','error');return;}
  var nota=document.getElementById('ref-ent-nota').value.trim();
  var nuevaCant=stockActual+cant;
  fetch(SUPA_URL+'/rest/v1/refacciones?id=eq.'+id,{
    method:'PATCH',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
    body:JSON.stringify({cantidad:nuevaCant,updated_at:new Date().toISOString()})
  }).then(function(r){
    if(!r.ok) return;
    fetch(SUPA_URL+'/rest/v1/refacciones_movimientos',{
      method:'POST',
      headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
      body:JSON.stringify({
        refaccion_id:id,tipo:'entrada',cantidad:cant,
        cantidad_anterior:stockActual,cantidad_nueva:nuevaCant,
        usuario_id:currentUser.id,usuario_nombre:currentUser.nombre,nota:nota||null
      })
    });
    var m=document.getElementById('modal-ref-ent');if(m)m.remove();
    showAlert('✅ Entrada registrada: +'+cant+' piezas · Stock: '+nuevaCant);
    _refTab='catalogo';_renderRefTabs();
  });
}

// ── QR ───────────────────────────────────────────────────────────
function mostrarQR(codigo,nombre,id){
  var modal=document.createElement('div');
  modal.id='modal-qr';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.75);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
  modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:24px;max-width:320px;width:100%;text-align:center;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;color:#1a3c5e;margin-bottom:4px">'+nombre+'</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">Código: '+codigo+'</div>'
    +'<div id="qr-container" style="display:flex;justify-content:center;margin-bottom:16px"></div>'
    +'<div style="font-size:.75rem;color:#9ca3af;margin-bottom:16px">Escanea para descontar del inventario</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button onclick="var m=document.getElementById(\'modal-qr\');if(m)m.remove()" style="flex:1;padding:12px;background:#f3f4f6;border:none;border-radius:10px;cursor:pointer">Cerrar</button>'
    +'<button onclick="imprimirQR(\''+codigo+'\',\''+nombre+'\')" style="flex:1;padding:12px;background:#1a3c5e;color:#fff;border:none;border-radius:10px;font-weight:700;cursor:pointer">🖨️ Imprimir</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  // Generar QR usando API pública
  var qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=200x200&data='+encodeURIComponent('REF:'+codigo);
  var img=document.createElement('img');
  img.src=qrUrl;
  img.style.cssText='width:200px;height:200px;border:1px solid #e5e7eb;border-radius:8px';
  document.getElementById('qr-container').appendChild(img);
}

function imprimirQR(codigo,nombre){
  var qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=250x250&data='+encodeURIComponent('REF:'+codigo);
  var w=window.open('','_blank');
  w.document.write('<html><head><title>QR '+nombre+'</title><style>body{font-family:Arial;text-align:center;padding:20px}h3{margin-bottom:4px}p{color:#666;margin:4px 0}img{border:1px solid #ddd;border-radius:8px}</style></head><body>');
  w.document.write('<h3>'+nombre+'</h3><p>Código: '+codigo+'</p><img src="'+qrUrl+'"><br><br>');
  w.document.write('<script>window.onload=function(){window.print();}<\/script></body></html>');
  w.document.close();
}

// ── ESCÁNER QR ───────────────────────────────────────────────────
function abrirEscanerQR(){
  var modal=document.createElement('div');
  modal.id='modal-escaner';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.9);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML='<div style="color:#fff;font-family:Nunito,sans-serif;font-size:17px;font-weight:800;margin-bottom:16px">📷 Escanear QR de Refacción</div>'
    +'<div style="background:#fff;border-radius:12px;padding:16px;margin-bottom:16px;width:100%;max-width:320px;box-sizing:border-box">'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:6px">Ingresa el código manualmente o escanea:</label>'
    +'<input type="text" id="qr-manual" class="form-control" placeholder="Ej: REF-001" style="padding:12px;font-size:1rem" autofocus>'
    +'</div>'
    +'<div style="display:flex;gap:10px;width:100%;max-width:320px">'
    +'<button onclick="var m=document.getElementById(\'modal-escaner\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="buscarRefPorCodigo(document.getElementById(\'qr-manual\').value)" style="flex:2;padding:13px;background:#5D4037;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">🔍 Buscar</button>'
    +'</div>'
    +'<div style="color:#9ca3af;font-size:.8rem;margin-top:16px;text-align:center">Tip: El código está en la etiqueta QR de la refacción</div>';
  document.body.appendChild(modal);
  setTimeout(function(){var el=document.getElementById('qr-manual');if(el)el.focus();},300);
}

function buscarRefPorCodigo(codigo){
  if(!codigo||!codigo.trim()){showAlert('Ingresa un código','error');return;}
  var cod=codigo.replace('REF:','').trim();
  supaFetch('refacciones','GET',null,'codigo=eq.'+encodeURIComponent(cod)+'&activo=eq.true').then(function(rows){
    var m=document.getElementById('modal-escaner');if(m)m.remove();
    if(!rows||!rows.length){showAlert('Refacción no encontrada: '+cod,'error');return;}
    var r=rows[0];
    abrirDescuentoRef(r.id,r.nombre,r.cantidad);
  });
}

// ── MOVIMIENTOS ──────────────────────────────────────────────────
function _renderMovimientosRef(cont){
  cont.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  supaFetch('refacciones_movimientos','GET',null,'order=created_at.desc&limit=100').then(function(rows){
    if(!rows||!rows.length){
      cont.innerHTML='<div class="card text-center" style="padding:40px"><div style="font-size:48px">📋</div><div style="font-weight:700;margin-top:12px">Sin movimientos registrados</div></div>';
      return;
    }
    // Enriquecer con nombre de refacción
    supaFetch('refacciones','GET',null,'select=id,nombre,codigo').then(function(refs){
      var refMap={};
      (refs||[]).forEach(function(r){refMap[r.id]=r;});
      cont.innerHTML=rows.map(function(m){
        var ref=refMap[m.refaccion_id]||{};
        var esSalida=m.tipo==='salida';
        var col=esSalida?'#dc2626':'#16a34a';
        var fecha=m.created_at?new Date(m.created_at).toLocaleDateString('es-MX',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
        return '<div class="card" style="border-left:4px solid '+col+';margin-bottom:8px;padding:12px">'
          +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
          +'<div>'
          +'<div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800">'+(ref.nombre||m.refaccion_id)+'</div>'
          +'<div style="font-size:11px;color:#6b7280">'+fecha+' · '+(m.usuario_nombre||'—')+'</div>'
          +(m.orden_id?'<div style="font-size:11px;color:#0891b2;margin-top:2px">OT: '+m.orden_id+'</div>':'')
          +(m.nota?'<div style="font-size:11px;color:var(--txt3);margin-top:2px">'+m.nota+'</div>':'')
          +'</div>'
          +'<div style="text-align:right">'
          +'<div style="font-size:1.3rem;font-weight:900;color:'+col+'">'+(esSalida?'-':'+')+m.cantidad+'</div>'
          +'<div style="font-size:.7rem;color:#9ca3af">'+m.cantidad_anterior+'→'+m.cantidad_nueva+'</div>'
          +'</div></div></div>';
      }).join('');
    });
  });
}

// ── NUEVA REFACCIÓN / EDITAR ─────────────────────────────────────
function _renderFormNuevaRef(cont,data){
  cont.innerHTML='<div class="card"><div class="card-title mb8">'+( data?'✏️ Editar Refacción':'➕ Nueva Refacción')+'</div>'
    +'<div class="form-group"><label class="form-label">Nombre *</label><input type="text" class="form-control" id="rn-nombre" value="'+(data?data.nombre:'')+'" placeholder="Ej: Rodamiento 6205"></div>'
    +'<div class="form-group"><label class="form-label">Código único *</label><input type="text" class="form-control" id="rn-codigo" value="'+(data?data.codigo:'')+'" placeholder="Ej: ROD-6205" '+(data?'readonly':'')+'></div>'
    +'<div class="form-group"><label class="form-label">Descripción</label><input type="text" class="form-control" id="rn-desc" value="'+(data?data.descripcion||'':'')+'" placeholder="Detalles adicionales..."></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<div class="form-group"><label class="form-label">Cantidad actual</label><input type="number" class="form-control" id="rn-cant" value="'+(data?data.cantidad:0)+'" min="0"></div>'
    +'<div class="form-group"><label class="form-label">Cantidad mínima</label><input type="number" class="form-control" id="rn-min" value="'+(data?data.cantidad_minima:1)+'" min="0"></div>'
    +'<div class="form-group"><label class="form-label">Ubicación</label><input type="text" class="form-control" id="rn-ubic" value="'+(data?data.ubicacion||'':'')+'" placeholder="Ej: Estante A-3"></div>'
    +'<div class="form-group"><label class="form-label">Precio unitario</label><input type="number" class="form-control" id="rn-precio" value="'+(data?data.precio_unitario||0:0)+'" min="0" step="0.01"></div>'
    +'</div>'
    +'<button class="btn btn-primary" onclick="guardarRefaccion(\''+( data?data.id:'')+'\')">💾 '+(data?'Actualizar':'Crear Refacción')+'</button>'
    +(data?'<button onclick="eliminarRef(\''+data.id+'\')" style="width:100%;margin-top:8px;padding:12px;background:#fee2e2;border:none;border-radius:10px;color:#dc2626;font-weight:700;cursor:pointer">🗑️ Eliminar refacción</button>':'')
    +'</div>';
}

function editarRef(id){
  supaFetch('refacciones','GET',null,'id=eq.'+id).then(function(rows){
    var r=rows&&rows[0];
    if(!r) return;
    _refTab='nuevo';
    _renderRefTabs();
    setTimeout(function(){_renderFormNuevaRef(document.getElementById('ref-content'),r);},50);
  });
}

function guardarRefaccion(id){
  var nombre=document.getElementById('rn-nombre').value.trim();
  var codigo=document.getElementById('rn-codigo').value.trim().toUpperCase();
  if(!nombre||!codigo){showAlert('Nombre y código son obligatorios','error');return;}
  var payload={
    nombre:nombre,codigo:codigo,
    descripcion:document.getElementById('rn-desc').value.trim()||null,
    cantidad:parseInt(document.getElementById('rn-cant').value)||0,
    cantidad_minima:parseInt(document.getElementById('rn-min').value)||1,
    ubicacion:document.getElementById('rn-ubic').value.trim()||null,
    precio_unitario:parseFloat(document.getElementById('rn-precio').value)||0,
    activo:true,updated_at:new Date().toISOString()
  };
  if(!id) payload.id=gen_id();
  var url=SUPA_URL+'/rest/v1/refacciones'+(id?'?id=eq.'+id:'');
  var method=id?'PATCH':'POST';
  fetch(url,{method:method,headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=representation'},body:JSON.stringify(payload)})
    .then(function(r){
      if(r.ok){showAlert('✅ Refacción guardada');_refTab='catalogo';_renderRefTabs();}
      else r.text().then(function(t){showAlert('⚠️ '+t.substring(0,80),'error');});
    });
}

function eliminarRef(id){
  if(!confirm('¿Eliminar esta refacción? Se conservarán sus movimientos.')) return;
  fetch(SUPA_URL+'/rest/v1/refacciones?id=eq.'+id,{
    method:'PATCH',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
    body:JSON.stringify({activo:false})
  }).then(function(){showAlert('✅ Refacción eliminada');_refTab='catalogo';_renderRefTabs();});
}

function gen_id(){return 'ref-'+Date.now().toString(36)+Math.random().toString(36).substr(2,5);}
// ── FIN MÓDULO REFACCIONES ───────────────────────────────────────

// ================================================================
// SUPER USUARIO — Elegir quién levanta o cierra
// ================================================================
function _superElegirUsuario(accion, callback){
  var modal=document.createElement('div');
  modal.id='modal-super-usuario';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
  var usersAll=USERS.filter(function(u){return u.rol!=='super'&&u.activo!==false;});
  var opts=usersAll.map(function(u){return '<option value="'+u.id+'">'+u.nombre+' ('+u.rol+')</option>';}).join('');
  modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:24px;max-width:420px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:16px;font-weight:800;color:#1a3c5e;margin-bottom:4px">👤 ¿Quién '+(accion==='levanta'?'levanta esta orden?':'cierra esta tarea?')+'</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">Super usuario — sin rastro propio</div>'
    +'<div style="margin-bottom:12px"><input type="text" id="super-busq-user" class="form-control" placeholder="🔍 Buscar usuario..." style="padding:10px;margin-bottom:8px" oninput="_filtrarSuperUsers(this.value)">'
    +'<select id="super-user-sel" class="form-control" style="padding:10px;height:160px" size="6">'+opts+'</select></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-super-usuario\');if(m)m.remove()" style="flex:1;padding:12px;background:#f3f4f6;border:none;border-radius:10px;cursor:pointer">Cancelar</button>'
    +'<button onclick="_confirmarSuperUser()" style="flex:2;padding:12px;background:#1a3c5e;color:#fff;border:none;border-radius:10px;font-weight:700;cursor:pointer">✅ Confirmar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  window._superUserCallback=callback;
  window._superUsersAll=usersAll;
  // Select first option
  setTimeout(function(){var s=document.getElementById('super-user-sel');if(s&&s.options.length)s.selectedIndex=0;},100);
}

function _filtrarSuperUsers(q){
  var sel=document.getElementById('super-user-sel');
  if(!sel||!window._superUsersAll) return;
  var filtered=window._superUsersAll.filter(function(u){
    return !q||u.nombre.toLowerCase().includes(q.toLowerCase())||(u.username||'').toLowerCase().includes(q.toLowerCase());
  });
  sel.innerHTML=filtered.map(function(u){return '<option value="'+u.id+'">'+u.nombre+' ('+u.rol+')</option>';}).join('');
}

function _confirmarSuperUser(){
  var sel=document.getElementById('super-user-sel');
  if(!sel||!sel.value){showAlert('Selecciona un usuario','error');return;}
  var uid=sel.value;
  var u=window._superUsersAll.find(function(x){return x.id===uid;});
  var m=document.getElementById('modal-super-usuario');if(m)m.remove();
  if(window._superUserCallback&&u) window._superUserCallback(u);
}
