// Técnico da Pre-cierre (queda pendiente de aprobación del operador)
function abrirPreCierre(id){
  otCerrandoId = id;
  document.getElementById('cierre-obs').value = '';
  document.getElementById('cierre-horas').value = '';
  document.getElementById('cierre-refacciones').value = '';
  document.getElementById('cierre-ref-wrap').classList.remove('hidden');
  // Cambiar título del modal
  var titulo = document.querySelector('#modal-cierre .modal-title');
  if(titulo) titulo.textContent = '🔧 Pre-cierre — Pendiente aprobación';
  // Ocultar tiempo calculado
  var tw = document.getElementById('cierre-tiempo-wrap');
  if(tw) tw.classList.add('hidden');
  // Cambiar botón confirmar para que llame a confirmarPreCierre
  var btnConfirmar = document.querySelector('#modal-cierre .btn-success');
  if(btnConfirmar){
    btnConfirmar.textContent = '🔧 Registrar Pre-cierre';
    btnConfirmar.onclick = confirmarPreCierre;
  }
  showModal('modal-cierre');
}

function confirmarPreCierre(){
  var o = ORDENES.find(function(x){return x.id===otCerrandoId;});
  if(!o) return;
  var obs = document.getElementById('cierre-obs').value.trim();
  if(!obs){ showAlert('Escribe las observaciones de lo que realizaste','error'); return; }
  var horas = parseFloat(document.getElementById('cierre-horas').value)||0;
  var refs  = document.getElementById('cierre-refacciones').value.trim();

  o.estado = 'pre_cierre';
  o.observacionesCierre = obs;
  o.horasCierre = horas;
  o.refaccionesUsadas = refs;
  o.preCierreTs  = Date.now();
  o.preCierrePor = currentUser.nombre;
  // Limpiar rechazo anterior al dar nuevo pre-cierre
  o.motivoRechazo = null;
  o.rechazadoPor  = null;
  o.rechazadoTs   = null;

  saveDB('ordenes', ORDENES);
  supabaseStatePatch(o.id, {
    estado: 'pre_cierre',
    pre_cierre_ts: o.preCierreTs,
    pre_cierre_por: o.preCierrePor,
    observaciones_cierre: o.observacionesCierre,
    horas_cierre: o.horasCierre,
    motivo_rechazo: null,
    rechazado_por: null
  });
  // Notificar al usuario que levantó la OT
  if(o.levantadoId){
    crearNotificacion(
      'pre_cierre',
      '🔧 Corrección lista para validar',
      'La OT '+o.id+' fue atendida por '+o.tecnicoNombre+'. Ingresa a revisar y aprobar o rechazar el cierre.',
      null,
      o.levantadoId,
      o.id
    );
  }
  cerrarModal('modal-cierre');
  showAlert('✅ Pre-cierre registrado — esperando aprobación del operador');
  showDetalle(otCerrandoId);
}

// Operador/Lider aprueba el cierre
function aprobarCierre(id){
  var o = ORDENES.find(function(x){return x.id===id;});
  if(!o) return;
  if(!confirm('¿Confirmas que la anormalidad fue resuelta correctamente?')) return;
  o.estado       = 'cerrada';
  o.cerradaTs    = Date.now();
  o.cerradaPor   = currentUser.nombre + ' (aprobación)';
  o.aprobadoPor  = currentUser.nombre;
  o.aprobadoTs   = Date.now();
  if(!o.historialModificacion) o.historialModificacion = [];
  o.historialModificacion.push({ts:Date.now(),por:nombreEfectivo(),campo:'Aprobación cierre',de:'pre_cierre',a:'cerrada'});
  saveDB('ordenes', ORDENES);
  supabaseStatePatch(o.id, {
    estado: 'cerrada',
    cerrada_ts: o.cerradaTs,
    cerrada_por: o.cerradaPor,
    aprobado_por: o.aprobadoPor
  });
  showAlert('✅ Anormalidad aprobada y cerrada');
  showDetalle(id);
}

