function opFiltrarPendientes(tipo, btn){
  window._opTipoActual = tipo;
  // Actualizar estilos botones principales
  ['azul','rojo','aprobar'].forEach(function(t){
    var b=document.getElementById('op-fil-'+t);
    if(!b) return;
    if(t===tipo){
      b.style.background=t==='azul'?'#1565C0':t==='rojo'?'#dc2626':'#7c3aed';
      b.style.color='#fff';
      b.style.borderColor=t==='azul'?'#1565C0':t==='rojo'?'#dc2626':'#7c3aed';
    } else {
      b.style.background='';b.style.color='';b.style.borderColor='';
    }
  });
  // Mostrar/ajustar subfiltros según tipo
  var sf = document.getElementById('op-subfiltro');
  if(sf){
    if(tipo==='aprobar'){
      sf.innerHTML='<button class="filter-chip active" id="op-sf-pendientes" onclick="opSubfiltro(&quot;pendiente&quot;,this)" style="font-size:11px;background:#7c3aed;color:#fff;border-color:#7c3aed">⏳ Pendientes</button>'
        +'<button class="filter-chip" id="op-sf-aprobadas" onclick="opSubfiltro(&quot;aprobada&quot;,this)" style="font-size:11px">✅ Aprobadas</button>';
      window._opSubfiltroActual='pendiente';
    } else {
      sf.innerHTML='<button class="filter-chip active" id="op-sf-abiertas" onclick="opSubfiltro(&quot;abierta&quot;,this)" style="font-size:11px;background:#374151;color:#fff;border-color:#374151">Abiertas</button>'
        +'<button class="filter-chip" id="op-sf-cerradas" onclick="opSubfiltro(&quot;cerrada&quot;,this)" style="font-size:11px">Cerradas</button>';
      window._opSubfiltroActual='abierta';
    }
  }
  opRenderLista(tipo, window._opSubfiltroActual);
}

function opSubfiltro(estado, btn){
  window._opSubfiltroActual=estado;
  // Estilos subfiltro
  var parent = btn ? btn.parentElement : null;
  if(parent) parent.querySelectorAll('.filter-chip').forEach(function(b){
    b.style.background='';b.style.color='';b.style.borderColor='';
  });
  if(btn){
    var col=window._opTipoActual==='aprobar'?'#7c3aed':window._opTipoActual==='azul'?'#1565C0':'#dc2626';
    btn.style.background=col;btn.style.color='#fff';btn.style.borderColor=col;
  }
  opRenderLista(window._opTipoActual||'azul', estado);
}

function opRenderLista(tipo, subfiltro){
  var lDiv=document.getElementById('mis-ordenes-list');
  if(!lDiv) return;
  var ots;
  if(tipo==='azul'){
    // Azules propias — pre_cierre NO aplica en azules (azul la cierra el mismo operador)
    ots=ORDENES.filter(function(o){
      return o.colorOT==='azul' && o.levantadoId===currentUser.id
        && (subfiltro==='abierta'?o.estado==='abierta':o.estado==='cerrada');
    });
  } else if(tipo==='rojo'){
    // Rojas levantadas — EXCLUIR pre_cierre (esas van en "Por Aprobar")
    ots=ORDENES.filter(function(o){
      return o.colorOT==='rojo' && o.levantadoId===currentUser.id
        && (subfiltro==='abierta'?o.estado==='abierta':o.estado==='cerrada');
    });
  } else { // aprobar — SOLO pre_cierre o cerradas aprobadas
    ots=ORDENES.filter(function(o){
      return o.levantadoId===currentUser.id
        && (subfiltro==='pendiente'?o.estado==='pre_cierre':(o.estado==='cerrada'&&o.aprobadoPor));
    });
  }
  ots=ots.sort(function(a,b){return b.ts-a.ts;});
  var ico=tipo==='azul'?'🔵':tipo==='rojo'?'🔴':'⏳';
  var msg=tipo==='azul'?'Sin anormalidades azules '+(subfiltro==='abierta'?'abiertas':'cerradas')
    :tipo==='rojo'?'Sin anormalidades rojas '+(subfiltro==='abierta'?'abiertas':'cerradas')
    :subfiltro==='pendiente'?'Sin anormalidades pendientes de aprobación':'Sin anormalidades aprobadas';
  lDiv.innerHTML=ots.length
    ?ots.map(function(o){return renderOTCard(o);}).join('')
    :'<div class="card text-center" style="padding:40px"><div style="font-size:48px">'+ico+'</div><div style="font-weight:700;margin-top:12px">'+msg+'</div></div>';
}
// ── FIN FILTRO OPERADOR ──────────────────────────────────────────

