    +'<div style="display:flex;flex-direction:column;gap:10px">'
    +'<button onclick="document.getElementById(\'modal-atc-opciones\').remove();guardarAtencion()" style="padding:16px;background:linear-gradient(135deg,#1565C0,#1976D2);color:#fff;border:none;border-radius:12px;font-size:.95rem;font-weight:700;cursor:pointer">📋 Guardar como Resuelta<br><span style="font-size:11px;font-weight:400;opacity:.85">La atención quedó cerrada normalmente</span></button>'
    +((tipo==='PM01'||tipo==='PM02')?'<button onclick="document.getElementById(\'modal-atc-opciones\').remove();guardarAtencionTemporal()" style="padding:16px;background:linear-gradient(135deg,#F59E0B,#FCD34D);color:#1a1a1a;border:none;border-radius:12px;font-size:.95rem;font-weight:700;cursor:pointer">⚡ Resuelta Temporalmente<br><span style="font-size:11px;font-weight:400;opacity:.8">Cierra la '+tipo+' y genera PM03 para solución definitiva</span></button>':'')
    +'<button onclick="document.getElementById(\'modal-atc-opciones\').remove()" style="padding:14px;background:#f3f4f6;border:none;border-radius:12px;font-size:.9rem;cursor:pointer">Cancelar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
