function abrirReprogramarPM03(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var modal=document.createElement('div');
  modal.id='modal-reprog-pm3';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  // Semanas disponibles desde la semana de la PM3 en adelante
  var semOpts='';
  var pSem=p.semana||currentWeek(), pAño=p.año||currentYear();
  for(var i=1;i<=16;i++){
    var s=pSem+i, a=pAño;
    if(s>52){s-=52;a++;}
    semOpts+='<option value="'+s+'-'+a+'">Sem '+s+' / '+a+'</option>';
  }
  // Técnicos
  var tecOpts=USERS.filter(function(u){return u.rol==='tecnico';}).map(function(u){
    return '<option value="'+u.id+'"'+(p.tecnicoId===u.id?' selected':'')+'>'+u.nombre+'</option>';
  }).join('');
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">📅 Reprogramar PM03</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">'+p.id+' — '+p.linea+' (Sem '+pSem+'/'+pAño+')</div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Nueva semana</label>'
    +'<select id="reprog-sem" class="form-control" style="padding:10px">'+semOpts+'</select></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Técnico asignado</label>'
    +'<select id="reprog-tec" class="form-control" style="padding:10px">'+tecOpts+'</select></div>'
    +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Motivo de reprogramación <span style="color:#dc2626">*obligatorio</span></label>'
    +'<textarea id="reprog-nota" class="form-control" rows="2" style="padding:10px;resize:none" placeholder="Ej: Falta de refacciones, paro de producción..."></textarea></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-reprog-pm3\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarReprogramar(\''+id+'\')" style="flex:1;padding:13px;background:#f59e0b;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">📅 Reprogramar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function confirmarReprogramar(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var nota=document.getElementById('reprog-nota').value.trim();
  if(!nota){showAlert('El motivo de reprogramación es obligatorio','error');return;}
  var semVal=document.getElementById('reprog-sem').value.split('-');
  var tecSel=document.getElementById('reprog-tec');
  var newSem=parseInt(semVal[0]),newAño=parseInt(semVal[1]);
  var tObj=tecSel?USERS.find(function(u){return u.id===tecSel.value;}):null;
  // Crear nueva PM03 con nueva semana
  var newId='PM03-'+p.linea.replace(/\s+/g,'-').substring(0,8)+'-S'+newSem+'-'+Date.now().toString().slice(-4);
  var nueva={
    id:newId, linea:p.linea, componente:p.componente, actividad:p.actividad,
    area:p.area, semana:newSem, año:newAño,
    tecnicoId:tObj?tObj.id:p.tecnicoId,
    tecnicoNombre:tObj?tObj.nombre:p.tecnicoNombre,
    estado:'abierta', estadoFlujo:'ejecucion',
    generadoPor:nombreEfectivo(),
    reprogramadaDe:id, notaReprogramacion:nota,
    ts:Date.now(), horaCreacion:new Date().toISOString(),
    actividadesEstado:{}, actividadesEstadoInicial:{}, actividadesEstadoFinal:{},
    comentariosActividades:{}
  };
  // Marcar la original como reprogramada
  p.reprogramadaA=newId;
  p.estado='reprogramada';
  p._editadoTs=Date.now();
  nueva._editadoTs=Date.now();
  if(currentUser.rol==='super') p.reprogramadaPorSuper=true;
  PM03_PLAN.push(nueva);
  saveDB('pm03_plan',PM03_PLAN);
  // PATCH directo para asegurar estado='reprogramada' en Supabase
  fetch(SUPA_URL+'/rest/v1/pm03_plan?id=eq.'+id,{
    method:'PATCH',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},
    body:JSON.stringify({estado:'reprogramada',reprogramada_a:newId,nota_reprogramacion:nota})
  }).then(function(){savePM03Supa(nueva);}).catch(function(){savePM03Supa(p);savePM03Supa(nueva);});
  var m=document.getElementById('modal-reprog-pm3');if(m)m.remove();
  showAlert('📅 PM03 reprogramada para semana '+newSem);
  // Regresar a la lista PM03 con botón de regreso funcional
  detalleBackScreen='screen-pm03';
  setTimeout(function(){
    renderPM03();
    showScreen('screen-pm03');
  },200);
}

// ================================================================
// PM03 POR REPROGRAMAR — Abiertas vencidas (lunes 6:30am)
// ================================================================
function showPM03PorReprogramar(){
  detalleBackScreen='screen-ordenes';
  if(!window._pm3RepSem) window._pm3RepSem=currentWeek();
  if(!window._pm3RepAnio) window._pm3RepAnio=currentYear();
  if(!window._pm3RepMes) window._pm3RepMes=0;

  var sw=window._pm3RepSem, año=window._pm3RepAnio;
  // Fecha de lanzamiento de la app: semana 21 de 2026
  var SEMANA_LANZAMIENTO=21, ANIO_LANZAMIENTO=2026;

    // Determinar si una semana ya está vencida (pasó el lunes 6:30am siguiente)
  var ahora=new Date();
  var diaSemana=ahora.getDay(); // 0=dom,1=lun,...
  var horaActual=ahora.getHours()+ahora.getMinutes()/60;
  // Una semana S está vencida si ya pasó el lunes 6:30 de la semana S+1
  // Es decir: currentWeek() > S, o (currentWeek()===S+1 y es lunes >=6:30) o semana anterior
  function esVencida(semPM,añoPM){
    if(añoPM<currentYear()) return true;
    if(añoPM===currentYear()){
      if(semPM<currentWeek()) return true;
      if(semPM===currentWeek()){
        // Vence el lunes siguiente a las 6:30 — aún no vence si estamos en la misma semana
        // antes del lunes 6:30 de la semana siguiente
        return false;
      }
      // semana futura — no vence
      return false;
    }
    return false;
  }

  var pm3Vencidas=PM03_PLAN.filter(function(p){
    if(p.estado==='cerrada'||p.estado==='reprogramada') return false;
    // Incluir siempre las marcadas explícitamente como por_reprogramar
    if(p.estadoFlujo==='por_reprogramar') return true;
    // Solo mostrar desde semana 21/2026 en adelante
    if((p.año||2026)<ANIO_LANZAMIENTO) return false;
    if((p.año||2026)===ANIO_LANZAMIENTO&&p.semana<SEMANA_LANZAMIENTO) return false;
    // Solo mostrar si ya está vencida
    if(!esVencida(p.semana,p.año||2026)) return false;
    // Filtrar por período seleccionado
    if(window._pm3RepMes>0){
      var sems=getWeeksInMonth(año,window._pm3RepMes);
      return sems.indexOf(p.semana)>=0&&(p.año||2026)===año;
    }
    return p.semana===sw&&(p.año||2026)===año;
  }).sort(function(a,b){return a.semana-b.semana;});

  var fDiv=document.getElementById('ordenes-filtros');
  var lDiv=document.getElementById('mis-ordenes-list');

  // Filtros semana/mes/año
  var semOpts=Array.from({length:52},function(_,i){return '<option value="'+(i+1)+'"'+(sw===(i+1)?' selected':'')+'>Sem '+(i+1)+'</option>';}).join('');
  var meses=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  var mesOpts='<option value="0">Todas</option>'+meses.map(function(m,i){return '<option value="'+(i+1)+'"'+(window._pm3RepMes===(i+1)?' selected':'')+'>'+m+'</option>';}).join('');
  var añoOpts=[año-1,año,año+1].map(function(a){return '<option value="'+a+'"'+(año===a?' selected':'')+'>'+a+'</option>';}).join('');

  fDiv.innerHTML='<div style="background:#dc2626;color:#fff;border-radius:10px;padding:10px 14px;font-size:.88rem;font-weight:700;margin-bottom:8px">📅 PM03 por Reprogramar</div>'
    +'<div style="display:flex;gap:6px;margin-bottom:8px;flex-wrap:wrap">'
    +'<div style="flex:1;min-width:70px"><label style="font-size:.7rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Semana</label>'
    +'<select class="form-control" style="padding:6px;font-size:.82rem" onchange="window._pm3RepSem=parseInt(this.value);window._pm3RepMes=0;showPM03PorReprogramar()">'+semOpts+'</select></div>'
    +'<div style="flex:1;min-width:60px"><label style="font-size:.7rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Mes</label>'
    +'<select class="form-control" style="padding:6px;font-size:.82rem" onchange="window._pm3RepMes=parseInt(this.value);if(window._pm3RepMes)window._pm3RepSem=0;showPM03PorReprogramar()">'+mesOpts+'</select></div>'
    +'<div style="flex:1;min-width:60px"><label style="font-size:.7rem;font-weight:700;color:#6b7280;display:block;margin-bottom:2px">Año</label>'
    +'<select class="form-control" style="padding:6px;font-size:.82rem" onchange="window._pm3RepAnio=parseInt(this.value);showPM03PorReprogramar()">'+añoOpts+'</select></div>'
    +'</div>';

  if(!pm3Vencidas.length){
    lDiv.innerHTML='<div class="card text-center" style="padding:40px"><div style="font-size:48px">✅</div><div style="font-weight:700;margin-top:12px">Sin PM03 vencidas en este período</div></div>';
  } else {
    lDiv.innerHTML=pm3Vencidas.map(function(p){
      return '<div class="ot-card pm03" onclick="showDetallePM03(\''+p.id+'\')" style="border-left:4px solid #dc2626">'
        +'<div style="display:flex;justify-content:space-between;margin-bottom:4px">'
        +'<span style="font-size:11px;color:#dc2626;font-weight:700">'+p.id+'</span>'
        +'<span class="badge" style="background:#dc2626;color:#fff">Sem '+p.semana+' — Vencida</span>'
        +'</div>'
        +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;margin:2px 0 4px">'+p.linea+'</div>'
        +'<div style="font-size:12px;color:var(--txt2)">'+(p.tecnicoNombre||'Sin asignar')+'</div>'
        +'<div style="margin-top:8px;display:flex;gap:6px">'
        +'<button class="btn" onclick="event.stopPropagation();abrirReprogramarPM03(\''+p.id+'\')" style="flex:1;background:#f59e0b;color:#fff;border:none;font-size:12px;padding:8px;border-radius:8px">📅 Reprogramar</button>'
        +'</div></div>';
    }).join('');
  }
  showScreen('screen-ordenes');
}

// ================================================================
// FIRMAS CON COMENTARIO (máx 20 caracteres)
// ================================================================
function liberarPM03ConComentario(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var modal=document.createElement('div');
  modal.id='modal-liberar-comentario';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  var reqLimp=p.limpiezaMtto||p.desinfProduccion;
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">🔬 Liberar PM03</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:12px">'+p.linea+' — Sem '+p.semana+'/'+p.año+'</div>'
    +'<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:12px;margin-bottom:12px;font-size:.88rem;color:#166534">✅ Confirmo la liberación de línea por limpieza y sanitización para arranque.</div>'
    +(reqLimp?'<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:10px;padding:10px;margin-bottom:12px"><div style="font-size:.82rem;font-weight:700;color:#92400e;margin-bottom:6px">⚠️ Requiere limpieza antes del arranque</div>'
    +'<button id="limp-si-btn2" onclick="calToggleLimp(true)" style="width:100%;padding:9px;border:2px solid #d97706;border-radius:8px;background:#fff;font-weight:700;font-size:.85rem;cursor:pointer">✅ Me doy por enterado</button></div>':'')
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Comentario en firma (opcional, máx 20 caracteres)</label>'
    +'<input type="text" id="liberar-comentario" class="form-control" maxlength="20" placeholder="Ej: Sin observaciones" style="padding:10px">'
    +'<div id="liberar-char-count" style="font-size:11px;color:#9ca3af;text-align:right;margin-top:2px">0/20</div></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-liberar-comentario\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarLiberarPM03ConCom(\''+id+'\')" style="flex:1;padding:13px;background:#16a34a;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">✅ Liberar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  window._calLimpConfirmado=!reqLimp;
  document.getElementById('liberar-comentario').addEventListener('input',function(){
    document.getElementById('liberar-char-count').textContent=this.value.length+'/20';
  });
}

function confirmarLiberarPM03ConCom(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  if((p.limpiezaMtto||p.desinfProduccion)&&!window._calLimpConfirmado){
    showAlert('Confirma que te diste por enterado de la limpieza requerida','error');return;
  }
  var com=document.getElementById('liberar-comentario');
  var comentario=com?com.value.trim().substring(0,20):'';
  // Cerrar modal antes de mostrar el de selección de usuario
  var m=document.getElementById('modal-liberar-comentario');if(m)m.remove();
  superElegirNombreFirma(function(nombreFirma, trazabilidad){
    p.liberadoPor=nombreFirma;
    p.liberadoTs=Date.now();
    p.estadoCalidad='liberada';
    p.estadoFlujo='completo'; // Firmas suspendidas
    p.comentarioFirmaCalidad=comentario;
    p.calLimpConfirmada=window._calLimpConfirmado;
    if(trazabilidad&&trazabilidad!==nombreFirma) p._trazabilidadCalidad=trazabilidad;
    saveDB('pm03_plan',PM03_PLAN);
    savePM03Supa(p);
    showAlert('✅ PM03 liberada — enviada a Producción');
    showMisOrdenes();
  });
}

// Redirigir liberarPM03 al modal con comentario
var _origLiberarPM03=liberarPM03;
function liberarPM03(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(p) liberarPM03ConComentario(id);
}

// Firma producción con comentario
function abrirLiberarProduccionConCom(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var modal=document.createElement('div');
  modal.id='modal-liberar-prod-com';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">🏭 Liberación Producción</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:12px">'+p.linea+' — Sem '+p.semana+'/'+p.año+'</div>'
    +'<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:12px;margin-bottom:12px;font-size:.88rem;color:#166534">✅ Confirmo que la línea está limpia, armada y ajustada para su arranque.</div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Comentario en firma (opcional, máx 20 caracteres)</label>'
    +'<input type="text" id="prod-comentario" class="form-control" maxlength="20" placeholder="Ej: Arranque ok" style="padding:10px">'
    +'<div id="prod-char-count" style="font-size:11px;color:#9ca3af;text-align:right;margin-top:2px">0/20</div></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-liberar-prod-com\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="confirmarLiberarProdConCom(\''+id+'\')" style="flex:1;padding:13px;background:#16a34a;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">✅ Liberar Línea</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  document.getElementById('prod-comentario').addEventListener('input',function(){
    document.getElementById('prod-char-count').textContent=this.value.length+'/20';
  });
}

function confirmarLiberarProdConCom(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  var com=document.getElementById('prod-comentario');
  var comentario=com?com.value.trim().substring(0,20):'';
  var m=document.getElementById('modal-liberar-prod-com');if(m)m.remove();
  superElegirNombreFirma(function(nombreFirma, trazabilidad){
    p.liberadoProdPor=nombreFirma;
    p.liberadoProdTs=Date.now();
    p.estadoFlujo='pendiente_admin';
    p.comentarioFirmaProd=comentario;
    if(trazabilidad&&trazabilidad!==nombreFirma) p._trazabilidadProd=trazabilidad;
    saveDB('pm03_plan',PM03_PLAN);
    savePM03Supa(p);
    showAlert('✅ Línea liberada — enviada a Administración');
    showLiberacionProduccion();
  });
}

// Redirigir abrirLiberarProduccion al modal con comentario
var _origAbrirLiberarProduccion=abrirLiberarProduccion;
function abrirLiberarProduccion(id){
  abrirLiberarProduccionConCom(id);
}

// ================================================================
// MÓDULO PROVEEDORES
// ================================================================
var ACTIVIDADES_PROV=[
  'Trabajos de electricidad','Trabajos de construcción','Trabajos de drenajes',
  'Trabajos pintura y repelle','Trabajos de pisos','Trabajos de estructuras',
  'Mtto preventivo a equipos','Trabajos de pailería','Plataformas',
  'Montacargas','Patines','Otros (especificar)'
];

var _provBusqueda='';

function showProveedores(){
  detalleBackScreen='screen-ordenes';
  var fDiv=document.getElementById('ordenes-filtros');
  var lDiv=document.getElementById('mis-ordenes-list');
  fDiv.innerHTML=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
    +'<div style="font-family:Nunito,sans-serif;font-size:16px;font-weight:800;color:#1a3c5e">🏢 Proveedores</div>'
    +'<button onclick="abrirEditorProveedor(null)" style="padding:8px 14px;background:#1a3c5e;color:#fff;border:none;border-radius:8px;font-size:.85rem;font-weight:700;cursor:pointer">+ Agregar</button>'
    +'</div>'
    +'<div style="display:flex;gap:8px;margin-bottom:4px">'
    +'<input type="text" id="prov-busq" class="form-control" placeholder="🔍 Buscar por nombre, contacto o actividad..." value="'+_provBusqueda+'" oninput="_provBusqueda=this.value;renderProveedores()" style="flex:1;padding:9px;font-size:.85rem">'
    +'</div>';

  renderProveedores();
  showScreen('screen-ordenes');
}

function renderProveedores(){
  var lDiv=document.getElementById('mis-ordenes-list');
  if(!lDiv) return;
  lDiv.innerHTML='<div style="text-align:center;padding:24px;color:var(--txt3)">Cargando...</div>';
  supaFetch('proveedores','GET',null,'activo=eq.true&order=nombre.asc').then(function(rows){
    var q=(_provBusqueda||'').toLowerCase();
    var filtered=(rows||[]).filter(function(p){
      if(!q) return true;
      var acts=(p.actividades||[]).join(' ').toLowerCase();
      var contactos=JSON.stringify(p.contactos||[]).toLowerCase();
      return p.nombre.toLowerCase().includes(q)||acts.includes(q)||contactos.includes(q);
    });
    if(!filtered.length){
      lDiv.innerHTML='<div class="card text-center" style="padding:40px"><div style="font-size:48px">🏢</div><div style="font-weight:700;margin-top:12px">'+(q?'Sin resultados para "'+q+'"':'Sin proveedores registrados')+'</div></div>';
      return;
    }
    lDiv.innerHTML=filtered.map(function(p){
      var acts=p.actividades||[];
      var contacts=p.contactos||[];
      // Fallback: si tiene campo antiguo contacto/correo
      if(!contacts.length&&(p.contacto||p.correo)){
        contacts=[{nombre:p.contacto||'',correo:p.correo||'',cel:''}];
      }
      return '<div class="card" style="margin-bottom:10px">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
        +'<div style="flex:1">'
        +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800">'+p.nombre+'</div>'
        // Contactos
        +(contacts.length?'<div style="margin-top:6px">'+contacts.map(function(c,i){
          return '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:4px;font-size:11px;color:var(--txt2);margin-bottom:2px;background:#f8fafc;border-radius:6px;padding:4px 6px">'
            +'<span>👤 '+(c.nombre||'—')+'</span>'
            +'<span>✉️ '+(c.correo||'—')+'</span>'
            +'<span>📱 '+(c.cel||'—')+'</span>'
            +'</div>';
        }).join('')+'</div>':'')
        // Actividades
        +(acts.length?'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">'+acts.map(function(a){
          return '<span style="background:#f3f4f6;border-radius:12px;padding:2px 8px;font-size:11px;color:#374151">'+a+'</span>';
        }).join('')+'</div>':'')
        +(p.notas?'<div style="font-size:11px;color:var(--txt3);margin-top:4px">📝 '+p.notas+'</div>':'')
        +'</div>'
        +'<button onclick="abrirEditorProveedor(\''+p.id+'\')" style="padding:6px 12px;background:#f3f4f6;border:none;border-radius:7px;font-size:.8rem;cursor:pointer;margin-left:8px;flex-shrink:0">✏️</button>'
        +'</div></div>';
    }).join('');
  }).catch(function(){
    lDiv.innerHTML='<div class="card text-center" style="padding:24px;color:#dc2626">Error al cargar proveedores</div>';
  });
}

function abrirEditorProveedor(id){
  var modal=document.createElement('div');
  modal.id='modal-editor-prov';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;overflow-y:auto;padding:16px;box-sizing:border-box';

  supaFetch('proveedores','GET',null,'activo=eq.true').then(function(rows){
    var p=id?(rows||[]).find(function(r){return r.id===id;}):null;
    var selActs=p&&p.actividades?p.actividades:[];
    // Contactos: usar array de contactos o migrar campo antiguo
    var contacts=p&&p.contactos?p.contactos:[];
    if(!contacts.length&&p&&(p.contacto||p.correo)){
      contacts=[{nombre:p.contacto||'',correo:p.correo||'',cel:''}];
    }
    while(contacts.length<1) contacts.push({nombre:'',correo:'',cel:''});

    function contactRow(c,i){
      return '<div id="prov-cont-'+i+'" style="display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:6px;align-items:center;margin-bottom:6px">'
        +'<input type="text" id="prov-cont-nom-'+i+'" class="form-control" placeholder="Nombre" value="'+(c.nombre||'')+'" style="padding:8px;font-size:.82rem">'
        +'<input type="email" id="prov-cont-cor-'+i+'" class="form-control" placeholder="Correo" value="'+(c.correo||'')+'" style="padding:8px;font-size:.82rem">'
        +'<input type="tel" id="prov-cont-cel-'+i+'" class="form-control" placeholder="Celular" value="'+(c.cel||'')+'" style="padding:8px;font-size:.82rem">'
        +(i>0?'<button onclick="provRemoveCont('+i+')" style="padding:6px 8px;background:#fee2e2;border:none;border-radius:6px;color:#dc2626;cursor:pointer">✕</button>':'<span></span>')
        +'</div>';
    }

    var actOpts=ACTIVIDADES_PROV.map(function(a){
      var sel=selActs.indexOf(a)>=0;
      return '<label style="display:flex;align-items:center;gap:8px;padding:7px;border:1px solid '+(sel?'#1a3c5e':'#e5e7eb')+';border-radius:8px;background:'+(sel?'#f0f4ff':'#fff')+';cursor:pointer;margin-bottom:4px">'
        +'<input type="checkbox" value="'+a+'"'+(sel?' checked':'')+' onchange="provToggleAct(this)" style="width:16px;height:16px">'
        +'<span style="font-size:.84rem">'+a+'</span></label>';
    }).join('');

    modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:20px;max-width:580px;margin:auto;box-sizing:border-box">'
      +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:16px">'+(p?'✏️ Editar Proveedor':'🏢 Nuevo Proveedor')+'</div>'
      +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Nombre de empresa *</label>'
      +'<input type="text" id="prov-nombre" class="form-control" value="'+(p?p.nombre:'')+'" style="padding:10px"></div>'
      // Contactos
      +'<div style="margin-bottom:12px">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'
      +'<label style="font-size:.75rem;font-weight:700;color:#374151">Contactos (hasta 3)</label>'
      +'<button onclick="provAddCont()" id="prov-btn-add-cont" style="padding:4px 10px;background:#1a3c5e;color:#fff;border:none;border-radius:6px;font-size:.78rem;cursor:pointer">+ Agregar</button>'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:4px;margin-bottom:4px">'
      +'<span style="font-size:.7rem;font-weight:700;color:#9ca3af;padding:0 4px">Nombre</span>'
      +'<span style="font-size:.7rem;font-weight:700;color:#9ca3af;padding:0 4px">Correo</span>'
      +'<span style="font-size:.7rem;font-weight:700;color:#9ca3af;padding:0 4px">Celular</span>'
      +'<span></span></div>'
      +'<div id="prov-contacts-list">'+contacts.map(contactRow).join('')+'</div>'
      +'</div>'
      // Actividades
      +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:6px">Actividades que realiza</label>'
      +'<div id="prov-acts">'+actOpts+'</div></div>'
      +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Notas adicionales</label>'
      +'<textarea id="prov-notas" class="form-control" rows="2" style="padding:10px;resize:none">'+(p?p.notas||'':' ')+'</textarea></div>'
      +'<div style="display:flex;gap:10px">'
      +'<button onclick="var m=document.getElementById(\'modal-editor-prov\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
      +'<button onclick="guardarProveedor(\''+( id||'')+'\' )" style="flex:2;padding:13px;background:#1a3c5e;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
      +'</div></div>';
    document.body.appendChild(modal);
    window._provContCount=contacts.length;
  });
}

function provAddCont(){
  var list=document.getElementById('prov-contacts-list');
  if(!list) return;
  var cnt=(list.querySelectorAll('[id^="prov-cont-"]').length);
  if(cnt>=3){showAlert('Máximo 3 contactos permitidos','error');return;}
  var i=window._provContCount||cnt;
  var div=document.createElement('div');
  div.id='prov-cont-'+i;
  div.style.cssText='display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:6px;align-items:center;margin-bottom:6px';
  div.innerHTML='<input type="text" id="prov-cont-nom-'+i+'" class="form-control" placeholder="Nombre" style="padding:8px;font-size:.82rem">'
    +'<input type="email" id="prov-cont-cor-'+i+'" class="form-control" placeholder="Correo" style="padding:8px;font-size:.82rem">'
    +'<input type="tel" id="prov-cont-cel-'+i+'" class="form-control" placeholder="Celular" style="padding:8px;font-size:.82rem">'
    +'<button onclick="provRemoveCont('+i+')" style="padding:6px 8px;background:#fee2e2;border:none;border-radius:6px;color:#dc2626;cursor:pointer">✕</button>';
  list.appendChild(div);
  window._provContCount=(window._provContCount||0)+1;
  if(list.querySelectorAll('[id^="prov-cont-"]').length>=3){
    var btn=document.getElementById('prov-btn-add-cont');
    if(btn) btn.style.display='none';
  }
}

function provRemoveCont(i){
  var div=document.getElementById('prov-cont-'+i);
  if(div) div.remove();
  var btn=document.getElementById('prov-btn-add-cont');
  if(btn) btn.style.display='';
}

function provToggleAct(cb){
  var lbl=cb.closest('label');
  if(!lbl) return;
  lbl.style.borderColor=cb.checked?'#1a3c5e':'#e5e7eb';
  lbl.style.background=cb.checked?'#f0f4ff':'#fff';
}

function guardarProveedor(id){
  var nombre=document.getElementById('prov-nombre').value.trim();
  if(!nombre){showAlert('El nombre es obligatorio','error');return;}
  // Leer contactos
  var contacts=[];
  document.querySelectorAll('[id^="prov-cont-"]').forEach(function(div){
    var idx=div.id.replace('prov-cont-','');
    var nom=document.getElementById('prov-cont-nom-'+idx);
    var cor=document.getElementById('prov-cont-cor-'+idx);
    var cel=document.getElementById('prov-cont-cel-'+idx);
    if(nom&&(nom.value.trim()||cor&&cor.value.trim()||cel&&cel.value.trim())){
      contacts.push({nombre:nom?nom.value.trim():'',correo:cor?cor.value.trim():'',cel:cel?cel.value.trim():''});
    }
  });
  var notas=document.getElementById('prov-notas').value.trim();
  var acts=[];
  document.querySelectorAll('#prov-acts input[type="checkbox"]:checked').forEach(function(cb){acts.push(cb.value);});
  var payload={nombre:nombre,contactos:contacts,actividades:acts,notas:notas,activo:true};
  var url=SUPA_URL+'/rest/v1/proveedores';
  var method='POST';
  var headers={'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=representation'};
  if(id){url+='?id=eq.'+id;method='PATCH';}
  fetch(url,{method:method,headers:headers,body:JSON.stringify(payload)}).then(function(r){
    if(r.ok){var m=document.getElementById('modal-editor-prov');if(m)m.remove();showAlert('✅ Proveedor guardado');showProveedores();}
    else r.text().then(function(t){showAlert('⚠️ Error: '+t.substring(0,80),'error');});
  });
}

// ── FIN MÓDULOS ──────────────────────────────────────────────────

// ================================================================
// KPI ANORMALIDADES — Solo operador/lider, con filtro de línea
// ================================================================
function showKPIAnormalidades(){
  detalleBackScreen='screen-ordenes';
  var fDiv=document.getElementById('ordenes-filtros');
  var lDiv=document.getElementById('mis-ordenes-list');

  // Solo PM02 levantadas por operadores y líderes
  var pm02Op=ORDENES.filter(function(o){
    if(o.tipo!=='PM02') return false;
    var r=o.rolLevantador||'';
    return r==='operador'||r==='lider'||r==='inspector_calidad'||r==='lider_calidad'||r==='administrativo'||r==='supply';
  });

  // Líneas de producción disponibles
  var lineas=[...new Set(pm02Op.map(function(o){return o.linea||o.area||'—';}))].filter(Boolean).sort();
  if(!window._kpiAnomLinea) window._kpiAnomLinea='';
  if(!window._kpiAnomSem) window._kpiAnomSem=0;
  if(!window._kpiAnomAño) window._kpiAnomAño=currentYear();
  if(window._kpiAnomBusq===undefined) window._kpiAnomBusq='';

  // Filtrar por línea
  var pm02Fil=window._kpiAnomLinea?pm02Op.filter(function(o){
    return (o.linea||o.area||'')===window._kpiAnomLinea;
  }):pm02Op;

  // Filtrar por semana/año si se seleccionó
  if(window._kpiAnomSem>0){
    pm02Fil=pm02Fil.filter(function(o){
      return o.semana===window._kpiAnomSem&&(o.año||2026)===window._kpiAnomAño;
    });
  }

  // Filtrar por búsqueda de texto
  if(window._kpiAnomBusq&&window._kpiAnomBusq.trim()){
    var q=window._kpiAnomBusq.trim().toLowerCase();
    pm02Fil=pm02Fil.filter(function(o){
      return (o.id||'').toLowerCase().includes(q)
        ||(o.linea||o.area||'').toLowerCase().includes(q)
        ||(o.componente||'').toLowerCase().includes(q)
        ||(o.detalle||'').toLowerCase().includes(q)
        ||(o.levantadoPor||'').toLowerCase().includes(q)
        ||(o.tecnicoNombre||'').toLowerCase().includes(q)
        ||(o.tipoAnormalidad||'').toLowerCase().includes(q);
    });
  }

  // Calculos
  var total=pm02Fil.length;
  var cerradas=pm02Fil.filter(function(o){return o.estado==='cerrada';}).length;
  var abiertas=total-cerradas;
  var pct=total?Math.round((cerradas/total)*100):0;
  var colPct=pct>=80?'#16a34a':'#d97706';
  var rojas=pm02Fil.filter(function(o){return o.colorOT==='rojo';});
  var azules=pm02Fil.filter(function(o){return o.colorOT==='azul';});
  var sinColor=pm02Fil.filter(function(o){return !o.colorOT;}).length;
  var prioA=pm02Fil.filter(function(o){return o.prioridad==='A';});
  var prioB=pm02Fil.filter(function(o){return o.prioridad==='B';});
  var prioC=pm02Fil.filter(function(o){return o.prioridad==='C';});

  // Selector de líneas
  var lineaOpts='<option value="">Todas las líneas</option>'+lineas.map(function(l){
    return '<option value="'+l+'"'+(window._kpiAnomLinea===l?' selected':'')+'>'+l+'</option>';
  }).join('');

  // Semanas disponibles
  var semOpts='<option value="0">Todas las semanas</option>'+Array.from({length:52},function(_,i){
    return '<option value="'+(i+1)+'"'+(window._kpiAnomSem===(i+1)?' selected':'')+'>Sem '+(i+1)+'</option>';
  }).join('');

  var añoOpts=[currentYear()-1,currentYear()].map(function(a){
    return '<option value="'+a+'"'+(window._kpiAnomAño===a?' selected':'')+'>'+a+'</option>';
  }).join('');

  fDiv.innerHTML=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
    +'<div style="font-family:Nunito,sans-serif;font-size:16px;font-weight:800;color:#C62828">📊 KPI Anormalidades — Operador / Lider</div>'
    +'<button onclick="exportarKPIAnomExcel()" style="padding:6px 12px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-size:.78rem;font-weight:700;cursor:pointer">⬇️ Excel</button>'
    +'</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">'
    +'<select class="form-control" style="flex:2;min-width:130px;padding:7px;font-size:.82rem" onchange="window._kpiAnomLinea=this.value;showKPIAnormalidades()">'+lineaOpts+'</select>'
    +'<select class="form-control" style="flex:1;min-width:80px;padding:7px;font-size:.82rem" onchange="window._kpiAnomSem=parseInt(this.value)||0;showKPIAnormalidades()">'+semOpts+'</select>'
    +'<select class="form-control" style="flex:1;min-width:70px;padding:7px;font-size:.82rem" onchange="window._kpiAnomAño=parseInt(this.value)||currentYear();showKPIAnormalidades()">'+añoOpts+'</select>'
    +'</div>'
    +'<input type="text" class="form-control" placeholder="🔍 Buscar por ID, línea, componente, detalle, técnico..." value="'+(window._kpiAnomBusq||'')+'" oninput="window._kpiAnomBusq=this.value;showKPIAnormalidades()" style="margin-bottom:4px;font-size:.84rem">';

  // KPI cards grandes
  lDiv.innerHTML=
    // Fila 1: Generadas | Cerradas | Abiertas
    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:10px">'
    +kpiCardGrande('Generadas', total, '#1a3c5e', '')
    +kpiCardGrande('Cerradas', cerradas, '#16a34a', '')
    +kpiCardGrande('Abiertas', abiertas, '#d97706', '')
    +'</div>'
    // Fila 2: Rojas | Azules
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">'
    +kpiCardGrande('🔴 Rojas', rojas.length, '#C62828', 'Cer: '+rojas.filter(function(o){return o.estado==='cerrada';}).length+' · Ab: '+rojas.filter(function(o){return o.estado!=='cerrada';}).length)
    +kpiCardGrande('🔵 Azules', azules.length, '#1565C0', 'Cer: '+azules.filter(function(o){return o.estado==='cerrada';}).length+' · Ab: '+azules.filter(function(o){return o.estado!=='cerrada';}).length)
    +'</div>'
    // Fila 3: Prio A | B | C
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:10px">'
    +kpiCardGrande('Prio A', prioA.length, '#C62828', 'Cer: '+prioA.filter(function(o){return o.estado==='cerrada';}).length+' · Ab: '+prioA.filter(function(o){return o.estado!=='cerrada';}).length)
    +kpiCardGrande('Prio B', prioB.length, '#F57C00', 'Cer: '+prioB.filter(function(o){return o.estado==='cerrada';}).length+' · Ab: '+prioB.filter(function(o){return o.estado!=='cerrada';}).length)
    +kpiCardGrande('Prio C', prioC.length, '#16a34a', 'Cer: '+prioC.filter(function(o){return o.estado==='cerrada';}).length+' · Ab: '+prioC.filter(function(o){return o.estado!=='cerrada';}).length)
    +'</div>'
    // Barra % cierre
    +'<div class="card" style="padding:16px;margin-bottom:10px">'
    +'<div style="display:flex;justify-content:space-between;font-size:.85rem;font-weight:700;margin-bottom:6px">'
    +'<span>% Cierre de Anormalidades</span>'
    +'<span style="color:'+colPct+'">'+pct+'%</span>'
    +'</div>'
    +'<div style="background:#f3f4f6;border-radius:8px;height:16px;overflow:hidden">'
    +'<div style="width:'+pct+'%;height:100%;background:'+colPct+';border-radius:8px;transition:width .5s"></div>'
    +'</div>'
    +'<div style="font-size:.75rem;color:#9ca3af;margin-top:4px;text-align:right">Meta: ≥80% verde · <80% naranja</div>'
    +'</div>'
    // Sin color
    +(sinColor>0?'<div style="background:#fee2e2;border-radius:10px;padding:10px 14px;font-size:.85rem;color:#C62828;font-weight:700;margin-bottom:10px">⚠️ '+sinColor+' anormalidades sin clasificar (roja/azul)</div>':'')
    // Lista de anormalidades
    +(window._kpiAnomBusq&&window._kpiAnomBusq.trim()
      ?'<div style="font-size:.75rem;font-weight:700;color:#6b7280;text-transform:uppercase;margin-bottom:6px">Resultados ('+pm02Fil.length+')</div>'
      :'<div style="font-size:.75rem;font-weight:700;color:#6b7280;text-transform:uppercase;margin-bottom:6px">Últimas 10 anormalidades</div>'
    )
    +'<div>'+(window._kpiAnomBusq&&window._kpiAnomBusq.trim()?pm02Fil:pm02Fil.slice().sort(function(a,b){return (b.ts||0)-(a.ts||0);}).slice(0,10)).map(function(o){
      var col=o.colorOT==='rojo'?'#C62828':o.colorOT==='azul'?'#1565C0':'#9ca3af';
      var esSuper=currentUser&&currentUser.rol==='super';
      var delBtn=esSuper?'<div style="display:flex;justify-content:flex-end;margin-top:6px">'
        +'<button class="btn btn-danger btn-sm" style="font-size:11px;padding:4px 10px;width:auto"'
        +' onclick="event.stopPropagation();kpiAnomEliminar(\''+o.id+'\')">'
        +'🗑️ Eliminar</button></div>':'';
      return '<div class="ot-card" style="border-left:4px solid '+col+';margin-bottom:6px">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start;cursor:pointer"'
        +' onclick="showDetalle(\''+o.id+'\')">'
        +'<div>'
        +'<div style="font-size:12px;font-weight:800">'+(o.linea||o.area||'—')+' · '+(o.componente||o.detalle||'—').substring(0,40)+'</div>'
        +'<div style="font-size:11px;color:var(--txt2);margin-top:2px">👤 '+(o.levantadoPor||'—')+' · Sem '+(o.semana||'—')+'</div>'
        +'</div>'
        +'<span class="badge badge-'+(o.estado||'abierta')+'">'+(o.estado||'abierta')+'</span>'
        +'</div>'
        +delBtn
        +'</div>';
    }).join('')+'</div>';

  showScreen('screen-ordenes');
}

function kpiAnomEliminar(id){
  eliminarOT(id);
  showKPIAnormalidades();
}

function kpiCardGrande(titulo, valor, color, sub){
  return '<div class="card" style="padding:20px;text-align:center;border-top:4px solid '+color+'">'
    +'<div style="font-size:2.2rem;font-weight:900;color:'+color+';line-height:1">'+valor+'</div>'
    +'<div style="font-size:.85rem;font-weight:700;color:#374151;margin-top:4px">'+titulo+'</div>'
    +(sub?'<div style="font-size:.75rem;color:#9ca3af;margin-top:3px">'+sub+'</div>':'')
    +'</div>';
}
