// ================================================================
// PM02 POR ASIGNAR — Admin gestiona anormalidades sin técnico
// ================================================================

function showPM02PorAsignar(){
  detalleBackScreen='screen-ordenes';
  // Por defecto mostrar sin asignar
  window._pm02AsigEstado='pendiente';
  window._pm02AsigPrio='';
  window._pm02AsigTec='';
  // Actualizar badge del botón
  var pend=ORDENES.filter(function(o){return o.pendienteAsignacion&&o.tipo==='PM02';}).length;
  var dBtn=document.getElementById('desc-pm02-asignar');
  var iBtn=document.getElementById('icon-pm02-asignar');
  if(dBtn) dBtn.textContent=pend>0?pend+' sin asignar':'Sin pendientes';
  if(iBtn) iBtn.innerHTML='📋'+(pend>0?'<span style="position:absolute;top:-4px;right:-8px;background:#dc2626;color:#fff;border-radius:50%;width:18px;height:18px;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center">'+pend+'</span>':'');

  _renderPM02Asignar();
  showScreen('screen-ordenes');
}

function _renderPM02Asignar(){
  var fDiv=document.getElementById('ordenes-filtros');
  var lDiv=document.getElementById('mis-ordenes-list');
  if(!window._pm02AsigEstado) window._pm02AsigEstado='todas';
  if(!window._pm02AsigPrio) window._pm02AsigPrio='';
  if(!window._pm02AsigTec) window._pm02AsigTec='';

  var tecsList=USERS.filter(function(u){
    return u.rol==='tecnico'||(u.rol==='admin'&&(u.nombre.toLowerCase().includes('jorge')||u.nombre.toLowerCase().includes('mauricio')));
  });

  var base=ORDENES.filter(function(o){
    if(o.tipo!=='PM02') return false;
    var r=o.rolLevantador||'';
    return r==='operador'||r==='lider'||r==='inspector_calidad'||r==='lider_calidad'||r==='administrativo'||r==='supply'||o.pendienteAsignacion===true;
  });

  var lista=base.filter(function(o){
    var est=window._pm02AsigEstado;
    var sinTec=!o.tecnicoAsignado||o.tecnicoAsignado==='';
    if(est==='pendiente' && (!sinTec||o.estado==='cerrada'||o.estado==='pre_cierre')) return false;
    if(est==='asignada' && (sinTec||o.estado==='cerrada'||o.estado==='pre_cierre')) return false;
    if(est==='por_aprobar' && o.estado!=='pre_cierre') return false;
    if(est==='cerrada' && o.estado!=='cerrada') return false;
    if(window._pm02AsigPrio && o.prioridad!==window._pm02AsigPrio) return false;
    if(window._pm02AsigTec && o.tecnicoAsignado!==window._pm02AsigTec) return false;
    return true;
  }).sort(function(a,b){return (b.ts||0)-(a.ts||0);});

  var totalPend=base.filter(function(o){var st=!o.tecnicoAsignado||o.tecnicoAsignado==='';return st&&o.estado!=='cerrada'&&o.estado!=='pre_cierre';}).length;
  var totalAsig=base.filter(function(o){var st=!o.tecnicoAsignado||o.tecnicoAsignado==='';return !st&&o.estado!=='cerrada'&&o.estado!=='pre_cierre';}).length;
  var totalCer=base.filter(function(o){return o.estado==='cerrada';}).length;

  var totalAprob=base.filter(function(o){return o.estado==='pre_cierre';}).length;
  var estBtns=['pendiente','asignada','todas','por_aprobar','cerrada'];
  var estLabels={'pendiente':'Sin asignar ('+totalPend+')','asignada':'Asignadas ('+totalAsig+')','todas':'Todas ('+base.length+')','por_aprobar':'Por aprobar ('+totalAprob+')','cerrada':'Cerradas ('+totalCer+')'};
  var estColors={'pendiente':'#dc2626','asignada':'#7c3aed','todas':'#374151','por_aprobar':'#f59e0b','cerrada':'#16a34a'};

  var tecOpts='<option value="">Todos los técnicos</option>'+tecsList.map(function(t){
    return '<option value="'+t.id+'"'+(window._pm02AsigTec===t.id?' selected':'')+'>'+t.nombre.split(' ')[0]+'</option>';
  }).join('');

  fDiv.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;flex-wrap:wrap;gap:6px">'
    +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;color:#7c3aed">📋 PM02 por Asignar</div>'
    +'<div style="display:flex;gap:6px">'
    +'<button onclick="showPM02ConsultaAsignadas()" style="padding:6px 12px;background:#1a3c5e;color:#fff;border:none;border-radius:8px;font-size:.8rem;font-weight:700;cursor:pointer">🔍 Consulta Asignadas</button>'
    +'<button onclick="showPM02PorValidar()" style="padding:6px 12px;background:#d97706;color:#fff;border:none;border-radius:8px;font-size:.8rem;font-weight:700;cursor:pointer">✅ Por Validar</button>'
    +'</div>'
    +'</div>'
    +'<div id="pm02-resumen-asignar"></div>';
  renderResumenPM02Asignar();

  // Panel carga técnicos
  var panelCarga='';
  if(currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super')){
    panelCarga=renderPanelCargaTecnicos();
  }
  lDiv.innerHTML=panelCarga+lista.map(function(o){
    var colCard=o.pendienteAsignacion?'#dc2626':o.colorOT==='azul'?'#1565C0':'#C62828';
    return '<div class="ot-card" style="border-left:4px solid '+colCard+';margin-bottom:8px">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:5px">'
      +'<div><div style="font-size:11px;color:'+colCard+';font-weight:700">'+o.id+'</div>'
      +'<div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800">'+(o.linea||o.area||'—')+'</div>'
      +'<div style="font-size:12px;color:var(--txt2)">'+(o.componente||o.detalle||'—').substring(0,50)+'</div>'
      +'</div>'
      +'<div style="display:flex;flex-direction:column;align-items:flex-end;gap:3px">'
      +'<span class="badge badge-'+(o.estado||'abierta')+'">'+( o.estado||'abierta')+'</span>'
      +(o.pendienteAsignacion?'<span class="badge" style="background:#dc2626;color:#fff;font-size:10px">Sin asignar</span>':'')
      +'</div></div>'
      +'<div style="font-size:11px;color:#6b7280;margin-bottom:8px">'
      +'👤 '+(o.levantadoPor||'—')+' · Prio '+(o.prioridad||'—')+' · Sem '+(o.semana||'—')
      +(o.conciliadoConNombre?' · 🤝 '+o.conciliadoConNombre:'')
      +(o.tecnicoAsignado?' · 👨‍🔧 '+(o.tecnicoNombre||'—'):'')
      +'</div>'
      +'<button onclick="abrirGestorPM02(\''+o.id+'\')" style="width:100%;padding:9px;background:#7c3aed;color:#fff;border:none;border-radius:8px;font-size:.85rem;font-weight:700;cursor:pointer">✏️ Ver / Editar / Asignar</button>'
      +'</div>';
  }).join('');
}

function abrirAsignarPM02(id){
  var o=ORDENES.find(function(x){return x.id===id;});
  if(!o) return;
  var modal=document.createElement('div');
  modal.id='modal-asignar-pm02';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';

  var tecOpts=USERS.filter(function(u){return u.rol==='tecnico';}).map(function(t){
    return '<option value="'+t.id+'"'+(o.tecnicoAsignado===t.id?' selected':'')+'>'+t.nombre+'</option>';
  }).join('');

  var semOpts=Array.from({length:26},function(_,i){
    var s=currentWeek()+i, a=currentYear();
    if(s>52){s-=52;a++;}
    return '<option value="'+s+'"'+(o.semanaResolucion===s?' selected':'')+'>'+(i===0?'Esta semana (Sem '+s+')':'Sem '+s+' / '+a)+'</option>';
  }).join('');

  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#1a3c5e;margin-bottom:4px">✏️ Asignar PM02</div>'
    +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">'+o.id+' · '+(o.linea||o.area||'—')+' · Prio '+(o.prioridad||'—')+'</div>'
    +(o.conciliadoConNombre?'<div style="background:#ede9fe;border-radius:8px;padding:8px 12px;margin-bottom:12px;font-size:.85rem;color:#7c3aed">🤝 Conciliado con: <strong>'+o.conciliadoConNombre+'</strong></div>':'')
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Técnico asignado *</label>'
    +'<select id="asig-tec" class="form-control" style="padding:10px"><option value="">-- Seleccionar técnico --</option>'+tecOpts+'</select></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Semana de resolución</label>'
    +'<select id="asig-sem" class="form-control" style="padding:10px">'+semOpts+'</select></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">💰 ¿Requiere inversión?</label>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="inv-si" onclick="pm02ToggleInv(true)" style="flex:1;padding:9px;border:2px solid '+(o.requiereInversion?'#d97706':'#e5e7eb')+';border-radius:8px;background:'+(o.requiereInversion?'#fef3c7':'#fff')+';font-weight:700;font-size:.85rem;cursor:pointer">💰 SI</button>'
    +'<button id="inv-no" onclick="pm02ToggleInv(false)" style="flex:1;padding:9px;border:2px solid '+(o.requiereInversion===false?'#6b7280':'#e5e7eb')+';border-radius:8px;background:'+(o.requiereInversion===false?'#f3f4f6':'#fff')+';font-weight:700;font-size:.85rem;cursor:pointer">NO</button>'
    +'</div></div>'
    +'<div id="inv-nota-wrap" style="margin-bottom:12px;display:'+(o.requiereInversion?'block':'none')+'">'
    +'<label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Descripción de la inversión</label>'
    +'<input type="text" id="inv-nota" class="form-control" placeholder="Ej: Motor reductor $15,000" value="'+(o.notaInversion||'')+'" style="padding:10px"></div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-asignar-pm02\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="guardarAsignacionPM02(\''+id+'\')" style="flex:2;padding:13px;background:#7c3aed;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">✅ Guardar Asignación</button>'
    +'</div></div>';
  document.body.appendChild(modal);
  window._pm02Inversion=o.requiereInversion||false;
}

function pm02ToggleInv(val){
  window._pm02Inversion=val;
  var si=document.getElementById('inv-si'),no=document.getElementById('inv-no');
  var wrap=document.getElementById('inv-nota-wrap');
  if(si){si.style.background=val?'#fef3c7':'#fff';si.style.borderColor=val?'#d97706':'#e5e7eb';}
  if(no){no.style.background=!val?'#f3f4f6':'#fff';no.style.borderColor=!val?'#6b7280':'#e5e7eb';}
  if(wrap) wrap.style.display=val?'block':'none';
}

function guardarAsignacionPM02(id){
  var o=ORDENES.find(function(x){return x.id===id;});
  if(!o) return;
  var tecSel=document.getElementById('asig-tec');
  var semSel=document.getElementById('asig-sem');
  var invNota=document.getElementById('inv-nota');
  if(!tecSel||!tecSel.value){showAlert('Selecciona un técnico','error');return;}
  var tObj=USERS.find(function(u){return u.id===tecSel.value;});
  o.tecnicoAsignado=tecSel.value;
  o.tecnicoNombre=tObj?tObj.nombre:'—';
  o.pendienteAsignacion=false;
  o.semanaResolucion=semSel?parseInt(semSel.value)||0:0;
  o.requiereInversion=window._pm02Inversion||false;
  o.notaInversion=window._pm02Inversion&&invNota?invNota.value.trim():'';
  o.asignadoPor=currentUser.nombre;
  o.asignadoTs=Date.now();
  saveDB('ordenes',ORDENES);
  supabaseStatePatch(o.id,{
    tecnico_asignado:o.tecnicoAsignado,
    tecnico_nombre:o.tecnicoNombre,
    pendiente_asignacion:false,
    semana_resolucion:o.semanaResolucion,
    requiere_inversion:o.requiereInversion,
    nota_inversion:o.notaInversion
  });
  var m=document.getElementById('modal-asignar-pm02');if(m)m.remove();
  showAlert('✅ PM02 asignada a '+o.tecnicoNombre);
  _renderPM02Asignar();
}
// ── FIN PM02 POR ASIGNAR ─────────────────────────────────────────

// ================================================================
// HISTORIAL CHECKLISTS
// ================================================================
var _chkHistFiltros = { año: 0, mes: 0, dia: '', soloRojos: false };

function showHistorialChecklist(tipoId) {
  detalleBackScreen = 'screen-checklist-menu';
  _chkHistFiltros.año = _chkHistFiltros.año || currentYear();
  _chkHistFiltros.tipoId = tipoId;
  _chkHistFiltros.soloRojos = false; // Por defecto mostrar todos

  var tipo = CHECKLIST_TIPOS.find(function(t){ return t.id === tipoId; });
  showScreen('screen-ordenes');

  // Mostrar cargando
  var lDiv = document.getElementById('mis-ordenes-list');
  var fDiv = document.getElementById('ordenes-filtros');
  if(fDiv) fDiv.innerHTML = '<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;color:'+(tipo?tipo.color:'#1a3c5e')+';margin-bottom:8px">📋 Historial — '+(tipo?tipo.icon+' '+tipo.label:'Check List')+'</div>';
  if(lDiv) lDiv.innerHTML = '<div style="text-align:center;padding:32px;color:#9ca3af">⏳ Cargando historial completo...</div>';

  // Cargar TODO de Supabase sin límite
  supaFetch('inspecciones','GET',null,'order=created_at.desc&limit=5000').then(function(rows){
    var totalSupa = rows ? rows.length : 0;
    if(rows && rows.length){
      // Merge con INSPECCIONES local sin duplicar
      rows.forEach(function(r){
        // Restaurar puntos desde puntos_detalle si existe
        if(r.puntos_detalle&&(!r.puntos||!r.puntos.length)){
          try{r.puntos=JSON.parse(r.puntos_detalle);}catch(e){}
        }
        // Normalize fields
        if(!r.tipo) r.tipo='inspeccion_turno';
        if(!r.momento&&r.momento_inspeccion) r.momento=r.momento_inspeccion;
        if(!INSPECCIONES.find(function(i){return i.id===r.id;})) INSPECCIONES.push(r);
        else{
          var idx2=INSPECCIONES.findIndex(function(i){return i.id===r.id;});
          if(idx2>=0&&r.puntos) INSPECCIONES[idx2].puntos=r.puntos;
        }
      });
      saveDB('inspecciones', INSPECCIONES);
    }
    console.log('Inspecciones Supabase:', totalSupa, '/ Local total:', INSPECCIONES.length);
    var base = INSPECCIONES.filter(function(i){
      // tipo puede ser 'inspeccion_turno' o momento_inspeccion puede ser 'inicio'/'medio'
      var tipo_i = (i.tipo || i.tipoId || '').toLowerCase();
      var momento_i = (i.momento || i.momento_inspeccion || '').toLowerCase();
      var t = tipo_i || momento_i;
      if(tipoId === 'inspeccion_turno'){
        return tipo_i === 'inspeccion_turno' || tipo_i === 'inspeccion' ||
               momento_i === 'inicio' || momento_i === 'medio' ||
               momento_i === 'inspeccion_turno' || t === '' || !t;
      }
      return t === tipoId || t.indexOf(tipoId.replace('_planta',''))>=0;
    }).filter(function(i){ return i.estado !== 'en_progreso'; });
    _renderHistorialChecklist(tipo, base);
  }).catch(function(){
    // Fallback a datos locales
    var base = INSPECCIONES.filter(function(i){
      // tipo puede ser 'inspeccion_turno' o momento_inspeccion puede ser 'inicio'/'medio'
      var tipo_i = (i.tipo || i.tipoId || '').toLowerCase();
      var momento_i = (i.momento || i.momento_inspeccion || '').toLowerCase();
      var t = tipo_i || momento_i;
      if(tipoId === 'inspeccion_turno'){
        return tipo_i === 'inspeccion_turno' || tipo_i === 'inspeccion' ||
               momento_i === 'inicio' || momento_i === 'medio' ||
               momento_i === 'inspeccion_turno' || t === '' || !t;
      }
      return t === tipoId || t.indexOf(tipoId.replace('_planta',''))>=0;
    }).filter(function(i){ return i.estado !== 'en_progreso'; });
    _renderHistorialChecklist(tipo, base);
  });
}

function _renderHistorialChecklist(tipo, base) {
  var f = _chkHistFiltros;
  var fDiv = document.getElementById('ordenes-filtros');
  var lDiv = document.getElementById('mis-ordenes-list');

  // Aplicar filtros
  var lista = base.filter(function(i) {
    var fecha = i.fecha || (i.tsCierre ? new Date(i.tsCierre).toISOString().split('T')[0] : '') || (i.ts ? new Date(i.ts).toISOString().split('T')[0] : '');
    if (!fecha) return true; // Si no hay fecha mostrar de todas formas
    var d = new Date(fecha + 'T12:00:00');
    if (f.año && d.getFullYear() !== f.año) return false;
    if (f.mes && d.getMonth() + 1 !== f.mes) return false;
    if (f.dia && fecha !== f.dia) return false;
    if (f.soloRojos && !(i.puntos_rojo > 0 || (i.puntos && i.puntos.some(function(p){ return p.estado === 'rojo'; })))) return false;
    return true;
  }).sort(function(a, b) {
    return (b.tsCierre || b.ts || 0) - (a.tsCierre || a.ts || 0);
  });

  // Contadores
  var conRojos = lista.filter(function(i){
    return i.puntos_rojo > 0 || (i.puntos && i.puntos.some(function(p){ return p.estado === 'rojo'; }));
  }).length;

  var añoOpts = [currentYear()-1, currentYear()].map(function(a){
    return '<option value="'+a+'"'+(f.año===a?' selected':'')+'>'+a+'</option>';
  }).join('');
  var meses = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  var mesOpts = '<option value="0">Todo mes</option>' + meses.map(function(m,i){
    return '<option value="'+(i+1)+'"'+(f.mes===(i+1)?' selected':'')+'>'+m+'</option>';
  }).join('');

  var tColor = tipo ? tipo.color : '#1a3c5e';
  var tLabel = tipo ? tipo.icon + ' ' + tipo.label : 'Check List';

  fDiv.innerHTML =
    '<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800;color:'+tColor+';margin-bottom:8px">📋 Historial — '+tLabel+'</div>'
    + '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px">'
    + '<select class="form-control" style="flex:1;min-width:60px;padding:7px;font-size:.82rem" onchange="_chkHistFiltros.año=parseInt(this.value)||currentYear();_chkHistFiltros.mes=0;_chkHistFiltros.dia=\'\';_renderHistorialChecklist(CHECKLIST_TIPOS.find(function(t){return t.id===_chkHistFiltros.tipoId;}),'+
    'INSPECCIONES.filter(function(i){var t=i.tipo||i.tipoId||i.momento||\'\';return _chkHistFiltros.tipoId===\'inspeccion_turno\'?(!t||t===\'\'||t===\'inspeccion_turno\'):t===_chkHistFiltros.tipoId;}).filter(function(i){return i.estado===\'cerrada\'||i.estado===\'completa\';}))">'
    + añoOpts + '</select>'
    + '<select class="form-control" style="flex:1;min-width:70px;padding:7px;font-size:.82rem" onchange="_chkHistFiltros.mes=parseInt(this.value)||0;_chkHistFiltros.dia=\'\';_renderHistorialChecklist(CHECKLIST_TIPOS.find(function(t){return t.id===_chkHistFiltros.tipoId;}),INSPECCIONES.filter(function(i){var t=i.tipo||i.tipoId||i.momento||\'\';return _chkHistFiltros.tipoId===\'inspeccion_turno\'?(!t||t===\'\'||t===\'inspeccion_turno\'):t===_chkHistFiltros.tipoId;}).filter(function(i){return i.estado===\'cerrada\'||i.estado===\'completa\';}))">'
    + mesOpts + '</select>'
    + '<input type="date" class="form-control" style="flex:2;min-width:120px;padding:7px;font-size:.82rem" value="'+( f.dia||'')+'" onchange="_chkHistFiltros.dia=this.value;_renderHistorialChecklist(CHECKLIST_TIPOS.find(function(t){return t.id===_chkHistFiltros.tipoId;}),INSPECCIONES.filter(function(i){var t=i.tipo||i.tipoId||i.momento||\'\';return _chkHistFiltros.tipoId===\'inspeccion_turno\'?(!t||t===\'\'||t===\'inspeccion_turno\'):t===_chkHistFiltros.tipoId;}).filter(function(i){return i.estado===\'cerrada\'||i.estado===\'completa\';}));">'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-bottom:6px;align-items:center">'
    + '<button onclick="_chkHistFiltros.soloRojos=!_chkHistFiltros.soloRojos;_renderHistorialChecklist(CHECKLIST_TIPOS.find(function(t){return t.id===_chkHistFiltros.tipoId;}),INSPECCIONES.filter(function(i){var t=i.tipo||i.tipoId||i.momento||\'\';return _chkHistFiltros.tipoId===\'inspeccion_turno\'?(!t||t===\'\'||t===\'inspeccion_turno\'):t===_chkHistFiltros.tipoId;}).filter(function(i){return i.estado===\'cerrada\'||i.estado===\'completa\';}));" style="padding:7px 14px;border:2px solid '+(f.soloRojos?'#dc2626':'#e5e7eb')+';border-radius:8px;background:'+(f.soloRojos?'#fee2e2':'#fff')+';font-size:.82rem;font-weight:700;color:'+(f.soloRojos?'#dc2626':'#374151')+';cursor:pointer">🔴 Solo con puntos fuera</button>'
    + '<span style="font-size:.78rem;color:#6b7280">'+lista.length+' registros · '+conRojos+' con puntos fuera</span>'
    + '</div>';

  if (!lista.length) {
    lDiv.innerHTML = '<div class="card text-center" style="padding:40px"><div style="font-size:48px">📋</div><div style="font-weight:700;margin-top:12px">Sin registros en este período</div></div>';
    return;
  }

  lDiv.innerHTML = lista.map(function(i) {
    var rojos = i.puntos ? i.puntos.filter(function(p){ return p.tipo!=='seccion' && p.estado === 'rojo'; }).length : (i.puntos_rojo||0);
    var verdes = i.puntos ? i.puntos.filter(function(p){ return p.tipo!=='seccion' && p.estado === 'verde'; }).length : (i.puntos_verde||0);
    var total = i.puntos ? i.puntos.filter(function(p){ return p.tipo!=='seccion'; }).length : (i.puntos_total || 0);
    var tieneRojos = rojos > 0;
    var fecha = i.fecha || (i.tsCierre ? new Date(i.tsCierre).toLocaleDateString('es-MX') : '—');
    var hora = i.tsCierre ? new Date(i.tsCierre).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}) : (i.horaFin || '—');
    var turno = i.turno ? 'T'+i.turno : '—';

    var puntosRojosHTML = '';
    if (tieneRojos && i.puntos) {
      var rojosDetalle = i.puntos.filter(function(p){ return p.estado === 'rojo'; });
      puntosRojosHTML = '<div style="background:#fee2e2;border-radius:8px;padding:8px 10px;margin-top:6px">'
        + '<div style="font-size:.72rem;font-weight:700;color:#dc2626;margin-bottom:4px">🔴 PUNTOS FUERA DE ESPECIFICACIÓN</div>'
        + rojosDetalle.map(function(p){
          return '<div style="font-size:.82rem;color:#7f1d1d;padding:2px 0;border-bottom:1px solid #fecaca">'
            + '• ' + (p.texto || p.nombre || p.id)
            + (p.comentario ? ' — <em>' + p.comentario + '</em>' : '')
            + '</div>';
        }).join('')
        + '</div>';
    }

    return '<div class="card" style="border-left:5px solid '+(tieneRojos?'#dc2626':tColor)+';margin-bottom:8px;padding:12px;background:'+(tieneRojos?'#fff9f9':'#fff')+'">'
      + '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">'
      + '<div>'
      + '<div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800">'+(i.tecnicoNombre||i.tecnico||'—')+'</div>'
      + '<div style="font-size:11px;color:#6b7280">📅 '+fecha+' · ⏰ '+hora+' · 🔄 Turno '+turno+'</div>'
      + '</div>'
      + '<div style="text-align:right">'
      + (tieneRojos ? '<span class="badge" style="background:#dc2626;color:#fff;font-size:11px;font-weight:800">🔴 '+rojos+' fuera</span>' : '<span class="badge" style="background:#16a34a;color:#fff;font-size:11px">✅ OK</span>')
      + '</div></div>'
      + '<div style="display:flex;gap:8px;font-size:.78rem;color:#6b7280;margin-top:4px">'
      + '<span>✅ '+verdes+' bien</span>'
      + '<span>🔴 '+rojos+' fuera</span>'
      + '<span>📋 '+total+' total</span>'
      + '</div>'
      + puntosRojosHTML
      + '</div>';
  }).join('');
}
// ── FIN HISTORIAL CHECKLISTS ─────────────────────────────────────

// ================================================================
// GESTIÓN DE PERSONAL — Horarios, Vacaciones, Incidencias
// ================================================================

// LFT: días de vacaciones por año de antigüedad
var VACACIONES_LFT = [0,12,14,16,18,20,22,22,22,22,22,22];
function diasVacLFT(años){
  if(años<=0) return 12;
  if(años>=11) return 22;
  return VACACIONES_LFT[años]||12;
}

var _gpTab='empleados'; // empleados | horarios | vacaciones | incidencias
var _gpEmpSelId=null;
var _gpMes=new Date().getMonth()+1;
var _gpAño=new Date().getFullYear();

function showGestionPersonal(){
  showScreen('screen-personal');
  var tabsDiv=document.getElementById('personal-tabs');
  var cont=document.getElementById('personal-content');
  if(!tabsDiv||!cont) return;
  var esTecnico=currentUser&&currentUser.rol==='tecnico';
  var tabs=[
    {id:'empleados',icon:'👤',label:esTecnico?'Mi Ficha':'Empleados'},
    {id:'horarios',icon:'📅',label:'Horarios'},
    {id:'vacaciones',icon:'🏖️',label:'Vacaciones'},
    {id:'incidencias',icon:'📋',label:'Incidencias'},
    {id:'contrasenas',icon:'🔑',label:'Contraseñas'}
  ];
  tabsDiv.innerHTML=tabs.map(function(t){
    var sel=_gpTab===t.id;
    return '<button onclick="_gpTab=\''+t.id+'\';showGestionPersonal()" style="padding:7px 12px;border-radius:8px;border:2px solid '+(sel?'#0891b2':'#e5e7eb')+';background:'+(sel?'#e0f7fa':'#fff')+';font-weight:700;font-size:.82rem;cursor:pointer;color:'+(sel?'#0891b2':'#374151')+'">'+t.icon+' '+t.label+'</button>';
  }).join('');
  if(_gpTab==='empleados') _renderEmpleados(cont);
  else if(_gpTab==='horarios') _renderHorarios(cont);
  else if(_gpTab==='vacaciones') _renderVacaciones(cont);
  else if(_gpTab==='incidencias') _renderIncidencias(cont);
  else if(_gpTab==='contrasenas') _renderContrasenas(cont);
}

// ── EMPLEADOS ────────────────────────────────────────────────────
function _renderEmpleados(lDiv){
  lDiv.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  var esTecnico=currentUser&&currentUser.rol==='tecnico';
  var esAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  var query=esTecnico?('usuario_id=eq.'+currentUser.id+'&order=nombre.asc'):'order=nombre.asc';
  supaFetch('empleados','GET',null,query).then(function(rows){
    var html='';
    if(esAdmin){
      html='<div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:10px">'
        +(currentUser.rol==='super'?'<button onclick="importarEmpleadosArchivo()" style="padding:8px 14px;background:#6d28d9;color:#fff;border:none;border-radius:8px;font-size:.85rem;font-weight:700;cursor:pointer">⬆️ Importar archivo</button>':'')
        +'<button onclick="abrirEditorEmpleado(null)" style="padding:8px 14px;background:#0891b2;color:#fff;border:none;border-radius:8px;font-size:.85rem;font-weight:700;cursor:pointer">+ Nuevo Empleado</button>'
        +'</div>';
    }
    if(!rows||!rows.length){
      html+='<div class="card text-center" style="padding:40px"><div style="font-size:48px">👤</div><div style="font-weight:700;margin-top:12px">'+(esTecnico?'No tienes ficha registrada':'Sin empleados registrados')+'</div></div>';
    } else {
      html+=rows.map(function(e){
        var años=e.antiguedad_años||0;
        var diasVac=diasVacLFT(años);
        return '<div class="card" style="margin-bottom:8px;padding:14px;border-left:4px solid '+(e.activo?'#0891b2':'#9ca3af')+'">'
          +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
          +'<div>'
          +'<div style="font-family:Nunito,sans-serif;font-size:15px;font-weight:800">'+(e.activo?'':'<span style="color:#9ca3af">[Baja] </span>')+e.nombre+'</div>'
          +'<div style="font-size:12px;color:var(--txt2);margin-top:2px">Nº '+(e.numero_empleado||'—')+' · Antigüedad: '+años+' año(s) · Vacaciones: '+diasVac+' días/año</div>'
          +(e.puesto?'<div style="font-size:11px;color:#6b7280;margin-top:1px">'+e.puesto+'</div>':'')
          +(e.fecha_ingreso?'<div style="font-size:11px;color:#9ca3af">Ingreso: '+new Date(e.fecha_ingreso).toLocaleDateString('es-MX')+'</div>':'')
          +'</div>'
          +(esAdmin?'<div style="display:flex;gap:6px">'
            +'<button onclick="abrirEditorEmpleado(\''+e.id+'\')" style="padding:6px 10px;background:#f3f4f6;border:none;border-radius:7px;font-size:.8rem;cursor:pointer">✏️</button>'
            +(e.activo?'<button onclick="bajaEmpleado(\''+e.id+'\')" style="padding:6px 10px;background:#fee2e2;border:none;border-radius:7px;font-size:.8rem;color:#dc2626;cursor:pointer">Dar baja</button>':'')
            +'</div>':'')
          +'</div>'
          +'</div>';
      }).join('');
    }
    lDiv.innerHTML=html;
  });
}

function abrirEditorEmpleado(id){
  supaFetch('empleados','GET',null,'order=nombre.asc').then(function(rows){
    var e=id?(rows||[]).find(function(r){return r.id===id;}):null;
    // Ligar con usuario técnico
    var tecOpts='<option value="">Sin ligar a usuario</option>'+USERS.filter(function(u){return u.rol==='tecnico';}).map(function(u){
      return '<option value="'+u.id+'"'+(e&&e.usuario_id===u.id?' selected':'')+'>'+u.nombre+'</option>';
    }).join('');
    var modal=document.createElement('div');
    modal.id='modal-editor-emp';
    modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;overflow-y:auto;padding:16px;box-sizing:border-box';
    modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:20px;max-width:500px;margin:auto;box-sizing:border-box">'
      +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#0891b2;margin-bottom:16px">'+(e?'✏️ Editar Empleado':'👤 Nuevo Empleado')+'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">'
      +'<div style="grid-column:1/-1"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Nombre completo *</label>'
      +'<input type="text" id="emp-nombre" class="form-control" value="'+(e?e.nombre:'')+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Número de empleado</label>'
      +'<input type="text" id="emp-num" class="form-control" value="'+(e?e.numero_empleado||'':'')+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Fecha de ingreso</label>'
      +'<input type="date" id="emp-ingreso" class="form-control" value="'+(e?e.fecha_ingreso||'':'')+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Años de antigüedad</label>'
      +'<input type="number" id="emp-ant" class="form-control" min="0" max="40" value="'+(e?e.antiguedad_años||0:0)+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Turno actual</label>'
      +'<select id="emp-turno" class="form-control" style="padding:10px">'
      +'<option value="1"'+(e&&e.turno_actual===1?' selected':'')+'>Turno 1 (6:30-14:30)</option>'
      +'<option value="2"'+(e&&e.turno_actual===2?' selected':'')+'>Turno 2 (14:30-22:30)</option>'
      +'<option value="3"'+(e&&e.turno_actual===3?' selected':'')+'>Turno 3 (22:30-6:30)</option>'
      +'</select></div>'
      +'<div style="grid-column:1/-1"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Ligar a usuario de la app</label>'
      +'<select id="emp-usuario" class="form-control" style="padding:10px">'+tecOpts+'</select></div>'
      +'</div>'
      +'<div style="background:#f0f7ff;border-radius:8px;padding:10px;margin-bottom:16px;font-size:.82rem;color:#0369a1">'
      +'📋 Vacaciones por LFT según antigüedad: <strong id="emp-vac-calc">'+diasVacLFT(e?e.antiguedad_años||0:0)+' días/año</strong>'
      +'</div>'
      +'<div style="display:flex;gap:10px">'
      +'<button onclick="var m=document.getElementById(\'modal-editor-emp\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
      +'<button onclick="guardarEmpleado(\''+( id||'')+'\' )" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
      +'</div></div>';
    document.body.appendChild(modal);
    // Actualizar días LFT en tiempo real
    document.getElementById('emp-ant').addEventListener('input',function(){
      var el=document.getElementById('emp-vac-calc');
      if(el) el.textContent=diasVacLFT(parseInt(this.value)||0)+' días/año';
    });
  });
}

function guardarEmpleado(id){
  var nombre=document.getElementById('emp-nombre').value.trim();
  if(!nombre){showAlert('El nombre es obligatorio','error');return;}
  var payload={
    nombre:nombre,
    numero_empleado:document.getElementById('emp-num').value.trim()||null,
    fecha_ingreso:document.getElementById('emp-ingreso').value||null,
    antiguedad_años:parseInt(document.getElementById('emp-ant').value)||0,
    turno_actual:parseInt(document.getElementById('emp-turno').value)||1,
    usuario_id:document.getElementById('emp-usuario').value||null,
    activo:true
  };
  var url=SUPA_URL+'/rest/v1/empleados';
  var method='POST';
  if(id){url+='?id=eq.'+id;method='PATCH';}
  fetch(url,{method:method,headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=representation'},body:JSON.stringify(payload)})
    .then(function(r){
      if(r.ok){var m=document.getElementById('modal-editor-emp');if(m)m.remove();showAlert('✅ Empleado guardado');showGestionPersonal();}
      else r.text().then(function(t){showAlert('⚠️ Error: '+t.substring(0,80),'error');});
    });
}

function bajaEmpleado(id){
  if(!confirm('¿Dar de baja a este empleado? Conservará su historial.')) return;
  fetch(SUPA_URL+'/rest/v1/empleados?id=eq.'+id,{method:'PATCH',headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json'},body:JSON.stringify({activo:false})})
    .then(function(){showAlert('✅ Empleado dado de baja');showGestionPersonal();});
}

