function _renderHorarios(lDiv){
  var esAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  var meses=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  var mesOpts=meses.map(function(m,i){return '<option value="'+(i+1)+'"'+(_gpMes===(i+1)?' selected':'')+'>'+m+'</option>';}).join('');
  var añoOpts=[_gpAño-1,_gpAño,_gpAño+1].map(function(a){return '<option value="'+a+'"'+(_gpAño===a?' selected':'')+'>'+a+'</option>';}).join('');

  // Leer datos guardados en localStorage (key: hor_mes_año)
  var storageKey='hor_'+_gpMes+'_'+_gpAño;
  var savedData={};
  try{ savedData=JSON.parse(localStorage.getItem(storageKey)||'{}'); }catch(e){}

  // Si no hay datos guardados, usar los del Excel embebido
  var empIds=Object.keys(_HORARIOS_EXCEL);
  if(!Object.keys(savedData).length){
    empIds.forEach(function(eid){
      var mData=_HORARIOS_EXCEL[eid]||{};
      var dData=mData[_gpMes]||mData[String(_gpMes)]||{};
      if(Object.keys(dData).length) savedData[eid]=dData;
    });
  }

  var diasMes=new Date(_gpAño,_gpMes,0).getDate();
  var diasSem=['D','L','M','X','J','V','S'];
  var turnoColor={'1':'#16a34a','2':'#d97706','3':'#dc2626','D':'#9ca3af','I':'#7c3aed','V':'#0891b2','P':'#f59e0b'};
  var turnoBg={'1':'#dcfce7','2':'#fef3c7','3':'#fee2e2','D':'#f3f4f6','I':'#ede9fe','V':'#e0f7fa','P':'#fffbeb'};

  // Cabecera días
  var headerDias='<tr><th style="position:sticky;left:0;background:#1a3c5e;z-index:2;padding:4px 8px;font-size:.7rem;color:#fff;white-space:nowrap">Técnico</th>';
  for(var d=1;d<=diasMes;d++){
    var dow=new Date(_gpAño+'-'+String(_gpMes).padStart(2,'0')+'-'+String(d).padStart(2,'0')+'T12:00:00').getDay();
    var esFS=dow===0||dow===6;
    headerDias+='<th style="background:'+(esFS?'#374151':'#1a3c5e')+';padding:2px;font-size:.6rem;font-weight:700;color:#fff;text-align:center;min-width:28px">'
      +'<div>'+d+'</div><div style="opacity:.8">'+diasSem[dow]+'</div></th>';
  }
  headerDias+='</tr>';

  // Lista de técnicos = los del Excel + los de empleados en Supabase
  var EMPLEADOS_LISTA=[
    {id:'emp_2196',nombre:'César'},
    {id:'emp_2055',nombre:'Marco'},
    {id:'emp_1923',nombre:'Ángel'},
    {id:'emp_2064',nombre:'Alan'},
    {id:'emp_1105',nombre:'Uriel'},
    {id:'emp_1980',nombre:'Anthon'},
    {id:'emp_804', nombre:'Lisandro'},
    {id:'emp_461', nombre:'Eduardo'},
  ];

  var filas=EMPLEADOS_LISTA.map(function(e){
    var diasEmp=savedData[e.id]||{};
    var fila='<tr><td style="position:sticky;left:0;background:#fff;z-index:1;padding:4px 8px;font-size:.72rem;font-weight:800;white-space:nowrap;border-bottom:1px solid #e5e7eb">'+e.nombre+'</td>';
    for(var d=1;d<=diasMes;d++){
      var val=diasEmp[d]||diasEmp[String(d)]||'';
      var bg=turnoBg[val]||'#fff';
      var col=turnoColor[val]||'#d1d5db';
      if(esAdmin){
        fila+='<td style="padding:1px;border-bottom:1px solid #e5e7eb;min-width:28px">'
          +'<select data-emp="'+e.id+'" data-dia="'+d+'" onchange="horSetVal(this)" onkeydown="horNavegar(this,event)" style="width:28px;height:28px;border:none;background:'+bg+';color:'+col+';font-size:.65rem;font-weight:800;text-align:center;cursor:pointer;padding:0">'
          +'<option value="">-</option>'
          +'<option value="1"'+(val==='1'?' selected':'')+'>1</option>'
          +'<option value="2"'+(val==='2'?' selected':'')+'>2</option>'
          +'<option value="3"'+(val==='3'?' selected':'')+'>3</option>'
          +'<option value="D"'+(val==='D'?' selected':'')+'>D</option>'
          +'<option value="I"'+(val==='I'?' selected':'')+'>I</option>'
          +'<option value="V"'+(val==='V'?' selected':'')+'>V</option>'
          +'<option value="P"'+(val==='P'?' selected':'')+'>P</option>'
          +'</select></td>';
      } else {
        fila+='<td style="background:'+bg+';text-align:center;font-size:.65rem;font-weight:800;color:'+col+';padding:3px 2px;border-bottom:1px solid #e5e7eb;min-width:28px">'+(val||'')+'</td>';
      }
    }
    return fila+'</tr>';
  }).join('');

  var leyenda='<div style="display:flex;gap:6px;flex-wrap:wrap;font-size:.72rem;margin-bottom:8px">'
    +'<span style="background:#dcfce7;color:#16a34a;padding:2px 8px;border-radius:4px;font-weight:700">1=T1</span>'
    +'<span style="background:#fef3c7;color:#d97706;padding:2px 8px;border-radius:4px;font-weight:700">2=T2</span>'
    +'<span style="background:#fee2e2;color:#dc2626;padding:2px 8px;border-radius:4px;font-weight:700">3=T3</span>'
    +'<span style="background:#f3f4f6;color:#9ca3af;padding:2px 8px;border-radius:4px;font-weight:700">D=Desc</span>'
    +'<span style="background:#ede9fe;color:#7c3aed;padding:2px 8px;border-radius:4px;font-weight:700">I=Inc</span>'
    +'<span style="background:#e0f7fa;color:#0891b2;padding:2px 8px;border-radius:4px;font-weight:700">V=Vac</span>'
    +'<span style="background:#fffbeb;color:#f59e0b;padding:2px 8px;border-radius:4px;font-weight:700">P=Permiso</span>'
    +(esAdmin?'<button onclick="horGuardar()" style="margin-left:auto;padding:2px 12px;background:#1a3c5e;color:#fff;border:none;border-radius:6px;font-size:.72rem;font-weight:700;cursor:pointer">💾 Guardar</button>':'')
    +'</div>';

  var selHTML='<div style="display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap">'
    +'<select class="form-control" style="flex:1;padding:8px" onchange="_gpMes=parseInt(this.value);_renderHorarios(document.getElementById(\'personal-content\'))">'+mesOpts+'</select>'
    +'<select class="form-control" style="flex:1;padding:8px" onchange="_gpAño=parseInt(this.value);_renderHorarios(document.getElementById(\'personal-content\'))">'+añoOpts+'</select>'
    +'</div>';

  lDiv.innerHTML=selHTML+leyenda
    +'<div style="overflow-x:auto;-webkit-overflow-scrolling:touch">'
    +'<table style="border-collapse:collapse;width:100%">'
    +'<thead>'+headerDias+'</thead>'
    +'<tbody>'+filas+'</tbody>'
    +'</table></div>';

  window._horStorageKey=storageKey;
  window._horData=savedData;
}

function horSetVal(sel){
  var emp=sel.getAttribute('data-emp');
  var dia=sel.getAttribute('data-dia');
  if(!window._horData[emp]) window._horData[emp]={};
  window._horData[emp][dia]=sel.value;
  var turnoColor={'1':'#16a34a','2':'#d97706','3':'#dc2626','D':'#9ca3af','I':'#7c3aed','V':'#0891b2','P':'#f59e0b'};
  var turnoBg={'1':'#dcfce7','2':'#fef3c7','3':'#fee2e2','D':'#f3f4f6','I':'#ede9fe','V':'#e0f7fa','P':'#fffbeb'};
  sel.style.background=turnoBg[sel.value]||'#fff';
  sel.style.color=turnoColor[sel.value]||'#d1d5db';
}

function horNavegar(sel, e){
  // Navegación con teclado entre celdas del grid
  var emp=sel.getAttribute('data-emp');
  var dia=parseInt(sel.getAttribute('data-dia'));
  var empIds=['emp_2196','emp_2055','emp_1923','emp_2064','emp_1105','emp_1980','emp_804','emp_461'];
  var empIdx=empIds.indexOf(emp);
  var diasMes=new Date(_gpAño,_gpMes,0).getDate();

  var nextEmp=emp, nextDia=dia;

  if(e.key==='ArrowRight'||e.key==='Tab'){
    e.preventDefault();
    if(dia<diasMes){ nextDia=dia+1; }
    else if(empIdx<empIds.length-1){ nextEmp=empIds[empIdx+1]; nextDia=1; }
  } else if(e.key==='ArrowLeft'){
    e.preventDefault();
    if(dia>1){ nextDia=dia-1; }
    else if(empIdx>0){ nextEmp=empIds[empIdx-1]; nextDia=diasMes; }
  } else if(e.key==='ArrowDown'||e.key==='Enter'){
    e.preventDefault();
    if(empIdx<empIds.length-1){ nextEmp=empIds[empIdx+1]; }
  } else if(e.key==='ArrowUp'){
    e.preventDefault();
    if(empIdx>0){ nextEmp=empIds[empIdx-1]; }
  } else if(e.key==='1'||e.key==='2'||e.key==='3'){
    sel.value=e.key; horSetVal(sel); e.preventDefault();
    // Avanzar automáticamente al siguiente día
    if(dia<diasMes){ nextDia=dia+1; }
    else if(empIdx<empIds.length-1){ nextEmp=empIds[empIdx+1]; nextDia=1; }
  } else if(e.key==='d'||e.key==='D'){
    sel.value='D'; horSetVal(sel); e.preventDefault();
    if(dia<diasMes){ nextDia=dia+1; }
  } else if(e.key==='i'||e.key==='I'){
    sel.value='I'; horSetVal(sel); e.preventDefault();
    if(dia<diasMes){ nextDia=dia+1; }
  } else if(e.key==='v'||e.key==='V'){
    sel.value='V'; horSetVal(sel); e.preventDefault();
    if(dia<diasMes){ nextDia=dia+1; }
  } else if(e.key==='p'||e.key==='P'){
    sel.value='P'; horSetVal(sel); e.preventDefault();
    if(dia<diasMes){ nextDia=dia+1; }
  } else { return; }

  var next=document.querySelector('[data-emp="'+nextEmp+'"][data-dia="'+nextDia+'"]');
  if(next) next.focus();
}

function horGuardar(){
  try{
    localStorage.setItem(window._horStorageKey, JSON.stringify(window._horData));
    showAlert('✅ Horario guardado');
  }catch(e){
    showAlert('Error al guardar','error');
  }
}


function editarHorarioEmp(empId,mes,año){
  var modal=document.createElement('div');
  modal.id='modal-horario-emp';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;overflow-y:auto;padding:16px;box-sizing:border-box';
  modal.innerHTML='<div style="background:#fff;border-radius:16px;padding:20px;max-width:500px;margin:auto">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#0891b2;margin-bottom:16px">📅 Horario del Mes</div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Turno de inicio del mes</label>'
    +'<select id="hor-turno" class="form-control" style="padding:10px">'
    +'<option value="1">Turno 1 (6:30-14:30)</option>'
    +'<option value="2">Turno 2 (14:30-22:30)</option>'
    +'<option value="3">Turno 3 (22:30-6:30)</option>'
    +'</select></div>'
    +'<div style="margin-bottom:12px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Día de descanso semanal</label>'
    +'<select id="hor-descanso" class="form-control" style="padding:10px">'
    +'<option value="1">Lunes</option><option value="2">Martes</option><option value="3">Miércoles</option>'
    +'<option value="4">Jueves</option><option value="5">Viernes</option><option value="6">Sábado</option>'
    +'<option value="7" selected>Domingo</option>'
    +'</select></div>'
    +'<div style="background:#f0f7ff;border-radius:8px;padding:10px;margin-bottom:16px;font-size:.82rem;color:#0369a1">'
    +'ℹ️ El sistema calculará automáticamente 6 días laborados por 1 de descanso con rotación semanal de turno.'
    +'</div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-horario-emp\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="guardarHorarioEmp(\''+empId+'\','+mes+','+año+')" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function guardarHorarioEmp(empId,mes,año){
  var turno=parseInt(document.getElementById('hor-turno').value)||1;
  var descanso=parseInt(document.getElementById('hor-descanso').value)||7;
  var payload={empleado_id:empId,mes:mes,anio:año,turno_inicio:turno,dia_descanso:descanso};
  fetch(SUPA_URL+'/rest/v1/horarios_empleado',{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=representation'},
    body:JSON.stringify(payload)
  }).then(function(r){
    if(r.ok){var m=document.getElementById('modal-horario-emp');if(m)m.remove();showAlert('✅ Horario guardado');_renderHorarios(document.getElementById('personal-content'));}
    else r.text().then(function(t){showAlert('⚠️ '+t.substring(0,80),'error');});
  });
}

// ── VACACIONES ───────────────────────────────────────────────────
function _renderVacaciones(lDiv){
  lDiv.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  var esTecnico=currentUser&&currentUser.rol==='tecnico';
  var esAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  var añoOpts=[_gpAño-1,_gpAño,_gpAño+1].map(function(a){return '<option value="'+a+'"'+(_gpAño===a?' selected':'')+'>'+a+'</option>';}).join('');
  var selHTML='<div style="display:flex;gap:8px;align-items:center;margin-bottom:12px">'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151">Período:</label>'
    +'<select class="form-control" style="flex:1;padding:8px" onchange="_gpAño=parseInt(this.value);_renderVacaciones(document.getElementById(\'personal-content\'))">'+añoOpts+'</select>'
    +'</div>';

  var empQuery=esTecnico?('activo=eq.true&usuario_id=eq.'+currentUser.id+'&order=nombre.asc'):'activo=eq.true&order=nombre.asc';
  Promise.all([
    supaFetch('empleados','GET',null,empQuery),
    supaFetch('vacaciones','GET',null,'año=eq.'+_gpAño)
  ]).then(function(results){
    var empleados=results[0]||[];
    var vacRows=results[1]||[];
    if(!empleados.length){
      lDiv.innerHTML=selHTML+'<div class="card text-center" style="padding:30px">Sin empleados registrados.</div>';
      return;
    }
    var html=selHTML;
    html+=empleados.map(function(e){
      var vac=vacRows.find(function(v){return v.empleado_id===e.id;})||{dias_correspondientes:diasVacLFT(e.antiguedad_años||0),dias_tomados:0};
      var saldo=(vac.dias_correspondientes||0)-(vac.dias_tomados||0);
      var pct=vac.dias_correspondientes>0?Math.round((vac.dias_tomados/vac.dias_correspondientes)*100):0;
      var col=saldo<=0?'#dc2626':saldo<=3?'#d97706':'#16a34a';
      return '<div class="card" style="margin-bottom:10px;padding:14px;border-left:4px solid '+col+'">'
        +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">'
        +'<div>'
        +'<div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800">'+e.nombre+'</div>'
        +'<div style="font-size:.75rem;color:#6b7280">Antigüedad: '+(e.antiguedad_años||0)+' año(s) · LFT: '+diasVacLFT(e.antiguedad_años||0)+' días/año</div>'
        +'</div>'
        +(esAdmin?'<div style="display:flex;gap:6px">'
          +'<button onclick="abrirAjusteVacaciones(\''+e.id+'\',\''+e.nombre.replace(/'/g,"\\'")+'\',' +_gpAño+')" style="padding:6px 10px;background:#f3f4f6;border:none;border-radius:7px;font-size:.78rem;font-weight:700;cursor:pointer">✏️ Ajustar</button>'
          +'<button onclick="abrirRegistroVacaciones(\''+e.id+'\',\''+e.nombre.replace(/'/g,"\\'")+'\',' +_gpAño+')" style="padding:6px 10px;background:#e0f7fa;border:none;border-radius:7px;font-size:.78rem;font-weight:700;color:#0891b2;cursor:pointer">+ Registrar</button>'
          +'</div>':'')
        +'</div>'
        +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:8px">'
        +'<div style="text-align:center"><div style="font-size:1.4rem;font-weight:900;color:#0891b2">'+(vac.dias_correspondientes||0)+'</div><div style="font-size:.7rem;color:#6b7280">Correspondientes</div></div>'
        +'<div style="text-align:center"><div style="font-size:1.4rem;font-weight:900;color:#d97706">'+(vac.dias_tomados||0)+'</div><div style="font-size:.7rem;color:#6b7280">Tomados</div></div>'
        +'<div style="text-align:center"><div style="font-size:1.4rem;font-weight:900;color:'+col+'">'+saldo+'</div><div style="font-size:.7rem;color:#6b7280">Saldo</div></div>'
        +'</div>'
        +'<div style="background:#f3f4f6;border-radius:6px;height:8px;overflow:hidden">'
        +'<div style="width:'+Math.min(pct,100)+'%;height:100%;background:'+col+';border-radius:6px"></div>'
        +'</div></div>';
    }).join('');
    lDiv.innerHTML=html;
  });
}

function abrirAjusteVacaciones(empId,empNombre,año){
  // Cargar valores actuales primero
  supaFetch('vacaciones','GET',null,'empleado_id=eq.'+empId+'&año=eq.'+año+'&limit=1').then(function(rows){
    var v=rows&&rows[0]?rows[0]:{dias_correspondientes:0,dias_tomados:0};
    var modal=document.createElement('div');
    modal.id='modal-ajuste-vac';
    modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
    modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
      +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#0891b2;margin-bottom:4px">✏️ Ajustar Vacaciones</div>'
      +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">'+empNombre+' · '+año+'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:16px">'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Correspondientes</label>'
      +'<input type="number" id="ajvac-corr" class="form-control" min="0" value="'+(v.dias_correspondientes||0)+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Tomados</label>'
      +'<input type="number" id="ajvac-tom" class="form-control" min="0" value="'+(v.dias_tomados||0)+'" style="padding:10px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Saldo</label>'
      +'<input type="number" id="ajvac-saldo" class="form-control" min="0" value="'+((v.dias_correspondientes||0)-(v.dias_tomados||0))+'" style="padding:10px;background:#f3f4f6" readonly></div>'
      +'</div>'
      +'<div style="display:flex;gap:10px">'
      +'<button onclick="var m=document.getElementById(\'modal-ajuste-vac\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
      +'<button onclick="guardarAjusteVacaciones(\''+empId+'\','+año+')" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar ajuste</button>'
      +'</div></div>';
    document.body.appendChild(modal);
    // Actualizar saldo en tiempo real
    ['ajvac-corr','ajvac-tom'].forEach(function(id){
      document.getElementById(id).addEventListener('input',function(){
        var c=parseInt(document.getElementById('ajvac-corr').value)||0;
        var t=parseInt(document.getElementById('ajvac-tom').value)||0;
        document.getElementById('ajvac-saldo').value=c-t;
      });
    });
  });
}

function guardarAjusteVacaciones(empId,año){
  var corr=parseInt(document.getElementById('ajvac-corr').value)||0;
  var tom=parseInt(document.getElementById('ajvac-tom').value)||0;
  fetch(SUPA_URL+'/rest/v1/vacaciones',{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=representation'},
    body:JSON.stringify({empleado_id:empId,año:año,dias_correspondientes:corr,dias_tomados:tom})
  }).then(function(r){
    if(r.ok){var m=document.getElementById('modal-ajuste-vac');if(m)m.remove();showAlert('✅ Vacaciones ajustadas');_renderVacaciones(document.getElementById('personal-content'));}
    else r.text().then(function(t){showAlert('⚠️ '+t.substring(0,80),'error');});
  });
}

function abrirRegistroVacaciones(empId,empNombre,año){
  var modal=document.createElement('div');
  modal.id='modal-vac';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#0891b2;margin-bottom:4px">🏖️ Vacaciones</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">'+empNombre+' · '+año+'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">'
    +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Días correspondientes</label>'
    +'<input type="number" id="vac-dias-corr" class="form-control" min="0" value="12" style="padding:10px"></div>'
    +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Días a descontar</label>'
    +'<input type="number" id="vac-dias-tomar" class="form-control" min="0" value="0" style="padding:10px"></div>'
    +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Fecha inicio</label>'
    +'<input type="date" id="vac-inicio" class="form-control" style="padding:10px"></div>'
    +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Fecha fin</label>'
    +'<input type="date" id="vac-fin" class="form-control" style="padding:10px"></div>'
    +'</div>'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-vac\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="guardarVacaciones(\''+empId+'\','+año+')" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

function guardarVacaciones(empId,año){
  var corr=parseInt(document.getElementById('vac-dias-corr').value)||0;
  var tomar=parseInt(document.getElementById('vac-dias-tomar').value)||0;
  var inicio=document.getElementById('vac-inicio').value;
  var fin=document.getElementById('vac-fin').value;
  // Upsert vacaciones del año
  fetch(SUPA_URL+'/rest/v1/vacaciones',{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=representation'},
    body:JSON.stringify({empleado_id:empId,año:año,dias_correspondientes:corr,dias_tomados:tomar,fecha_inicio:inicio||null,fecha_fin:fin||null})
  }).then(function(r){
    if(r.ok){var m=document.getElementById('modal-vac');if(m)m.remove();showAlert('✅ Vacaciones guardadas');_renderVacaciones(document.getElementById('personal-content'));}
    else r.text().then(function(t){showAlert('⚠️ '+t.substring(0,80),'error');});
  });
}

// ── INCIDENCIAS ──────────────────────────────────────────────────
function _renderIncidencias(lDiv){
  lDiv.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  var esTecnico=currentUser&&currentUser.rol==='tecnico';
  var esAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  var meses=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  var mesOpts=meses.map(function(m,i){return '<option value="'+(i+1)+'"'+(_gpMes===(i+1)?' selected':'')+'>'+m+'</option>';}).join('');
  var añoOpts=[_gpAño-1,_gpAño,_gpAño+1].map(function(a){return '<option value="'+a+'"'+(_gpAño===a?' selected':'')+'>'+a+'</option>';}).join('');
  var selHTML='<div style="display:flex;gap:6px;margin-bottom:12px">'
    +'<select class="form-control" style="flex:1;padding:7px;font-size:.82rem" onchange="_gpMes=parseInt(this.value);_renderIncidencias(document.getElementById(\'personal-content\'))">'+mesOpts+'</select>'
    +'<select class="form-control" style="flex:1;padding:7px;font-size:.82rem" onchange="_gpAño=parseInt(this.value);_renderIncidencias(document.getElementById(\'personal-content\'))">'+añoOpts+'</select>'
    +(esAdmin?'<button onclick="abrirRegistroIncidencia(null)" style="padding:7px 12px;background:#0891b2;color:#fff;border:none;border-radius:8px;font-size:.82rem;font-weight:700;cursor:pointer">+ Nueva</button>':'')
    +'</div>';

  var empQuery=esTecnico?('activo=eq.true&usuario_id=eq.'+currentUser.id+'&order=nombre.asc'):'activo=eq.true&order=nombre.asc';
  Promise.all([
    supaFetch('empleados','GET',null,empQuery),
    supaFetch('incidencias','GET',null,'order=fecha.desc&limit=200')
  ]).then(function(results){
    var empleados=results[0]||[];
    var todas=results[1]||[];
    // Filtrar por mes/año
    var lista=todas.filter(function(i){
      if(!i.fecha) return false;
      var d=new Date(i.fecha+'T12:00:00');
      return d.getMonth()+1===_gpMes&&d.getFullYear()===_gpAño;
    });
    var tipoColor={permiso_con_goce:'#16a34a',permiso_sin_goce:'#d97706',falta_justificada:'#f59e0b',falta_injustificada:'#dc2626',retardo:'#0891b2',vacaciones:'#7c3aed'};
    var tipoLabel={permiso_con_goce:'Permiso c/goce',permiso_sin_goce:'Permiso s/goce',falta_justificada:'Falta justificada',falta_injustificada:'Falta injustificada',retardo:'Retardo',vacaciones:'Vacaciones'};
    var html=selHTML;
    if(!lista.length){
      html+='<div class="card text-center" style="padding:30px"><div style="font-size:40px">✅</div><div style="font-weight:700;margin-top:8px">Sin incidencias en este período</div></div>';
    } else {
      html+=lista.map(function(i){
        var emp=empleados.find(function(e){return e.id===i.empleado_id;})||{nombre:'—'};
        var col=tipoColor[i.tipo]||'#9ca3af';
        var lbl=tipoLabel[i.tipo]||i.tipo;
        return '<div class="card" style="border-left:4px solid '+col+';margin-bottom:8px;padding:12px">'
          +'<div style="display:flex;justify-content:space-between;align-items:flex-start">'
          +'<div>'
          +'<div style="font-family:Nunito,sans-serif;font-size:14px;font-weight:800">'+emp.nombre+'</div>'
          +'<div style="margin-top:4px"><span style="background:'+col+';color:#fff;border-radius:12px;padding:2px 10px;font-size:.78rem;font-weight:700">'+lbl+'</span></div>'
          +'<div style="font-size:12px;color:var(--txt2);margin-top:4px">📅 '+i.fecha+(i.fecha_fin&&i.fecha_fin!==i.fecha?' → '+i.fecha_fin:'')+'</div>'
          +(i.motivo?'<div style="font-size:11px;color:#6b7280;margin-top:2px">'+i.motivo+'</div>':'')
          +'</div>'
          +'<span style="font-size:1.2rem;font-weight:900;color:'+col+'">'+(i.dias||1)+' día(s)</span>'
          +'</div></div>';
      }).join('');
    }
    lDiv.innerHTML=html;
  });
}

function abrirRegistroIncidencia(empId){
  supaFetch('empleados','GET',null,'activo=eq.true&order=nombre.asc').then(function(empleados){
    var modal=document.createElement('div');
    modal.id='modal-incidencia';
    modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
    var empOpts=(empleados||[]).map(function(e){return '<option value="'+e.id+'"'+(empId===e.id?' selected':'')+'>'+e.nombre+'</option>';}).join('');
    modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
      +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#0891b2;margin-bottom:16px">📋 Nueva Incidencia</div>'
      +'<div style="margin-bottom:10px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Empleado *</label>'
      +'<select id="inc-emp" class="form-control" style="padding:10px"><option value="">Seleccionar...</option>'+empOpts+'</select></div>'
      +'<div style="margin-bottom:10px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Tipo *</label>'
      +'<select id="inc-tipo" class="form-control" style="padding:10px">'
      +'<option value="permiso_con_goce">Permiso con goce</option>'
      +'<option value="permiso_sin_goce">Permiso sin goce</option>'
      +'<option value="falta_justificada">Falta justificada</option>'
      +'<option value="falta_injustificada">Falta injustificada</option>'
      +'<option value="retardo">Retardo</option>'
      +'<option value="vacaciones">Vacaciones</option>'
      +'</select></div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px">'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Fecha inicio *</label>'
      +'<input type="date" id="inc-fecha" class="form-control" value="'+new Date().toISOString().substring(0,10)+'" style="padding:8px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Fecha fin</label>'
      +'<input type="date" id="inc-fecha-fin" class="form-control" style="padding:8px"></div>'
      +'<div><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Días</label>'
      +'<input type="number" id="inc-dias" class="form-control" min="1" value="1" style="padding:8px"></div>'
      +'</div>'
      +'<div style="margin-bottom:16px"><label style="font-size:.75rem;font-weight:700;color:#374151;display:block;margin-bottom:3px">Motivo / Nota</label>'
      +'<input type="text" id="inc-motivo" class="form-control" placeholder="Opcional" style="padding:10px"></div>'
      +'<div style="display:flex;gap:10px">'
      +'<button onclick="var m=document.getElementById(\'modal-incidencia\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
      +'<button onclick="guardarIncidencia()" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
      +'</div></div>';
    document.body.appendChild(modal);
  });
}

function guardarIncidencia(){
  var empId=document.getElementById('inc-emp').value;
  var tipo=document.getElementById('inc-tipo').value;
  var fecha=document.getElementById('inc-fecha').value;
  if(!empId||!tipo||!fecha){showAlert('Empleado, tipo y fecha son obligatorios','error');return;}
  var payload={
    empleado_id:empId, tipo:tipo, fecha:fecha,
    fecha_fin:document.getElementById('inc-fecha-fin').value||fecha,
    dias:parseInt(document.getElementById('inc-dias').value)||1,
    motivo:document.getElementById('inc-motivo').value.trim()||null
  };
  fetch(SUPA_URL+'/rest/v1/incidencias',{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=representation'},
    body:JSON.stringify(payload)
  }).then(function(r){
    if(r.ok){var m=document.getElementById('modal-incidencia');if(m)m.remove();showAlert('✅ Incidencia registrada');_renderIncidencias(document.getElementById('personal-content'));}
    else r.text().then(function(t){showAlert('⚠️ '+t.substring(0,80),'error');});
  });
}
// ── FIN GESTIÓN DE PERSONAL ──────────────────────────────────────


