function _renderContrasenas(lDiv){
  lDiv.innerHTML='<div style="text-align:center;padding:20px;color:#9ca3af">Cargando...</div>';
  var esAdmin=currentUser&&(currentUser.rol==='admin'||currentUser.rol==='super');
  var puedeAgregar=esAdmin||(currentUser&&currentUser.rol==='tecnico');
  supaFetch('contrasenas_equipo','GET',null,'order=equipo.asc').then(function(rows){
    var lista=rows||[];
    var html='';
    if(puedeAgregar){
      html+='<div style="display:flex;justify-content:flex-end;margin-bottom:10px">'
        +'<button onclick="abrirAgregarContrasena()" style="padding:8px 14px;background:#0891b2;color:#fff;border:none;border-radius:8px;font-size:.85rem;font-weight:700;cursor:pointer">+ Agregar</button>'
        +'</div>';
    }
    if(!lista.length){
      html+='<div class="card text-center" style="padding:32px"><div style="font-size:40px">🔑</div><div style="font-weight:700;margin-top:8px">Sin contraseñas registradas</div></div>';
    } else {
      // Tabla
      html+='<div style="overflow-x:auto">'
        +'<table style="width:100%;border-collapse:collapse;font-size:13px">'
        +'<thead><tr style="background:#1a3c5e;color:#fff">'
        +'<th style="padding:10px 12px;text-align:left;border-radius:8px 0 0 0">Equipo</th>'
        +'<th style="padding:10px 12px;text-align:left">Usuario</th>'
        +'<th style="padding:10px 12px;text-align:left">Contraseña</th>'
        +(esAdmin?'<th style="padding:10px 12px;border-radius:0 8px 0 0"></th>':'')
        +'</tr></thead><tbody>'
        +lista.map(function(r,i){
          return '<tr style="background:'+(i%2===0?'#fff':'#f9fafb')+';border-bottom:1px solid #e5e7eb">'
            +'<td style="padding:10px 12px;font-weight:700">'+r.equipo+'</td>'
            +'<td style="padding:10px 12px">'+r.usuario+'</td>'
            +'<td style="padding:10px 12px;font-family:monospace">'+r.contrasena+'</td>'
            +(esAdmin?'<td style="padding:8px"><button onclick="eliminarContrasena(\''+r.id+'\')" style="background:#fee2e2;color:#dc2626;border:none;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:.78rem">🗑️</button></td>':'')
            +'</tr>';
        }).join('')
        +'</tbody></table></div>';
    }
    lDiv.innerHTML=html;
  }).catch(function(){
    lDiv.innerHTML='<div class="card" style="padding:20px;color:#9ca3af;text-align:center">Crea la tabla contrasenas_equipo en Supabase primero.</div>';
  });
}

function abrirAgregarContrasena(){
  var modal=document.createElement('div');
  modal.id='modal-add-pass';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end;justify-content:center';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px 20px 32px;width:100%;max-width:480px">'
    +'<div style="font-size:17px;font-weight:800;font-family:Nunito,sans-serif;color:#1a3c5e;margin-bottom:16px">🔑 Agregar contraseña</div>'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Equipo</label>'
    +'<input type="text" id="pass-equipo" class="form-control" placeholder="Ej: PLC Línea 1, Router, PC..." style="margin-bottom:10px">'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Usuario</label>'
    +'<input type="text" id="pass-usuario" class="form-control" placeholder="Ej: admin, root..." style="margin-bottom:10px">'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">Contraseña</label>'
    +'<input type="text" id="pass-contrasena" class="form-control" placeholder="Contraseña..." style="margin-bottom:16px;font-family:monospace">'
    +'<div style="display:flex;gap:10px">'
    +'<button onclick="var m=document.getElementById(\'modal-add-pass\');if(m)m.remove()" style="flex:1;padding:13px;background:#f3f4f6;border:none;border-radius:11px;cursor:pointer">Cancelar</button>'
    +'<button onclick="guardarContrasena()" style="flex:2;padding:13px;background:#0891b2;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">💾 Guardar</button>'
    +'</div></div>';
  document.body.appendChild(modal);
}

async function guardarContrasena(){
  var eq=(document.getElementById('pass-equipo')||{}).value.trim();
  var us=(document.getElementById('pass-usuario')||{}).value.trim();
  var pw=(document.getElementById('pass-contrasena')||{}).value.trim();
  if(!eq||!us||!pw){showAlert('Completa todos los campos','error');return;}
  var r=await fetch(SUPA_URL+'/rest/v1/contrasenas_equipo',{
    method:'POST',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Content-Type':'application/json','Prefer':'return=minimal'},
    body:JSON.stringify({equipo:eq,usuario:us,contrasena:pw})
  });
  if(r.ok||r.status===201||r.status===204){
    var m=document.getElementById('modal-add-pass');if(m)m.remove();
    showAlert('✅ Contraseña guardada');
    _renderContrasenas(document.getElementById('personal-content'));
  } else {
    showAlert('Error al guardar','error');
  }
}

async function eliminarContrasena(id){
  if(!confirm('¿Eliminar esta contraseña?'))return;
  var r=await fetch(SUPA_URL+'/rest/v1/contrasenas_equipo?id=eq.'+id,{
    method:'DELETE',
    headers:{'apikey':SUPA_KEY,'Authorization':'Bearer '+SUPA_KEY,'Prefer':'return=minimal'}
  });
  if(r.ok||r.status===204){
    showAlert('Eliminada');
    _renderContrasenas(document.getElementById('personal-content'));
  } else {
    showAlert('Error al eliminar','error');
  }
}

// ================================================================
// FOTOS PM03 — Múltiples imágenes desde cámara o galería
// ================================================================
function pm3AgregarFotos(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p) return;
  if(!p.fotos) p.fotos=[];

  var modal=document.createElement('div');
  modal.id='modal-pm3-fotos';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:10000;display:flex;align-items:flex-end;justify-content:center';

  function renderFotosModal(){
    var previews=p.fotos.map(function(f,i){
      return'<div style="position:relative;display:inline-block;margin:4px">'
        +'<img src="'+f+'" style="width:80px;height:80px;object-fit:cover;border-radius:8px;border:2px solid #e5e7eb">'
        +'<button onclick="pm3EliminarFoto(\''+id+'\','+i+')" style="position:absolute;top:-6px;right:-6px;background:#dc2626;color:#fff;border:none;border-radius:50%;width:20px;height:20px;font-size:12px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1">×</button>'
        +'</div>';
    }).join('');

    modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px 20px 32px;width:100%;max-width:480px">'
      +'<div style="width:40px;height:4px;background:#e5e7eb;border-radius:2px;margin:0 auto 16px"></div>'
      +'<div style="font-size:16px;font-weight:800;color:#1a3c5e;margin-bottom:4px">📷 Fotos del protocolo</div>'
      +'<div style="font-size:12px;color:#6b7280;margin-bottom:16px">'+id+' · '+(p.fotos.length)+' foto(s)</div>'
      // Previews
      +(p.fotos.length?'<div style="margin-bottom:16px;min-height:88px">'+previews+'</div>':'<div style="background:#f9fafb;border-radius:10px;padding:20px;text-align:center;color:#9ca3af;margin-bottom:16px">Sin fotos aún</div>')
      // Botones agregar
      +'<input type="file" id="pm3-foto-input" accept="image/*" multiple style="display:none" onchange="pm3ProcesarFotos(\''+id+'\')">'
      +'<input type="file" id="pm3-camara-input" accept="image/*" capture="environment" style="display:none" onchange="pm3ProcesarFotos(\''+id+'\')">'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">'
      +'<button onclick="document.getElementById(\'pm3-camara-input\').click()" style="padding:12px;background:#e0f7fa;color:#0891b2;border:2px solid #0891b2;border-radius:11px;font-weight:700;cursor:pointer">📸 Cámara</button>'
      +'<button onclick="document.getElementById(\'pm3-foto-input\').click()" style="padding:12px;background:#f3f4f6;color:#374151;border:2px solid #e5e7eb;border-radius:11px;font-weight:700;cursor:pointer">🖼️ Galería</button>'
      +'</div>'
      +'<button onclick="document.getElementById(\'modal-pm3-fotos\').remove()" style="width:100%;padding:12px;background:#1a3c5e;color:#fff;border:none;border-radius:11px;font-weight:700;cursor:pointer">✅ Listo</button>'
      +'</div>';
  }

  document.body.appendChild(modal);
  renderFotosModal();
  window._pm3FotosRender=renderFotosModal;
}

function pm3ProcesarFotos(id){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p){p={id:id};} // fallback
  if(!p.fotos) p.fotos=[];

  // Leer archivos de ambos inputs
  var inputs=['pm3-foto-input','pm3-camara-input'];
  var archivos=[];
  inputs.forEach(function(inputId){
    var inp=document.getElementById(inputId);
    if(inp&&inp.files) Array.from(inp.files).forEach(function(f){archivos.push(f);});
  });

  if(!archivos.length) return;
  var procesados=0;
  archivos.forEach(function(file){
    var r=new FileReader();
    r.onload=function(e){
      var img=new Image();
      img.onload=function(){
        var M=1024;
        var w=img.width,h=img.height;
        if(w>M){h=Math.round(h*M/w);w=M;}
        if(h>M){w=Math.round(w*M/h);h=M;}
        var c=document.createElement('canvas');
        c.width=w;c.height=h;
        c.getContext('2d').drawImage(img,0,0,w,h);
        p.fotos.push(c.toDataURL('image/jpeg',.7));
        procesados++;
        if(procesados===archivos.length){
          // Guardar en localStorage y Supabase
          saveDB('pm03_plan',PM03_PLAN);
          savePM03Supa(p);
          showAlert('✅ '+archivos.length+' foto(s) guardada(s)');
          if(window._pm3FotosRender) window._pm3FotosRender();
        }
      };
      img.src=e.target.result;
    };
    r.readAsDataURL(file);
  });
}

function pm3EliminarFoto(id,idx){
  var p=PM03_PLAN.find(function(x){return x.id===id;});
  if(!p||!p.fotos) return;
  if(!confirm('¿Eliminar esta foto?')) return;
  p.fotos.splice(idx,1);
  saveDB('pm03_plan',PM03_PLAN);
  savePM03Supa(p);
  if(window._pm3FotosRender) window._pm3FotosRender();
}

