function mostrarPreguntaLimpieza(callback){
  var modal=document.createElement('div');
  modal.id='modal-limpieza-pm';
  modal.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-end';
  modal.innerHTML='<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;box-sizing:border-box">'
    +'<div style="font-family:Nunito,sans-serif;font-size:17px;font-weight:800;color:#92400e;margin-bottom:4px">🧹 ¿Se requiere limpieza?</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-bottom:16px">¿Después de la intervención el usuario debe limpiar el área?</div>'
    +'<div style="display:flex;gap:10px;margin-bottom:12px">'
    +'<button id="lp-si" onclick="lpToggle(true)" style="flex:1;padding:13px;border-radius:10px;border:2px solid #e5e7eb;background:#fff;font-weight:700;font-size:.9rem;cursor:pointer">✅ Sí</button>'
    +'<button id="lp-no" onclick="lpToggle(false)" style="flex:1;padding:13px;border-radius:10px;border:2px solid #e5e7eb;background:#fff;font-weight:700;font-size:.9rem;cursor:pointer">❌ No</button>'
    +'</div>'
    +'<div id="lp-aviso-wrap" style="display:none;margin-bottom:12px">'
    +'<label style="font-size:.8rem;font-weight:700;color:#374151;display:block;margin-bottom:4px">¿A quién se le avisó?</label>'
    +'<input type="text" id="lp-aviso" class="form-control" placeholder="Nombre del usuario avisado..." style="padding:11px">'
    +'</div>'
    +'<button onclick="lpConfirmar()" style="width:100%;padding:13px;background:#1a3c5e;color:#fff;border:none;border-radius:11px;font-weight:700;font-size:.95rem;cursor:pointer">💾 Continuar y Guardar</button>'
    +'</div>';
  document.body.appendChild(modal);
  window._lpCallback=callback;
  window._lpVal=null;
}

function lpToggle(val){
  window._lpVal=val;
  var si=document.getElementById('lp-si');
  var no=document.getElementById('lp-no');
  var wrap=document.getElementById('lp-aviso-wrap');
  if(si){si.style.background=val?'#d1fae5':'#fff';si.style.borderColor=val?'#16a34a':'#e5e7eb';}
  if(no){no.style.background=!val?'#fee2e2':'#fff';no.style.borderColor=!val?'#dc2626':'#e5e7eb';}
  if(wrap) wrap.style.display=val?'block':'none';
}

function lpConfirmar(){
  if(window._lpVal===null||window._lpVal===undefined){
    showAlert('Selecciona si se requiere limpieza','error');return;
  }
  if(window._lpVal===true){
    var av=document.getElementById('lp-aviso')?document.getElementById('lp-aviso').value.trim():'';
    if(!av){showAlert('Indica a quién se le avisó de la limpieza','error');return;}
    pmState.limpiezaRequerida=true;
    pmState.limpiezaAvisadoA=av;
  } else {
    pmState.limpiezaRequerida=false;
    pmState.limpiezaAvisadoA='';
  }
  var m=document.getElementById('modal-limpieza-pm');if(m)m.remove();
  if(window._lpCallback) window._lpCallback();
}
// ── FIN LIMPIEZA ─────────────────────────────────────────────────

function confirmarResolucion_temp(){
  calcResTime();
  var fEl=document.getElementById('pm-fecha-orden');
  var fecha=fEl&&fEl.value?fEl.value:pmState.fechaTrabajo||todayStr();
  pmState.fechaTrabajo=fecha;
  var horaIni=pmState.horaInicioTrabajo||'00:00';
  pmState._tsOrden=new Date(fecha+'T'+horaIni+':00').getTime();
  pmState._semOrden=getWeekNumber(new Date(fecha+'T12:00:00'));
  pmState._añoOrden=new Date(fecha+'T12:00:00').getFullYear();
  var ini=document.getElementById('res-ini');
  var fin=document.getElementById('res-fin');
  if(ini&&fin&&ini.value&&fin.value){
    var parts1=ini.value.split(':').map(Number);
    var parts2=fin.value.split(':').map(Number);
    var mins=(parts2[0]*60+parts2[1])-(parts1[0]*60+parts1[1]);
    if(mins<0)mins+=1440;
    pmState.horasCierre=parseFloat((mins/60).toFixed(2));
  }
  if(!pmState.horasCierre||pmState.horasCierre<=0){showAlert('Verifica hora inicio y fin','error');return;}
  // Leer limpieza del campo inline
  if(window._resLimp===null||window._resLimp===undefined){
    showAlert('Indica si se requiere limpieza','error');return;
  }
  if(window._resLimp===true){
    var avT=document.getElementById('res-limp-aviso')?document.getElementById('res-limp-aviso').value.trim():'';
    if(!avT){showAlert('Indica a quién se le avisó de la limpieza','error');return;}
    pmState.limpiezaRequerida=true;
    pmState.limpiezaAvisadoA=avT;
  } else {
    pmState.limpiezaRequerida=false;
    pmState.limpiezaAvisadoA='';
  }
  window._resLimp=null;
  guardarRessueltaTemporalmente();
}

function resLimpToggle(val){
  window._resLimp=val;
  var si=document.getElementById('res-limp-si');
  var no=document.getElementById('res-limp-no');
  var wrap=document.getElementById('res-limp-aviso-wrap');
  if(si){si.style.background=val?'#d1fae5':'#fff';si.style.borderColor=val?'#16a34a':'#e5e7eb';}
  if(no){no.style.background=!val?'#fee2e2':'#fff';no.style.borderColor=!val?'#dc2626':'#e5e7eb';}
  if(wrap) wrap.style.display=val?'block':'none';
}

